import { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-lg">
        <h1 className="text-3xl font-bold text-center mb-6">Contador</h1>

        <div className="flex items-center justify-center gap-4 mb-6">
          <button
            onClick={() => setCount(count - 1)}
            className="bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-4 rounded text-xl"
          >
            -
          </button>

          <span className="text-4xl font-bold min-w-[60px] text-center">
            {count}
          </span>

          <button
            onClick={() => setCount(count + 1)}
            className="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-4 rounded text-xl"
          >
            +
          </button>
        </div>

        <div className="text-center mb-4">
          <p className="text-lg text-gray-700">
            El doble es <span className="font-bold">{count * 2}</span>
          </p>
        </div>

        {count > 5 && (
          <div className="text-center">
            <p className="text-lg font-bold text-blue-600">¡Más de 5!</p>
          </div>
        )}
      </div>
    </div>
  );
}

