model Task {
  id: ID
  title: String
  completed: Bool = false
}

component TaskItem(task: Task, onDelete: Fn, onToggle: Fn) {
  row gap=2 align=center pad=2 {
    checkbox task.completed -> onToggle()
    text task.title muted=task.completed
    button "×" small -> onDelete()
  }
}

page App "/" {
  state newTask = ""
  state tasks: Task[] = []

  fn addTask() {
    if newTask.trim() == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: newTask, completed: false })
    newTask = ""
  }

  fn deleteTask(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  fn toggleTask(id) {
    let task = tasks.find(t => t.id == id)
    if task {
      task.completed = !task.completed
    }
  }

  computed pending = tasks.filter(t => !t.completed).length

  column gap=4 pad=4 {
    title "Mi lista de tareas"
    row gap=2 {
      input newTask placeholder="¿Qué hay que hacer?" -> addTask()
      button "Agregar" primary -> addTask()
    }
    column gap=2 {
      for t in tasks key t.id {
        TaskItem task=t onDelete=(() => deleteTask(t.id)) onToggle=(() => toggleTask(t.id))
      }
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted small
    }
  }
}

