import React, { useState } from 'react';

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

const TaskItem: React.FC<{
  task: Task;
  onToggle: (id: number) => void;
  onDelete: (id: number) => void;
}> = ({ task, onToggle, onDelete }) => {
  return (
    <div className="flex items-center gap-3 p-3 bg-white border border-gray-200 rounded-lg hover:shadow-md transition-shadow">
      <input
        type="checkbox"
        checked={task.completed}
        onChange={() => onToggle(task.id)}
        className="w-5 h-5 cursor-pointer text-blue-600 rounded focus:ring-2 focus:ring-blue-500"
      />
      <span
        className={`flex-1 text-lg transition-all ${
          task.completed
            ? 'line-through text-gray-400'
            : 'text-gray-800'
        }`}
      >
        {task.title}
      </span>
      <button
        onClick={() => onDelete(task.id)}
        className="w-8 h-8 flex items-center justify-center text-red-500 hover:bg-red-50 rounded-full transition-colors font-bold text-xl"
      >
        ×
      </button>
    </div>
  );
};

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [input, setInput] = useState('');

  const addTask = () => {
    if (input.trim() === '') return;

    const newTask: Task = {
      id: Date.now(),
      title: input,
      completed: false,
    };

    setTasks([...tasks, newTask]);
    setInput('');
  };

  const toggleTask = (id: number) => {
    setTasks(
      tasks.map((task) =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const deleteTask = (id: number) => {
    setTasks(tasks.filter((task) => task.id !== id));
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      addTask();
    }
  };

  const pendingCount = tasks.filter((task) => !task.completed).length;

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-lg shadow-lg p-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-8 text-center">
            Mi Lista de Tareas
          </h1>

          <div className="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="¿Qué hay que hacer?"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={handleKeyPress}
              className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
            <button
              onClick={addTask}
              className="px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 transition-colors"
            >
              Agregar
            </button>
          </div>

          <div className="space-y-2 mb-6">
            {tasks.length === 0 ? (
              <p className="text-center text-gray-400 py-8 text-lg">
                No hay tareas
              </p>
            ) : (
              tasks.map((task) => (
                <TaskItem
                  key={task.id}
                  task={task}
                  onToggle={toggleTask}
                  onDelete={deleteTask}
                />
              ))
            )}
          </div>

          {tasks.length > 0 && (
            <div className="text-center text-gray-600 font-medium">
              {pendingCount === 0
                ? '¡Todas completadas!'
                : `${pendingCount} ${pendingCount === 1 ? 'tarea pendiente' : 'tareas pendientes'}`}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

