import { useState } from 'react';

export default function App() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const isEmailValid = email.includes('@');
  const isPasswordValid = password.length >= 8;
  const isFormValid = isEmailValid && isPasswordValid;

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (isFormValid) {
      setIsLoggedIn(true);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
      <div className="bg-white rounded-lg shadow-2xl p-8 w-full max-w-md">
        {isLoggedIn ? (
          <div className="text-center">
            <h2 className="text-3xl font-bold text-gray-800 mb-4">
              Bienvenido, <span className="text-blue-600">{email}</span>
            </h2>
            <button
              onClick={() => {
                setIsLoggedIn(false);
                setEmail('');
                setPassword('');
              }}
              className="mt-6 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-6 rounded-lg transition duration-200"
            >
              Cerrar Sesión
            </button>
          </div>
        ) : (
          <div>
            <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">
              Login
            </h1>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                  Email
                </label>
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="tu@email.com"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                {email && !isEmailValid && (
                  <p className="text-red-500 text-sm mt-1">El email debe contener @</p>
                )}
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-2">
                  Contraseña
                </label>
                <input
                  id="password"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Mínimo 8 caracteres"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                {password && !isPasswordValid && (
                  <p className="text-red-500 text-sm mt-1">
                    La contraseña debe tener al menos 8 caracteres
                  </p>
                )}
              </div>

              <button
                type="submit"
                disabled={!isFormValid}
                className={`w-full py-2 px-4 rounded-lg font-semibold transition duration-200 ${
                  isFormValid
                    ? 'bg-blue-600 hover:bg-blue-700 text-white cursor-pointer'
                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
              >
                Entrar
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}

