model Product {
  id: ID
  name: String
  price: Number
}

component ProductCard(product: Product, onAdd: Fn) {
  button `${product.name} - $${product.price.toFixed(2)}` primary -> onAdd(product)
}

component CartItem(product: Product, quantity: Number, onIncrease: Fn, onDecrease: Fn) {
  row gap=2 align=center {
    text `${product.name}`
    button "-" small -> onDecrease(product.id)
    text `${quantity}` bold
    button "+" small -> onIncrease(product.id)
    text `$${(product.price * quantity).toFixed(2)}` muted
  }
}

page Shop "/" {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 },
    { id: "2", name: "Mouse", price: 29.99 },
    { id: "3", name: "Keyboard", price: 79.99 }
  ]

  state cart: {id: String, quantity: Number}[] = []

  computed total = cart.reduce((sum, item) => {
    let product = products.find(p => p.id == item.id)
    return sum + (product ? product.price * item.quantity : 0)
  }, 0)

  fn addToCart(product) {
    let existing = cart.find(item => item.id == product.id)
    if existing {
      existing.quantity++
    } else {
      cart.push({ id: product.id, quantity: 1 })
    }
  }

  fn increaseQuantity(productId) {
    let item = cart.find(i => i.id == productId)
    if item {
      item.quantity++
    }
  }

  fn decreaseQuantity(productId) {
    let item = cart.find(i => i.id == productId)
    if item {
      item.quantity--
      if item.quantity == 0 {
        cart = cart.filter(i => i.id != productId)
      }
    }
  }

  column gap=6 pad=4 {
    column gap=4 {
      title "Shop"
      column gap=2 {
        for p in products {
          ProductCard product=p onAdd=addToCart
        }
      }
    }

    column gap=4 {
      title "Shopping Cart"
      if cart.length == 0 {
        text "Your cart is empty" muted
      } else {
        column gap=2 {
          for item in cart {
            let product = products.find(p => p.id == item.id)
            if product {
              CartItem product=product quantity=item.quantity onIncrease=increaseQuantity onDecrease=decreaseQuantity
            }
          }
        }
        divider
        row justify=end gap=2 {
          text "Total:" bold large
          text `$${total.toFixed(2)}` bold large primary
        }
      }
    }
  }
}

