import { createSignal, createMemo } from 'solid-js';
import ProductList from './ProductList';
import Cart from './Cart';

interface CartItem {
  id: number;
  nombre: string;
  precio: number;
  cantidad: number;
}

export default function App() {
  const [cartItems, setCartItems] = createSignal<CartItem[]>([]);

  const products = [
    { id: 1, nombre: 'Laptop', precio: 999.99 },
    { id: 2, nombre: 'Mouse', precio: 29.99 },
    { id: 3, nombre: 'Teclado', precio: 79.99 },
  ];

  const addToCart = (product: typeof products[0]) => {
    setCartItems((items) => {
      const existing = items.find((item) => item.id === product.id);
      if (existing) {
        return items.map((item) =>
          item.id === product.id ? { ...item, cantidad: item.cantidad + 1 } : item
        );
      }
      return [...items, { ...product, cantidad: 1 }];
    });
  };

  const removeFromCart = (id: number) => {
    setCartItems((items) => items.filter((item) => item.id !== id));
  };

  const updateQuantity = (id: number, cantidad: number) => {
    if (cantidad <= 0) {
      removeFromCart(id);
    } else {
      setCartItems((items) =>
        items.map((item) => (item.id === id ? { ...item, cantidad } : item))
      );
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 p-8">
      <div class="max-w-6xl mx-auto">
        <h1 class="text-4xl font-bold text-gray-800 mb-8">Tienda Online</h1>
        <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div class="lg:col-span-2">
            <ProductList products={products} onAddToCart={addToCart} />
          </div>
          <div>
            <Cart
              items={cartItems()}
              onUpdateQuantity={updateQuantity}
              onRemove={removeFromCart}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

