import { createSignal, createMemo } from 'solid-js';
import ProductList from './ProductList';
import Cart from './Cart';

export default function App() {
  const [cartItems, setCartItems] = createSignal<Map<number, number>>(new Map());

  const products = [
    { id: 1, nombre: 'Laptop', precio: 999.99 },
    { id: 2, nombre: 'Mouse', precio: 29.99 },
    { id: 3, nombre: 'Teclado', precio: 79.99 },
  ];

  const addToCart = (productId: number) => {
    setCartItems((prev) => {
      const newCart = new Map(prev);
      newCart.set(productId, (newCart.get(productId) ?? 0) + 1);
      return newCart;
    });
  };

  const updateQuantity = (productId: number, quantity: number) => {
    setCartItems((prev) => {
      const newCart = new Map(prev);
      if (quantity <= 0) {
        newCart.delete(productId);
      } else {
        newCart.set(productId, quantity);
      }
      return newCart;
    });
  };

  const total = createMemo(() => {
    let sum = 0;
    cartItems().forEach((quantity, productId) => {
      const product = products.find((p) => p.id === productId);
      if (product) {
        sum += product.precio * quantity;
      }
    });
    return sum.toFixed(2);
  });

  return (
    <div class="min-h-screen bg-gray-100 p-8">
      <div class="max-w-6xl mx-auto">
        <h1 class="text-4xl font-bold text-gray-800 mb-8">Tienda Online</h1>
        <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div class="lg:col-span-2">
            <ProductList products={products} onAddToCart={addToCart} />
          </div>
          <div>
            <Cart
              products={products}
              cartItems={cartItems}
              onUpdateQuantity={updateQuantity}
              total={total}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

