import { useState } from 'react';

export default function App() {
  const [activeTab, setActiveTab] = useState('perfil');

  const tabContent = {
    perfil: 'Bienvenido a tu perfil. Aquí puedes ver tu información personal y datos de cuenta.',
    ajustes: 'En esta sección puedes configurar tus preferencias, privacidad y opciones generales.',
    ayuda: 'Centro de ayuda. Encuentra respuestas a preguntas frecuentes y contacta con soporte.',
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto bg-white rounded-lg shadow-lg p-8">
        <h1 className="text-4xl font-bold text-gray-800 mb-8">Mi Cuenta</h1>

        <div className="flex gap-4 mb-8">
          {(['perfil', 'ajustes', 'ayuda'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-6 py-3 font-semibold rounded-lg transition-all duration-200 ${
                activeTab === tab
                  ? 'bg-indigo-600 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </div>

        <div className="p-6 bg-gray-50 rounded-lg border-2 border-indigo-200">
          <p className="text-gray-700 text-lg leading-relaxed">
            {tabContent[activeTab as keyof typeof tabContent]}
          </p>
        </div>
      </div>
    </div>
  );
}

