import React, { useState, useEffect } from 'react';

interface Usuario {
  id: string;
  nombre: string;
  email: string;
}

interface ErrorResponse {
  error: string;
}

export default function App() {
  const [usuarios, setUsuarios] = useState<Usuario[]>([]);
  const [nombre, setNombre] = useState('');
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarUsuarios();
  }, []);

  const cargarUsuarios = async () => {
    try {
      setLoading(true);
      const res = await fetch('/api/usuarios');
      if (!res.ok) throw new Error('Error al cargar usuarios');
      const data = await res.json();
      setUsuarios(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const agregarUsuario = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!nombre.trim()) {
      setError('El nombre es requerido');
      return;
    }

    if (!email.trim()) {
      setError('El email es requerido');
      return;
    }

    try {
      const res = await fetch('/api/usuarios', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nombre, email }),
      });

      const data = await res.json() as Usuario | ErrorResponse;

      if (!res.ok) {
        const errorData = data as ErrorResponse;
        setError(errorData.error || 'Error al crear usuario');
        return;
      }

      const nuevoUsuario = data as Usuario;
      setUsuarios([...usuarios, nuevoUsuario]);
      setNombre('');
      setEmail('');
      setError('');
    } catch (err) {
      setError('Error al crear usuario');
      console.error(err);
    }
  };

  const borrarUsuario = async (id: string) => {
    try {
      const res = await fetch(`/api/usuarios/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Error al borrar usuario');
      setUsuarios(usuarios.filter((u) => u.id !== id));
    } catch (err) {
      console.error(err);
      setError('Error al borrar usuario');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-100">
        <div className="text-lg text-gray-600">Cargando...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 py-8 px-4">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8 text-center">
          Gestor de Usuarios
        </h1>

        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <form onSubmit={agregarUsuario} className="space-y-4">
            <div>
              <input
                type="text"
                placeholder="Nombre"
                value={nombre}
                onChange={(e) => setNombre(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
              <input
                type="text"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            {error && (
              <div className="text-red-600 text-sm font-semibold">{error}</div>
            )}
            <button
              type="submit"
              className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-lg transition duration-200"
            >
              Agregar
            </button>
          </form>
        </div>

        <div className="space-y-4">
          {usuarios.length === 0 ? (
            <div className="text-center text-gray-500 py-8">
              No hay usuarios registrados
            </div>
          ) : (
            usuarios.map((usuario) => (
              <div
                key={usuario.id}
                className="bg-white rounded-lg shadow-md p-4 flex justify-between items-center"
              >
                <div>
                  <p className="text-lg font-semibold text-gray-800">
                    {usuario.nombre}
                  </p>
                  <p className="text-gray-600">{usuario.email}</p>
                </div>
                <button
                  onClick={() => borrarUsuario(usuario.id)}
                  className="bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-4 rounded-lg transition duration-200"
                >
                  Borrar
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

