import { createServer, IncomingMessage, ServerResponse } from 'node:http';

interface Usuario {
  id: string;
  nombre: string;
  email: string;
}

const usuarios: Usuario[] = [];

function isValidEmail(email: string): boolean {
  const atIndex = email.indexOf('@');
  return atIndex > 0 && atIndex < email.length - 1;
}

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        resolve(JSON.parse(body));
      } catch (err) {
        reject(err);
      }
    });

    req.on('error', reject);
  });
}

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  try {
    if (pathname === '/api/usuarios' && req.method === 'GET') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(usuarios));
      return;
    }

    if (pathname === '/api/usuarios' && req.method === 'POST') {
      const { nombre, email } = await parseBody(req);

      if (!nombre || !email) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Nombre y email son requeridos' }));
        return;
      }

      if (!isValidEmail(email)) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Email inválido' }));
        return;
      }

      const nuevoUsuario: Usuario = {
        id: Math.random().toString(36).substr(2, 9),
        nombre,
        email,
      };

      usuarios.push(nuevoUsuario);

      res.writeHead(201, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(nuevoUsuario));
      return;
    }

    if (pathname.startsWith('/api/usuarios/') && req.method === 'DELETE') {
      const id = pathname.split('/').pop();
      const index = usuarios.findIndex((u) => u.id === id);

      if (index === -1) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Usuario no encontrado' }));
        return;
      }

      usuarios.splice(index, 1);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true }));
      return;
    }

    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Ruta no encontrada' }));
  } catch (err) {
    console.error(err);
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Error al procesar la solicitud' }));
  }
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

