import { createServer, IncomingMessage, ServerResponse } from 'node:http';

interface Usuario {
  id: string;
  nombre: string;
  email: string;
}

let usuarios: Usuario[] = [];
let nextId = 1;

const PORT = process.env.PORT || 3000;

const parseUrl = (url: string) => {
  const urlObj = new URL(url, `http://localhost`);
  return {
    pathname: urlObj.pathname,
    searchParams: urlObj.searchParams,
  };
};

const parseBody = async (req: IncomingMessage): Promise<string> => {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      resolve(body);
    });
    req.on('error', reject);
  });
};

const sendJson = (res: ServerResponse, statusCode: number, data: unknown) => {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
};

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  const { pathname } = parseUrl(req.url || '');

  // GET /api/usuarios
  if (req.method === 'GET' && pathname === '/api/usuarios') {
    sendJson(res, 200, usuarios);
    return;
  }

  // POST /api/usuarios
  if (req.method === 'POST' && pathname === '/api/usuarios') {
    try {
      const body = await parseBody(req);
      const { nombre, email } = JSON.parse(body);

      if (!nombre || !email || !email.includes('@')) {
        sendJson(res, 400, { error: 'Email inválido o datos incompletos' });
        return;
      }

      const nuevoUsuario: Usuario = {
        id: String(nextId++),
        nombre,
        email,
      };

      usuarios.push(nuevoUsuario);
      sendJson(res, 201, nuevoUsuario);
    } catch (err) {
      sendJson(res, 400, { error: 'Error procesando solicitud' });
    }
    return;
  }

  // DELETE /api/usuarios/:id
  if (req.method === 'DELETE' && pathname.startsWith('/api/usuarios/')) {
    const id = pathname.split('/').pop();
    const index = usuarios.findIndex((u) => u.id === id);

    if (index === -1) {
      sendJson(res, 404, { error: 'Usuario no encontrado' });
      return;
    }

    usuarios.splice(index, 1);
    sendJson(res, 200, { message: 'Usuario eliminado' });
    return;
  }

  sendJson(res, 404, { error: 'Ruta no encontrada' });
});

server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

import * as http from 'node:http';
import { randomUUID } from 'node:crypto';

interface User {
	id: string;
	name: string;
	email: string;
}

const users: Map<string, User> = new Map();

const server = http.createServer((req, res) => {
	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

	if (req.method === 'OPTIONS') {
		res.writeHead(204);
		res.end();
		return;
	}

	if (req.url?.startsWith('/api/users')) {
		if (req.method === 'GET' && req.url === '/api/users') {
			handleGetUsers(res);
		} else if (req.method === 'POST' && req.url === '/api/users') {
			handlePostUser(req, res);
		} else if (req.method === 'DELETE' && req.url?.match(/^\/api\/users\/[^/]+$/)) {
			const id = req.url.split('/').pop()!;
			handleDeleteUser(id, res);
		} else {
			res.writeHead(404, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify({ message: 'Not found' }));
		}
	} else {
		res.writeHead(404, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify({ message: 'Not found' }));
	}
});

function handleGetUsers(res: http.ServerResponse) {
	res.writeHead(200, { 'Content-Type': 'application/json' });
	res.end(JSON.stringify(Array.from(users.values())));
}

function handlePostUser(req: http.IncomingMessage, res: http.ServerResponse) {
	let body = '';

	req.on('data', (chunk) => {
		body += chunk.toString();
	});

	req.on('end', () => {
		try {
			const { name, email } = JSON.parse(body);

			if (!name || !email) {
				res.writeHead(400, { 'Content-Type': 'application/json' });
				res.end(JSON.stringify({ message: 'Name and email are required' }));
				return;
			}

			if (!email.includes('@')) {
				res.writeHead(400, { 'Content-Type': 'application/json' });
				res.end(JSON.stringify({ message: 'Email inválido' }));
				return;
			}

			const id = randomUUID();
			const user: User = { id, name, email };
			users.set(id, user);

			res.writeHead(201, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify(user));
		} catch {
			res.writeHead(400, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify({ message: 'Invalid JSON' }));
		}
	});
}

function handleDeleteUser(id: string, res: http.ServerResponse) {
	if (users.has(id)) {
		users.delete(id);
		res.writeHead(200, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify({ message: 'User deleted' }));
	} else {
		res.writeHead(404, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify({ message: 'User not found' }));
	}
}

const port = process.env.PORT || 3000;
server.listen(port, () => {
	console.log(`Server running on port ${port}`);
});

