import { createSignal, createEffect, For, Show } from 'solid-js';

interface User {
  id: string;
  name: string;
  email: string;
}

export default function App() {
  const [users, setUsers] = createSignal<User[]>([]);
  const [name, setName] = createSignal('');
  const [email, setEmail] = createSignal('');
  const [error, setError] = createSignal('');

  createEffect(() => {
    fetchUsers();
  });

  const fetchUsers = async () => {
    try {
      const response = await fetch('/api/users');
      const data = await response.json();
      setUsers(data);
    } catch (err) {
      console.error('Error fetching users:', err);
    }
  };

  const validateEmail = (emailStr: string): boolean => {
    return emailStr.includes('@');
  };

  const handleAddUser = async () => {
    setError('');

    if (!name().trim()) {
      setError('Por favor ingresá un nombre');
      return;
    }

    if (!validateEmail(email())) {
      setError('Email inválido');
      return;
    }

    try {
      const response = await fetch('/api/users', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: name().trim(),
          email: email().trim(),
        }),
      });

      if (response.ok) {
        setName('');
        setEmail('');
        await fetchUsers();
      } else {
        setError('Error al crear el usuario');
      }
    } catch (err) {
      setError('Error al crear el usuario');
      console.error(err);
    }
  };

  const handleDeleteUser = async (id: string) => {
    try {
      const response = await fetch(`/api/users/${id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        await fetchUsers();
      } else {
        setError('Error al eliminar el usuario');
      }
    } catch (err) {
      setError('Error al eliminar el usuario');
      console.error(err);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 py-8 px-4">
      <div class="max-w-2xl mx-auto">
        <h1 class="text-4xl font-bold text-gray-900 mb-8 text-center">
          Gestor de Usuarios
        </h1>

        <div class="bg-white rounded-lg shadow-md p-6 mb-8">
          <div class="space-y-4">
            <input
              type="text"
              placeholder="Nombre"
              value={name()}
              onInput={(e) => setName(e.target.value)}
              class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <input
              type="email"
              placeholder="Email"
              value={email()}
              onInput={(e) => setEmail(e.target.value)}
              class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />

            <Show when={error()}>
              <div class="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
                {error()}
              </div>
            </Show>

            <button
              onClick={handleAddUser}
              class="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-lg transition duration-200"
            >
              Agregar
            </button>
          </div>
        </div>

        <div class="space-y-4">
          <Show when={users().length > 0} fallback={
            <div class="text-center text-gray-500 py-8">
