import { createServer } from 'node:http';
import { URL } from 'node:url';

interface User {
  id: string;
  name: string;
  email: string;
}

const users: Map<string, User> = new Map();

const generateId = (): string => {
  return Math.random().toString(36).substring(2, 9);
};

const parseBody = (req: any): Promise<string> => {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk: Buffer) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      resolve(body);
    });
    req.on('error', reject);
  });
};

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // GET /api/users - get all users
  if (pathname === '/api/users' && req.method === 'GET') {
    const usersList = Array.from(users.values());
    res.writeHead(200);
    res.end(JSON.stringify(usersList));
    return;
  }

  // POST /api/users - create new user
  if (pathname === '/api/users' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const { name, email } = JSON.parse(body);

      if (!email || !email.includes('@')) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email inválido' }));
        return;
      }

      if (!name || !name.trim()) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'El nombre es requerido' }));
        return;
      }

      const id = generateId();
      const newUser: User = { id, name: name.trim(), email: email.trim() };
      users.set(id, newUser);

      res.writeHead(201);
      res.end(JSON.stringify(newUser));
    } catch (err) {
      res.writeHead(400);
      res.end(JSON.stringify({ error: 'Error al procesar la solicitud' }));
    }
    return;
  }

  // DELETE /api/users/:id - delete user
  if (pathname.startsWith('/api/users/') && req.method === 'DELETE') {
    const id = pathname.substring('/api/users/'.length);

    if (users.has(id)) {
      users.delete(id);
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Usuario no encontrado' }));
    }
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Ruta no encontrada' }));
});

