model ShoppingItem {
  id: ID
  name: String min=1
  purchased: Bool = false
}

api shoppingItems: ShoppingItem

page ShoppingList "/" {
  state newItem = ""
  data items = api.shoppingItems.list() live

  computed pending = items.filter(i => !i.purchased).length

  fn addItem() {
    if newItem.trim() == "" { return }
    api.shoppingItems.create({ name: newItem, purchased: false })
    newItem = ""
  }

  fn togglePurchased(item) {
    api.shoppingItems.update(item.id, { purchased: !item.purchased })
  }

  fn deleteItem(id) {
    api.shoppingItems.remove(id)
  }

  column gap=4 pad=6 {
    title "Lista de Compras"

    text `${pending} por comprar` muted

    row gap=2 {
      input newItem placeholder="Producto" -> addItem()
      button "Agregar" primary -> addItem()
