model Item {
  id: ID
  name: String min=1 max=100
  completed: Bool = false
}

api items: Item

page ShoppingList "/" {
  state newItem = ""
  data items = api.items.list()

  fn addItem() {
    if newItem.trim() == "" { return }
    api.items.create({ name: newItem })
    newItem = ""
    items.reload()
  }

  fn markCompleted(id) {
    api.items.update(id, { completed: true })
    items.reload()
  }

  fn deleteItem(id) {
    api.items.remove(id)
    items.reload()
  }

  computed pendingCount = items.filter(i => !i.completed).length

  column gap=4 pad=4 {
    title `${pendingCount} por comprar`

    row gap=2 {
      input newItem placeholder="Producto"
      button "Agregar" primary -> addItem()
    }

    if items.loading {
      spinner
    } else if items.length == 0 {
      text "Sin ítems" muted
    } else {
      column gap=2 {
        for item in items {
          row gap=3 align=center {
            if item.completed {
              text `✓ ${item.name}` muted
            } else {
              text item.name
            }

            if !item.completed {
              button "Comprado" small -> markCompleted(item.id)
