            {items.length === 0 ? (
              <p className="text-center text-gray-500 py-8">No hay items en la lista</p>
            ) : (
              items.map((item) => (
                <div
                  key={item.id}
                  className="flex items-center gap-3 p-4 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors duration-150"
                >
                  <button
                    onClick={() => handleToggleCompleted(item.id)}
                    className={`flex-shrink-0 w-10 h-10 rounded-lg font-bold text-lg transition-all duration-200 ${
                      item.completed
                        ? 'bg-green-500 text-white'
                        : 'bg-gray-300 text-gray-600 hover:bg-green-500 hover:text-white'
                    }`}
                  >
                    {item.completed ? '✓' : '○'}
                  </button>
