                    className={`flex-1 text-lg ${
                      item.completed
                        ? 'line-through text-gray-500'
                        : 'text-gray-800 font-medium'
                    }`}
                  >
                    {item.name}
                  </span>
                  <button
                    onClick={() => handleDelete(item.id)}
                    className="flex-shrink-0 px-4 py-2 bg-red-500 text-white font-semibold rounded-lg hover:bg-red-600 transition-colors duration-200 active:scale-95"
                  >
                    Borrar
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

