import { createServer, IncomingMessage, ServerResponse } from 'node:http'
import { URL } from 'node:url'

interface Item {
  id: number
  name: string
  purchased: boolean
}

let items: Item[] = []
let nextId = 1

const parseJson = async (req: IncomingMessage): Promise<any> => {
  return new Promise((resolve, reject) => {
    let body = ''
    req.on('data', (chunk) => {
      body += chunk.toString()
    })
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {})
      } catch (e) {
        reject(e)
      }
    })
    req.on('error', reject)
  })
}

const sendJson = (res: ServerResponse, status: number, data: any) => {
  res.writeHead(status, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(data))
}

const handleApiRequest = async (
  req: IncomingMessage,
  res: ServerResponse,
  pathname: string,
  method: string
) => {
  // GET /api/items
  if (pathname === '/api/items' && method === 'GET') {
    sendJson(res, 200, items)
    return
  }

  // POST /api/items
  if (pathname === '/api/items' && method === 'POST') {
    try {
      const body = await parseJson(req)
      if (!body.name || typeof body.name !== 'string') {
        sendJson(res, 400, { error: 'Invalid item name' })
        return
      }
      const newItem: Item = {
        id: nextId++,
        name: body.name,
        purchased: false
      }
      items.push(newItem)
      sendJson(res, 201, newItem)
    } catch (error) {
      sendJson(res, 400, { error: 'Invalid JSON' })
    }
    return
  }

  // PATCH /api/items/:id
  if (pathname.startsWith('/api/items/') && method === 'PATCH') {
    const idStr = pathname.split('/')[3]
    const id = parseInt(idStr, 10)
    try {
      const body = await parseJson(req)
      const item = items.find((i) => i.id === id)
      if (!item) {
        sendJson(res, 404, { error: 'Item not found' })
        return
      }
      if (typeof body.purchased === 'boolean') {
        item.purchased = body.purchased
      }
      sendJson(res, 200, item)
    } catch (error) {
      sendJson(res, 400, { error: 'Invalid JSON' })
    }
    return
  }

  // DELETE /api/items/:id
  if (pathname.startsWith('/api/items/') && method === 'DELETE') {
    const idStr = pathname.split('/')[3]
    const id = parseInt(idStr, 10)
    const index = items.findIndex((i) => i.id === id)
    if (index === -1) {
      sendJson(res, 404, { error: 'Item not found' })
      return
    }
    items.splice(index, 1)
    sendJson(res, 204, null)
    return
  }

  sendJson(res, 404, { error: 'Not found' })
}

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*')
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS')
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type')

  if (req.method === 'OPTIONS') {
    res.writeHead(204)
    res.end()
    return
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`)
  const pathname = url.pathname
  const method = req.method || 'GET'

  if (pathname.startsWith('/api/')) {
    await handleApiRequest(req, res, pathname, method)
  } else {
    sendJson(res, 404, { error: 'Not found' })
  }
})

const PORT = process.env.PORT || 3000
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`)
})

