import { createSignal, createMemo, For, Show } from 'solid-js';

interface ShoppingItem {
  id: string;
  name: string;
  purchased: boolean;
}

export default function App() {
  const [items, setItems] = createSignal<ShoppingItem[]>([]);
  const [input, setInput] = createSignal('');
  const [loading, setLoading] = createSignal(true);

  // Cargar items al montar
  createMemo(async () => {
    try {
      const res = await fetch('/api/items');
      const data = await res.json();
      setItems(data);
    } catch (e) {
      console.error('Error cargando items:', e);
    } finally {
      setLoading(false);
    }
  });

  const pendingCount = createMemo(() => {
    return items().filter(item => !item.purchased).length;
  });

  const handleAdd = async () => {
    const name = input().trim();
    if (!name) return;

    try {
      const res = await fetch('/api/items', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name })
      });
      const newItem = await res.json();
      setItems([...items(), newItem]);
      setInput('');
    } catch (e) {
      console.error('Error agregando item:', e);
    }
  };

  const handleTogglePurchased = async (id: string, purchased: boolean) => {
    try {
      const res = await fetch(`/api/items/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ purchased: !purchased })
      });
      const updated = await res.json();
      setItems(items().map(item => item.id === id ? updated : item));
    } catch (e) {
      console.error('Error actualizando item:', e);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await fetch(`/api/items/${id}`, { method: 'DELETE' });
      setItems(items().filter(item => item.id !== id));
    } catch (e) {
      console.error('Error borrando item:', e);
    }
  };

  const handleKeyPress = (e: KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleAdd();
    }
  };

  return (
    <div class="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div class="max-w-2xl mx-auto">
        <div class="bg-white rounded-lg shadow-lg p-8">
          <h1 class="text-4xl font-bold text-gray-800 mb-2">Lista de Compras</h1>

          <Show when={!loading()}>
            <div class="mb-6 p-4 bg-indigo-50 rounded-lg border-l-4 border-indigo-500">
              <p class="text-lg font-semibold text-indigo-700">
                {pendingCount()} por comprar
              </p>
            </div>

            <div class="flex gap-2 mb-6">
              <input
                type="text"
                placeholder="Producto"
                value={input()}
                onInput={(e) => setInput(e.currentTarget.value)}
                onKeyPress={handleKeyPress}
                class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
              <button
                onClick={handleAdd}
                class="px-6 py-2 bg-indigo-600 text-white rounded-lg font-semibold hover:bg-indigo-700 transition-colors"
              >
                Agregar
              </button>
            </div>

            <div class="space-y-2">
              <Show when={items().length === 0} fallback={
                <For each={items()}>
                  {(item) => (
                    <div class="flex items-center gap-3 p-4 bg-gray-50 rounded-lg border border-gray-200 hover:border-gray-300 transition-colors">
                      <button
                        onClick={() => handleTogglePurchased(item.id, item.purchased)}
                        class={`flex-shrink-0 w-10 h-10 rounded-lg font-bold text-lg transition-colors ${
                          item.purchased
                            ? 'bg-green-500 text-white hover:bg-green-600'
                            : 'bg-gray-300 text-gray-700 hover:bg-gray-400'
                        }`}
                      >
                        <Show when={item.purchased} fallback="✕">✓</Show>
                      </button>

                      <span class={`flex-1 text-lg font-medium ${
                        item.purchased
                          ? 'line-through text-gray-500'
                          : 'text-gray-800'
                      }`}>
                        {item.name}
                      </span>

                      <button
                        onClick={() => handleDelete(item.id)}
                        class="flex-shrink-0 px-4 py-2 bg-red-100 text-red-700 rounded-lg font-semibold hover:bg-red-200 transition-colors"
                      >
                        Borrar
                      </button>
                    </div>
                  )}
                </For>
              }>
                <p class="text-center text-gray-500 py-8">No hay items en la lista</p>
              </Show>
            </div>
          </Show>

          <Show when={loading()}>
            <div class="text-center py-8">
              <p class="text-gray-600">Cargando...</p>
            </div>
          </Show>
        </div>
      </div>
    </div>
  );
}

