import { createSignal, createEffect, For, Show } from 'solid-js';

export default function App() {
  const [items, setItems] = createSignal<Array<{ id: string; name: string; completed: boolean }>>([]);
  const [input, setInput] = createSignal('');

  createEffect(() => {
    fetch('/api/items')
      .then(res => res.json())
      .then(data => setItems(data));
  });

  const pendingCount = () => items().filter(i => !i.completed).length;

  const addItem = async () => {
    const name = input().trim();
    if (!name) return;

    const res = await fetch('/api/items', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name })
    });

    const newItem = await res.json();
    setItems([...items(), newItem]);
    setInput('');
  };

  const toggleCompleted = async (id: string) => {
    const res = await fetch(`/api/items/${id}/toggle`, { method: 'PATCH' });
    const updated = await res.json();
    setItems(items().map(i => i.id === id ? updated : i));
  };

  const deleteItem = async (id: string) => {
    await fetch(`/api/items/${id}`, { method: 'DELETE' });
    setItems(items().filter(i => i.id !== id));
  };

  const handleKeyPress = (e: KeyboardEvent) => {
    if (e.key === 'Enter') addItem();
  };

  return (
    <div class="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div class="max-w-md mx-auto bg-white rounded-lg shadow-lg p-6">
        <h1 class="text-3xl font-bold text-gray-800 mb-6">Lista de Compras</h1>

        <div class="mb-6 p-3 bg-blue-50 rounded-lg">
          <p class="text-lg font-semibold text-blue-700">
            {pendingCount()} por comprar
          </p>
        </div>

        <div class="flex gap-2 mb-6">
          <input
            type="text"
            placeholder="Producto"
            value={input()}
            onInput={e => setInput(e.target.value)}
            onKeyPress={handleKeyPress}
            class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            onClick={addItem}
            class="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors font-semibold"
          >
            Agregar
          </button>
        </div>

        <div class="space-y-2">
          <For each={items()}>
            {item => (
              <div class="flex items-center gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                <div class="flex-1">
                  <span class={`text-gray-800 ${item.completed ? 'line-through text-gray-400' : ''}`}>
                    <Show when={item.completed}>
                      <span class="text-green-500 font-bold mr-2">✓</span>
                    </Show>
                    {item.name}
                  </span>
                </div>
                <button
                  onClick={() => toggleCompleted(item.id)}
                  class={`px-3 py-1 rounded text-sm font-semibold transition-colors ${
                    item.completed
                      ? 'bg-green-500 text-white hover:bg-green-600'
                      : 'bg-gray-300 text-gray-700 hover:bg-gray-400'
                  }`}
                >
                  {item.completed ? 'Comprado' : 'Comprado'}
                </button>
                <button
                  onClick={() => deleteItem(item.id)}
                  class="px-3 py-1 bg-red-500 text-white rounded text-sm font-semibold hover:bg-red-600 transition-colors"
                >
                  Borrar
                </button>
              </div>
            )}
          </For>
        </div>

        <Show when={items().length === 0}>
          <p class="text-center text-gray-400 mt-8">No hay productos</p>
        </Show>
      </div>
    </div>
  );
}

