import { createServer } from 'node:http';
import { URL } from 'node:url';

interface Item {
  id: string;
  name: string;
  completed: boolean;
}

const items: Map<string, Item> = new Map();
let nextId = 1;

const port = process.env.PORT || 3000;

const generateId = () => String(nextId++);

const server = createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // GET /api/items
  if (pathname === '/api/items' && req.method === 'GET') {
    const itemsList = Array.from(items.values());
    res.writeHead(200);
    res.end(JSON.stringify(itemsList));
    return;
  }

  // POST /api/items
  if (pathname === '/api/items' && req.method === 'POST') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        const id = generateId();
        const newItem: Item = {
          id,
          name: data.name,
          completed: false
        };
        items.set(id, newItem);
        res.writeHead(201);
        res.end(JSON.stringify(newItem));
      } catch {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
    return;
  }

  // PATCH /api/items/:id/toggle
  const toggleMatch = pathname.match(/^\/api\/items\/(.+)\/toggle$/);
  if (toggleMatch && req.method === 'PATCH') {
    const id = toggleMatch[1];
    const item = items.get(id);
    if (!item) {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Item not found' }));
      return;
    }
    item.completed = !item.completed;
    res.writeHead(200);
    res.end(JSON.stringify(item));
    return;
  }

  // DELETE /api/items/:id
  const deleteMatch = pathname.match(/^\/api\/items\/(.+)$/);
  if (deleteMatch && req.method === 'DELETE') {
    const id = deleteMatch[1];
    if (!items.has(id)) {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Item not found' }));
      return;
    }
    items.delete(id);
    res.writeHead(204);
    res.end();
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});

