'use client';

import React, { useState, useEffect } from 'react';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

export default function App() {
  const [authors, setAuthors] = useState<Author[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [authorInput, setAuthorInput] = useState('');
  const [postTitle, setPostTitle] = useState('');
  const [selectedAuthorId, setSelectedAuthorId] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [authorsRes, postsRes] = await Promise.all([
        fetch('/api/authors'),
        fetch('/api/posts'),
      ]);

      if (!authorsRes.ok || !postsRes.ok) throw new Error('Failed to load data');

      const authorsData = await authorsRes.json();
      const postsData = await postsRes.json();

      setAuthors(authorsData);
      setPosts(postsData);
      setError('');
    } catch (err) {
      setError('Error loading data');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const createAuthor = async () => {
    if (!authorInput.trim()) {
      setError('Author name cannot be empty');
      return;
    }

    try {
      const res = await fetch('/api/authors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: authorInput }),
      });

      if (!res.ok) throw new Error('Failed to create author');

      const newAuthor = await res.json();
      setAuthors([...authors, newAuthor]);
      setAuthorInput('');
      setError('');
    } catch (err) {
      setError('Error creating author');
      console.error(err);
    }
  };

  const createPost = async () => {
    if (!postTitle.trim()) {
      setError('Post title cannot be empty');
      return;
    }

    if (!selectedAuthorId) {
      setError('Please select an author');
      return;
    }

    try {
      const res = await fetch('/api/posts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: postTitle, authorId: selectedAuthorId }),
      });

      if (!res.ok) throw new Error('Failed to create post');

      const newPost = await res.json();
      setPosts([...posts, newPost]);
      setPostTitle('');
      setSelectedAuthorId('');
      setError('');
    } catch (err) {
      setError('Error creating post');
      console.error(err);
    }
  };

  const deleteAuthor = async (authorId: string) => {
    try {
      const res = await fetch(`/api/authors/${authorId}`, {
        method: 'DELETE',
      });

      if (!res.ok) {
        const data = await res.json();
        setError(data.message || 'Cannot delete author');
        return;
      }

      setAuthors(authors.filter((a) => a.id !== authorId));
      setError('');
    } catch (err) {
      setError('Error deleting author');
      console.error(err);
    }
  };

  const getAuthorName = (authorId: string) => {
    return authors.find((a) => a.id === authorId)?.name || 'Unknown Author';
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
        <div className="max-w-2xl mx-auto text-center">
          <p className="text-gray-600 text-lg">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8 text-center">
          Blog Platform
        </h1>

        {error && (
          <div className="mb-6 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
            {error}
          </div>
        )}

        {/* Authors Section */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Authors</h2>

          <div className="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="Autor"
              value={authorInput}
              onChange={(e) => setAuthorInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && createAuthor()}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button
              onClick={createAuthor}
              className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold"
            >
              Crear autor
            </button>
          </div>

          <div className="space-y-2">
            {authors.length === 0 ? (
              <p className="text-gray-500 italic">No authors yet</p>
            ) : (
              authors.map((author) => (
                <div
                  key={author.id}
                  className="flex items-center justify-between bg-gray-50 p-4 rounded-lg border border-gray-200"
                >
                  <span className="font-medium text-gray-800">{author.name}</span>
                  <button
                    onClick={() => deleteAuthor(author.id)}
                    className="px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600 transition-colors text-sm font-semibold"
                  >
                    Borrar autor
                  </button>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Posts Section */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Create Post</h2>

          <div className="space-y-4 mb-6">
            <input
              type="text"
              placeholder="Título"
              value={postTitle}
              onChange={(e) => setPostTitle(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && createPost()}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />

            <select
              value={selectedAuthorId}
              onChange={(e) => setSelectedAuthorId(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">Select an author</option>
              {authors.map((author) => (
                <option key={author.id} value={author.id}>
                  {author.name}
                </option>
              ))}
            </select>

            <button
              onClick={createPost}
              className="w-full px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold"
            >
              Publicar
            </button>
          </div>
        </div>

        {/* Posts List */}
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Posts</h2>

          <div className="space-y-4">
            {posts.length === 0 ? (
              <p className="text-gray-500 italic">No posts yet</p>
            ) : (
              posts.map((post) => (
                <div
                  key={post.id}
                  className="bg-gray-50 p-4 rounded-lg border border-gray-200 hover:border-indigo-300 transition-colors"
                >
                  <h3 className="text-lg font-semibold text-gray-800">
                    {post.title}
                  </h3>
                  <p className="text-sm text-gray-600 mt-2">
                    por <span className="font-medium">{getAuthorName(post.authorId)}</span>
                  </p>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

