import { createServer } from 'node:http';
import { URL } from 'node:url';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

const authors: Map<string, Author> = new Map();
const posts: Map<string, Post> = new Map();

let authorIdCounter = 1;
let postIdCounter = 1;

function generateId(type: 'author' | 'post'): string {
  if (type === 'author') {
    return `author_${authorIdCounter++}`;
  }
  return `post_${postIdCounter++}`;
}

function parseBody(req: any): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk: string) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (e) {
        reject(e);
      }
    });
  });
}

function sendJSON(res: any, statusCode: number, data: any) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // GET /api/authors
  if (pathname === '/api/authors' && req.method === 'GET') {
    const authorsList = Array.from(authors.values());
    sendJSON(res, 200, authorsList);
    return;
  }

  // POST /api/authors
  if (pathname === '/api/authors' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      if (!body.name || !body.name.trim()) {
        sendJSON(res, 400, { message: 'Author name is required' });
        return;
      }

      const id = generateId('author');
      const newAuthor: Author = { id, name: body.name.trim() };
      authors.set(id, newAuthor);
      sendJSON(res, 201, newAuthor);
    } catch (error) {
      sendJSON(res, 400, { message: 'Invalid request' });
    }
    return;
  }

  // DELETE /api/authors/:id
  if (pathname.startsWith('/api/authors/') && req.method === 'DELETE') {
    const id = pathname.split('/').pop();
    if (!id) {
      sendJSON(res, 400, { message: 'Invalid author ID' });
      return;
    }

    if (!authors.has(id)) {
      sendJSON(res, 404, { message: 'Author not found' });
      return;
    }

    const authorHasPosts = Array.from(posts.values()).some(
      (p) => p.authorId === id
    );
    if (authorHasPosts) {
      sendJSON(res, 400, { message: 'El autor tiene posts' });
      return;
    }

    authors.delete(id);
    sendJSON(res, 200, { message: 'Author deleted' });
    return;
  }

  // GET /api/posts
  if (pathname === '/api/posts' && req.method === 'GET') {
    const postsList = Array.from(posts.values());
    sendJSON(res, 200, postsList);
    return;
  }

  // POST /api/posts
  if (pathname === '/api/posts' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      if (!body.title || !body.title.trim()) {
        sendJSON(res, 400, { message: 'Post title is required' });
        return;
      }

      if (!body.authorId) {
        sendJSON(res, 400, { message: 'Author ID is required' });
        return;
      }

      if (!authors.has(body.authorId)) {
        sendJSON(res, 404, { message: 'Author not found' });
        return;
      }

      const id = generateId('post');
      const newPost: Post = {
        id,
        title: body.title.trim(),
        authorId: body.authorId,
      };
      posts.set(id, newPost);
      sendJSON(res, 201, newPost);
    } catch (error) {
      sendJSON(res, 400, { message: 'Invalid request' });
    }
    return;
  }

  sendJSON(res, 404, { message: 'Not found' });
});

const port = process.env.PORT || 3001;
server.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});

