import { createServer } from 'node:http';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

const authors: Map<string, Author> = new Map();
const posts: Map<string, Post> = new Map();

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

function parseJson(body: string): unknown {
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  try {
    // GET /api/authors
    if (pathname === '/api/authors' && req.method === 'GET') {
      res.writeHead(200);
      res.end(JSON.stringify(Array.from(authors.values())));
      return;
    }

    // POST /api/authors
    if (pathname === '/api/authors' && req.method === 'POST') {
      let body = '';
      req.on('data', (chunk) => {
        body += chunk.toString();
      });
      req.on('end', () => {
        const data = parseJson(body) as { name?: string };
        if (!data?.name?.trim()) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Name is required' }));
          return;
        }

        const author: Author = {
          id: generateId(),
          name: data.name.trim(),
        };
        authors.set(author.id, author);
        res.writeHead(201);
        res.end(JSON.stringify(author));
      });
      return;
    }

    // DELETE /api/authors/:id
    if (pathname.startsWith('/api/authors/') && req.method === 'DELETE') {
      const id = pathname.split('/')[3];
      const hasPosts = Array.from(posts.values()).some((p) => p.authorId === id);

      if (hasPosts) {
        res.writeHead(400);
        res.end(JSON.stringify({ success: false, error: 'Author has posts' }));
        return;
      }

      if (authors.has(id)) {
        authors.delete(id);
        res.writeHead(200);
        res.end(JSON.stringify({ success: true }));
      } else {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Author not found' }));
      }
      return;
    }

    // GET /api/posts
    if (pathname === '/api/posts' && req.method === 'GET') {
      res.writeHead(200);
      res.end(JSON.stringify(Array.from(posts.values())));
      return;
    }

    // POST /api/posts
    if (pathname === '/api/posts' && req.method === 'POST') {
      let body = '';
      req.on('data', (chunk) => {
        body += chunk.toString();
      });
      req.on('end', () => {
        const data = parseJson(body) as { title?: string; authorId?: string };
        if (!data?.title?.trim() || !data?.authorId) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Title and authorId are required' }));
          return;
        }

        if (!authors.has(data.authorId)) {
          res.writeHead(404);
          res.end(JSON.stringify({ error: 'Author not found' }));
          return;
        }

        const post: Post = {
          id: generateId(),
          title: data.title.trim(),
          authorId: data.authorId,
        };
        posts.set(post.id, post);
        res.writeHead(201);
        res.end(JSON.stringify(post));
      });
      return;
    }

    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  } catch (error) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: 'Internal server error' }));
  }
});

const port = parseInt(process.env.PORT || '3000', 10);
server.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});

