        body: JSON.stringify({ title: postTitle, authorId: selectedAuthorId }),
      });
      const newPost = await response.json();
      setPosts([...posts, newPost]);
      setPostTitle('');
      setSelectedAuthorId('');
    } catch (error) {
      console.error('Error publishing post:', error);
    }
  };

  const handleDeleteAuthor = async (authorId: string) => {
    try {
      const response = await fetch(`/api/authors/${authorId}`, {
        method: 'DELETE',
      });
      const data = await response.json();
      if (data.success) {
        setAuthors(authors.filter((a) => a.id !== authorId));
        const newErrors = { ...deleteError };
        delete newErrors[authorId];
        setDeleteError(newErrors);
      } else {
        setDeleteError({ ...deleteError, [authorId]: data.error || 'El autor tiene posts' });
      }
    } catch (error) {
      console.error('Error deleting author:', error);
    }
  };

  const getAuthorName = (authorId: string) => {
    const author = authors.find((a) => a.id === authorId);
    return author?.name || 'Unknown';
  };

  const authorHasPosts = (authorId: string) => {
    return posts.some((p) => p.authorId === authorId);
  };

  if (loading) {
    return <div className="flex items-center justify-center min-h-screen text-lg">Loading...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-100 py-8 px-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-12">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">Blog</h1>
          <p className="text-gray-600">Manage your authors and posts</p>
        </div>

        {/* Create Author Section */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Create Author</h2>
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Autor"
              value={authorInput}
              onChange={(e) => setAuthorInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleCreateAuthor()}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleCreateAuthor}
              className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
            >
              Crear autor
            </button>
          </div>
        </div>

        {/* Authors List */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Authors</h2>
          {authors.length === 0 ? (
            <p className="text-gray-500">No authors yet. Create one to get started!</p>
          ) : (
            <div className="space-y-3">
              {authors.map((author) => (
                <div key={author.id} className="space-y-1">
                  <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200">
                    <span className="text-gray-800 font-medium">{author.name}</span>
                    {authorHasPosts(author.id) ? (
                      <span className="text-sm text-gray-500">El autor tiene posts</span>
                    ) : (
                      <button
                        onClick={() => handleDeleteAuthor(author.id)}
                        className="px-4 py-1 rounded text-sm font-medium bg-red-500 text-white hover:bg-red-600 transition-colors"
                      >
                        Borrar autor
                      </button>
                    )}
                  </div>
                  {deleteError[author.id] && (
                    <div className="px-3 text-xs text-red-600">
                      {deleteError[author.id]}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Create Post Section */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Publish Post</h2>
          <div className="space-y-4">
            <input
              type="text"
              placeholder="Título"
              value={postTitle}
              onChange={(e) => setPostTitle(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && selectedAuthorId && handlePublishPost()}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <div className="flex gap-2">
              <select
                value={selectedAuthorId}
                onChange={(e) => setSelectedAuthorId(e.target.value)}
                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="">Select an author</option>
                {authors.map((author) => (
                  <option key={author.id} value={author.id}>
                    {author.name}
                  </option>
                ))}
              </select>
              <button
                onClick={handlePublishPost}
                disabled={!postTitle.trim() || !selectedAuthorId}
                className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium disabled:bg-gray-400 disabled:cursor-not-allowed"
              >
                Publicar
              </button>
            </div>
          </div>
        </div>

        {/* Posts List */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Posts</h2>
          {posts.length === 0 ? (
            <p className="text-gray-500">No posts yet. Publish one to get started!</p>
          ) : (
            <div className="space-y-3">
              {posts.map((post) => (
