import { createServer } from 'node:http';

const PORT = process.env.PORT || 3000;

interface Author {
	id: string;
	name: string;
}

interface Post {
	id: string;
	title: string;
	authorId: string;
}

const authors: Author[] = [];
const posts: Post[] = [];

let authorCounter = 0;
let postCounter = 0;

function generateId(prefix: string): string {
	if (prefix === 'author') {
		return `author_${++authorCounter}`;
	}
	return `post_${++postCounter}`;
}

function parseBody(req: any): Promise<any> {
	return new Promise((resolve, reject) => {
		let data = '';
		req.on('data', (chunk: string) => {
			data += chunk;
		});
		req.on('end', () => {
			try {
				resolve(data ? JSON.parse(data) : {});
			} catch (e) {
				reject(e);
			}
		});
		req.on('error', reject);
	});
}

function getPath(url: string): string {
	return url.split('?')[0];
}

const server = createServer(async (req, res) => {
	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
	res.setHeader('Content-Type', 'application/json');

	if (req.method === 'OPTIONS') {
		res.writeHead(200);
		res.end();
		return;
	}

	const path = getPath(req.url || '');

	try {
		// GET /api/authors
		if (path === '/api/authors' && req.method === 'GET') {
			res.writeHead(200);
			res.end(JSON.stringify(authors));
			return;
		}

		// POST /api/authors
		if (path === '/api/authors' && req.method === 'POST') {
			const body = await parseBody(req);
			if (!body.name) {
				res.writeHead(400);
				res.end(JSON.stringify({ error: 'Name required' }));
				return;
			}
			const author: Author = {
				id: generateId('author'),
				name: body.name
			};
			authors.push(author);
			res.writeHead(201);
			res.end(JSON.stringify(author));
			return;
		}

		// DELETE /api/authors/:id
		if (path.startsWith('/api/authors/') && req.method === 'DELETE') {
			const id = path.split('/')[3];
			const authorIndex = authors.findIndex(a => a.id === id);
			if (authorIndex === -1) {
				res.writeHead(404);
				res.end(JSON.stringify({ error: 'Author not found' }));
				return;
			}
			const hasPost = posts.some(p => p.authorId === id);
			if (hasPost) {
				res.writeHead(409);
				res.end(JSON.stringify({ error: 'Author has posts' }));
				return;
			}
			authors.splice(authorIndex, 1);
			res.writeHead(200);
			res.end(JSON.stringify({ success: true }));
			return;
		}

		// GET /api/posts
		if (path === '/api/posts' && req.method === 'GET') {
			res.writeHead(200);
			res.end(JSON.stringify(posts));
			return;
		}

		// POST /api/posts
		if (path === '/api/posts' && req.method === 'POST') {
			const body = await parseBody(req);
			if (!body.title || !body.authorId) {
				res.writeHead(400);
				res.end(JSON.stringify({ error: 'Title and authorId required' }));
