import { createSignal, createMemo, For, Show } from 'solid-js';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

export default function App() {
  const [authors, setAuthors] = createSignal<Author[]>([]);
  const [posts, setPosts] = createSignal<Post[]>([]);
  const [authorInput, setAuthorInput] = createSignal('');
  const [postInput, setPostInput] = createSignal('');
  const [selectedAuthorId, setSelectedAuthorId] = createSignal('');

  // Load initial data
  const loadData = async () => {
    try {
      const authorsRes = await fetch('/api/authors');
      const authorsData = await authorsRes.json();
      setAuthors(authorsData);

      const postsRes = await fetch('/api/posts');
      const postsData = await postsRes.json();
      setPosts(postsData);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  // Load data on mount
  loadData();

  const createAuthor = async () => {
    const name = authorInput().trim();
    if (!name) return;

    try {
      const res = await fetch('/api/authors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      const newAuthor = await res.json();
      setAuthors([...authors(), newAuthor]);
      setAuthorInput('');
    } catch (error) {
      console.error('Error creating author:', error);
    }
  };

  const createPost = async () => {
    const title = postInput().trim();
    const authorId = selectedAuthorId();
    if (!title || !authorId) return;

    try {
      const res = await fetch('/api/posts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, authorId }),
      });
      const newPost = await res.json();
      setPosts([...posts(), newPost]);
      setPostInput('');
      setSelectedAuthorId('');
    } catch (error) {
      console.error('Error creating post:', error);
    }
  };

  const deleteAuthor = async (authorId: string) => {
    try {
      const res = await fetch(`/api/authors/${authorId}`, {
        method: 'DELETE',
      });
      const data = await res.json();
      if (data.success) {
        setAuthors(authors().filter((a) => a.id !== authorId));
      }
    } catch (error) {
      console.error('Error deleting author:', error);
    }
  };

  const getAuthorName = (authorId: string) => {
    const author = authors().find((a) => a.id === authorId);
    return author?.name || 'Unknown';
  };

  const postsByAuthor = createMemo(() => {
    const postCountByAuthor: Record<string, number> = {};
    posts().forEach((post) => {
      postCountByAuthor[post.authorId] =
        (postCountByAuthor[post.authorId] || 0) + 1;
    });
    return postCountByAuthor;
  });

  const canDeleteAuthor = (authorId: string) => {
    return !postsByAuthor()[authorId];
  };

  return (
    <div class="min-h-screen bg-gray-100 py-8 px-4">
      <div class="max-w-4xl mx-auto">
        <h1 class="text-4xl font-bold text-gray-900 mb-8">Blog</h1>

        {/* Authors Section */}
        <div class="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 class="text-2xl font-bold text-gray-800 mb-4">Autores</h2>
          <div class="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="Autor"
              value={authorInput()}
              onInput={(e) => setAuthorInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') createAuthor();
              }}
              class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={createAuthor}
              class="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors font-semibold"
            >
              Crear autor
            </button>
          </div>

          <div class="space-y-2">
            <For each={authors()}>
              {(author) => (
                <div class="flex items-center justify-between bg-gray-50 p-3 rounded-lg">
                  <span class="font-medium text-gray-700">{author.name}</span>
                  <button
                    onClick={() => deleteAuthor(author.id)}
                    disabled={!canDeleteAuthor(author.id)}
                    class={`px-4 py-2 rounded-lg transition-colors font-semibold ${
                      canDeleteAuthor(author.id)
                        ? 'bg-red-500 text-white hover:bg-red-600'
                        : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                    }`}
                  >
                    <Show
                      when={canDeleteAuthor(author.id)}
                      fallback={
                        <span>El autor tiene posts</span>
                      }
                    >
                      Borrar autor
                    </Show>
                  </button>
                </div>
              )}
            </For>
          </div>
        </div>

        {/* Posts Section */}
        <div class="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 class="text-2xl font-bold text-gray-800 mb-4">Publicar Post</h2>
          <div class="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="Título"
              value={postInput()}
              onInput={(e) => setPostInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') createPost();
              }}
              class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <select
              value={selectedAuthorId()}
              onChange={(e) => setSelectedAuthorId(e.target.value)}
              class="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="">Seleccionar autor</option>
              <For each={authors()}>
                {(author) => (
                  <option value={author.id}>{author.name}</option>
                )}
              </For>
            </select>
            <button
              onClick={createPost}
              class="px-6 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors font-semibold"
            >
              Publicar
            </button>
          </div>
        </div>

        {/* Posts Display */}
        <div class="bg-white rounded-lg shadow-md p-6">
          <h2 class="text-2xl font-bold text-gray-800 mb-4">Posts</h2>
          <div class="space-y-3">
            <For each={posts()}>
              {(post) => (
                <div class="border-l-4 border-blue-500 pl-4 py-2">
                  <h3 class="text-lg font-semibold text-gray-900">
                    {post.title}
                  </h3>
                  <p class="text-gray-600">por {getAuthorName(post.authorId)}</p>
                </div>
              )}
            </For>
            <Show when={posts().length === 0}>
              <p class="text-gray-500 italic">No hay posts aún</p>
            </Show>
          </div>
        </div>
      </div>
    </div>
  );
}

