import { createServer } from 'node:http';
import { URL } from 'node:url';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

const authors: Map<string, Author> = new Map();
const posts: Map<string, Post> = new Map();

let authorIdCounter = 1;
let postIdCounter = 1;

function generateId(counter: number): string {
  return `${Date.now()}-${counter}`;
}

function parseBody(req: any): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk: string) => {
      body += chunk;
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (error) {
        reject(error);
      }
    });
    req.on('error', reject);
  });
}

const server = createServer(async (req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // GET /api/authors
  if (pathname === '/api/authors' && req.method === 'GET') {
    res.writeHead(200);
    res.end(JSON.stringify(Array.from(authors.values())));
    return;
  }

  // POST /api/authors
  if (pathname === '/api/authors' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const { name } = body;

      if (!name || typeof name !== 'string') {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid author name' }));
        return;
      }

      const id = generateId(authorIdCounter++);
      const newAuthor: Author = { id, name };
      authors.set(id, newAuthor);

      res.writeHead(201);
      res.end(JSON.stringify(newAuthor));
    } catch (error) {
      res.writeHead(400);
      res.end(JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  // DELETE /api/authors/:id
  if (pathname.startsWith('/api/authors/') && req.method === 'DELETE') {
    const authorId = pathname.slice('/api/authors/'.length);
    const authorHasPosts = Array.from(posts.values()).some(
      (post) => post.authorId === authorId
    );

    if (authorHasPosts) {
      res.writeHead(400);
      res.end(JSON.stringify({ success: false, error: 'Author has posts' }));
      return;
    }

    const deleted = authors.delete(authorId);
    res.writeHead(200);
    res.end(JSON.stringify({ success: deleted }));
    return;
  }

  // GET /api/posts
  if (pathname === '/api/posts' && req.method === 'GET') {
    res.writeHead(200);
    res.end(JSON.stringify(Array.from(posts.values())));
    return;
  }

  // POST /api/posts
  if (pathname === '/api/posts' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const { title, authorId } = body;

      if (!title || typeof title !== 'string' || !authorId) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid post data' }));
        return;
      }

      if (!authors.has(authorId)) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Author not found' }));
        return;
      }

      const id = generateId(postIdCounter++);
      const newPost: Post = { id, title, authorId };
      posts.set(id, newPost);

      res.writeHead(201);
      res.end(JSON.stringify(newPost));
    } catch (error) {
      res.writeHead(400);
      res.end(JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  // 404
  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});

