    try {
      const res = await fetch('/api/authors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      const newAuthor = await res.json();
      setAuthors([...authors(), newAuthor]);
      setAuthorInput('');
