                      onClick={() => deleteAuthor(author.id)}
                      class="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors font-semibold"
                    >
                      Borrar autor
                    </button>
                  )}
                </div>
              )}
            </For>
          </div>
        </div>

        {/* Posts Section */}
        <div class="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 class="text-2xl font-bold text-gray-800 mb-4">Publicar Post</h2>
          <div class="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="Título"
              value={postInput()}
              onInput={(e) => setPostInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') createPost();
              }}
              class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <select
              value={selectedAuthorId()}
              onChange={(e) => setSelectedAuthorId(e.target.value)}
              class="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="">Seleccionar autor</option>
              <For each={authors()}>
                {(author) => (
                  <option value={author.id}>{author.name}</option>
                )}
              </For>
            </select>
            <button
              onClick={createPost}
              class="px-6 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors font-semibold"
            >
              Publicar
            </button>
          </div>
        </div>

        {/* Posts Display */}
        <div class="bg-white rounded-lg shadow-md p-6">
          <h2 class="text-2xl font-bold text-gray-800 mb-4">Posts</h2>
          <div class="space-y-3">
