import { createServer } from 'node:http';
import { URL } from 'node:url';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

const authors: Map<string, Author> = new Map();
const posts: Map<string, Post> = new Map();

function generateId(): string {
  return Math.random().toString(36).substring(2, 11);
}

function parseBody(req: any): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk: string) => {
      body += chunk;
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (error) {
        reject(error);
      }
    });
    req.on('error', reject);
  });
}

const server = createServer(async (req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  try {
    // GET /api/authors
    if (req.method === 'GET' && pathname === '/api/authors') {
      const authorList = Array.from(authors.values());
      res.writeHead(200);
      res.end(JSON.stringify(authorList));
      return;
    }

    // POST /api/authors
    if (req.method === 'POST' && pathname === '/api/authors') {
      const body = await parseBody(req);
      const { name } = body;

      if (!name || typeof name !== 'string') {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid name' }));
        return;
      }

      const id = generateId();
      const author: Author = { id, name };
      authors.set(id, author);

      res.writeHead(201);
      res.end(JSON.stringify(author));
      return;
    }

    // DELETE /api/authors/:id
    if (req.method === 'DELETE' && pathname.startsWith('/api/authors/')) {
      const id = pathname.split('/').pop();

      if (!id || !authors.has(id)) {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Author not found' }));
        return;
      }

      const authorHasPosts = Array.from(posts.values()).some((p) => p.authorId === id);

      if (authorHasPosts) {
        res.writeHead(409);
        res.end(JSON.stringify({ error: 'Author has posts' }));
        return;
      }

      authors.delete(id);
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
      return;
    }

    // GET /api/posts
    if (req.method === 'GET' && pathname === '/api/posts') {
      const postList = Array.from(posts.values());
      res.writeHead(200);
      res.end(JSON.stringify(postList));
      return;
    }

    // POST /api/posts
    if (req.method === 'POST' && pathname === '/api/posts') {
      const body = await parseBody(req);
      const { title, authorId } = body;

      if (!title || typeof title !== 'string' || !authorId || !authors.has(authorId)) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid title or authorId' }));
        return;
      }

      const id = generateId();
      const post: Post = { id, title, authorId };
      posts.set(id, post);

      res.writeHead(201);
      res.end(JSON.stringify(post));
      return;
    }

    // 404
