import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

interface Product {
  id: string;
  name: string;
  code: string;
  price: number;
}

const products: Map<string, Product> = new Map();

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

function parseJson(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(err);
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res: ServerResponse, statusCode: number, data: any): void {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

async function handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (pathname === '/api/products' && req.method === 'GET') {
    const productList = Array.from(products.values());
    sendJson(res, 200, productList);
    return;
  }

  if (pathname === '/api/products' && req.method === 'POST') {
    try {
      const body = await parseJson(req);
      const { name, code, price } = body;

      if (!name || name.trim().length < 3) {
        sendJson(res, 400, { error: 'Nombre muy corto' });
        return;
      }

      if (!code) {
        sendJson(res, 400, { error: 'Código requerido' });
        return;
      }

      if (Array.from(products.values()).some((p) => p.code === code)) {
        sendJson(res, 400, { error: 'Código repetido' });
        return;
      }

      if (typeof price !== 'number' || price < 0) {
        sendJson(res, 400, { error: 'Precio inválido' });
        return;
      }

      const product: Product = {
        id: generateId(),
        name: name.trim(),
        code,
        price,
      };

      products.set(product.id, product);
      sendJson(res, 201, product);
    } catch (err) {
      sendJson(res, 400, { error: 'Error al procesar la solicitud' });
    }
    return;
  }

  sendJson(res, 404, { error: 'Ruta no encontrada' });
}

const PORT = process.env.PORT || 3000;
const server = createServer(handleRequest);

server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

