      if (!code || typeof code !== 'string') {
        sendJson(res, 400, { error: 'Código requerido' });
        return;
      }

      if (Array.from(products.values()).some((p) => p.code === code)) {
        sendJson(res, 400, { error: 'Código repetido' });
        return;
