import { createServer, IncomingMessage, ServerResponse } from 'node:http';

interface Product {
  id: string;
  name: string;
  code: string;
  price: number;
}

const products: Map<string, Product> = new Map();
let nextId = 1;

const parseBody = (req: IncomingMessage): Promise<any> => {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(err);
      }
    });
    req.on('error', reject);
  });
};

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  try {
    if (pathname === '/api/products' && req.method === 'GET') {
      const productList = Array.from(products.values());
      res.writeHead(200);
      res.end(JSON.stringify(productList));
    } else if (pathname === '/api/products' && req.method === 'POST') {
      const body = await parseBody(req);
      const { name, code, price } = body;

      if (!name || name.length < 3) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Nombre muy corto' }));
        return;
      }

      if (!code) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Código requerido' }));
        return;
      }

      if (Array.from(products.values()).some((p) => p.code === code)) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Código repetido' }));
        return;
      }

      if (price === undefined || price === null || price < 0) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Precio inválido' }));
        return;
      }

      const newProduct: Product = {
        id: String(nextId++),
        name,
        code,
        price: Number(price),
      };

      products.set(newProduct.id, newProduct);

      res.writeHead(201);
      res.end(JSON.stringify(newProduct));
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Not Found' }));
    }
  } catch (err) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: 'Internal Server Error' }));
  }
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

