import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

interface Product {
	name: string;
	code: string;
	price: number;
}

const productos: Map<string, Product> = new Map();

function sendJSON(res: ServerResponse, statusCode: number, data: unknown) {
	res.writeHead(statusCode, { 'Content-Type': 'application/json' });
	res.end(JSON.stringify(data));
}

function parseBody(req: IncomingMessage): Promise<Record<string, unknown>> {
	return new Promise((resolve, reject) => {
		let body = '';
		req.on('data', (chunk) => {
			body += chunk.toString();
		});
		req.on('end', () => {
			try {
				resolve(body ? JSON.parse(body) : {});
			} catch {
				reject(new Error('Invalid JSON'));
			}
		});
		req.on('error', reject);
	});
}

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
	const url = new URL(req.url || '', `http://${req.headers.host}`);
	const pathname = url.pathname;

	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

	if (req.method === 'OPTIONS') {
		res.writeHead(200);
		res.end();
		return;
	}

	if (pathname === '/api/productos' && req.method === 'GET') {
		const productosArray = Array.from(productos.values());
		sendJSON(res, 200, productosArray);
		return;
	}

	if (pathname === '/api/productos' && req.method === 'POST') {
		try {
			const body = await parseBody(req);
			const { name, code, price } = body as {
				name?: unknown;
				code?: unknown;
				price?: unknown;
			};

			// Validaciones
			if (typeof name !== 'string' || name.length < 3) {
				sendJSON(res, 400, { error: 'Nombre muy corto' });
				return;
			}

			if (typeof code !== 'string' || !code) {
				sendJSON(res, 400, { error: 'Código inválido' });
				return;
			}

			if (productos.has(code)) {
				sendJSON(res, 400, { error: 'Código repetido' });
				return;
			}

			if (typeof price !== 'number' || price < 0) {
				sendJSON(res, 400, { error: 'Precio inválido' });
				return;
			}

			const producto: Product = { name, code, price };
			productos.set(code, producto);

			sendJSON(res, 201, producto);
			return;
		} catch {
			sendJSON(res, 400, { error: 'Error al procesar la solicitud' });
			return;
		}
	}

	sendJSON(res, 404, { error: 'Ruta no encontrada' });
});

