  res.end(JSON.stringify(data))
}

async function handleApiRequest(
  req: IncomingMessage,
  res: ServerResponse,
  path: string
) {
  if (path === '/api/productos' && req.method === 'GET') {
    sendJson(res, 200, productos)
    return
  }

  if (path === '/api/productos' && req.method === 'POST') {
    try {
      const body = (await parseJson(req)) as any

      if (!body.name || typeof body.name !== 'string') {
        sendJson(res, 400, { error: 'Nombre requerido' })
        return
      }

      if (body.name.length < 3) {
        sendJson(res, 400, { error: 'Nombre muy corto' })
        return
      }

      if (!body.code || typeof body.code !== 'string') {
        sendJson(res, 400, { error: 'Código requerido' })
        return
      }

      if (productos.some(p => p.code === body.code)) {
        sendJson(res, 400, { error: 'Código repetido' })
        return
      }

      if (typeof body.price !== 'number' || body.price < 0) {
        sendJson(res, 400, { error: 'Precio inválido' })
        return
      }

