        name: body.name,
        code: body.code,
        price: body.price
      }

      productos.push(nuevoProducto)
      sendJson(res, 201, nuevoProducto)
      return
    } catch (e) {
      sendJson(res, 400, { error: 'JSON inválido' })
      return
    }
  }

  sendJson(res, 404, { error: 'No encontrado' })
}

