import * as http from 'node:http';

interface Product {
  id: string;
  name: string;
  code: string;
  price: number;
}

const products: Map<string, Product> = new Map();
const codeSet: Set<string> = new Set();

const PORT = process.env.PORT || 3000;

const server = http.createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (req.url === '/api/products' && req.method === 'GET') {
    const productsList = Array.from(products.values());
    res.writeHead(200);
    res.end(JSON.stringify(productsList));
    return;
  }

  if (req.url === '/api/products' && req.method === 'POST') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const { name, code, price } = JSON.parse(body);
        const errors: Record<string, string> = {};

        if (!name || name.length < 3) {
          errors.name = 'Nombre muy corto';
        }

        if (codeSet.has(code)) {
          errors.code = 'Código repetido';
        }

        if (typeof price !== 'number' || price < 0) {
          errors.price = 'Precio inválido';
        }

        if (Object.keys(errors).length > 0) {
          res.writeHead(400);
          res.end(JSON.stringify({ errors }));
          return;
        }

        const id = Date.now().toString();
        const product: Product = { id, name, code, price };

        products.set(id, product);
        codeSet.add(code);

        res.writeHead(201);
        res.end(JSON.stringify({ product }));
      } catch (error) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid request body' }));
      }
    });
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

