import { createSignal, createMemo, For, Show } from 'solid-js';

export default function App() {
  const [nombre, setNombre] = createSignal('');
  const [codigo, setCodigo] = createSignal('');
  const [precio, setPrecio] = createSignal('');
  const [productos, setProductos] = createSignal<Array<{ nombre: string; codigo: string }>>([]);
  const [error, setError] = createSignal('');
  const [loading, setLoading] = createSignal(false);

  const cargarProductos = async () => {
    try {
      const res = await fetch('/api/productos');
      const data = await res.json();
      setProductos(data);
    } catch (err) {
      console.error('Error cargando productos:', err);
    }
  };

  // Cargar productos al montar
  cargarProductos();

  const guardar = async () => {
    setError('');
    setLoading(true);

    try {
      const res = await fetch('/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          nombre: nombre(),
          codigo: codigo(),
          precio: parseFloat(precio()),
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error);
        setLoading(false);
        return;
      }

      setNombre('');
      setCodigo('');
      setPrecio('');
      await cargarProductos();
    } catch (err) {
      setError('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 p-8">
      <div class="max-w-2xl mx-auto">
        <h1 class="text-3xl font-bold text-gray-900 mb-8">Registro de Productos</h1>

        <div class="bg-white rounded-lg shadow p-6 mb-8">
          <div class="space-y-4">
            <input
              type="text"
