            />
            <input
              type="text"
              placeholder="Código"
              value={codigo()}
              onInput={(e) => setCodigo(e.currentTarget.value)}
              class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <input
              type="number"
              placeholder="Precio"
              value={precio()}
              onInput={(e) => setPrecio(e.currentTarget.value)}
              class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />

            <Show when={error()}>
              <div class="text-red-600 font-semibold bg-red-50 p-3 rounded-lg">
                {error()}
              </div>
            </Show>

            <button
              onClick={guardar}
              disabled={loading()}
              class="w-full bg-blue-600 text-white py-2 rounded-lg font-semibold hover:bg-blue-700 disabled:bg-gray-400 transition"
            >
              {loading() ? 'Guardando...' : 'Guardar'}
            </button>
          </div>
        </div>

        <div class="bg-white rounded-lg shadow overflow-hidden">
          <div class="px-6 py-4 bg-gray-50 border-b border-gray-200">
            <h2 class="text-xl font-bold text-gray-900">Productos Guardados</h2>
          </div>
          <Show when={productos().length === 0} fallback={
            <ul class="divide-y divide-gray-200">
              <For each={productos()}>
                {(producto) => (
                  <li class="px-6 py-4 hover:bg-gray-50">
                    <div class="flex justify-between items-center">
                      <span class="text-gray-900 font-semibold">{producto.nombre}</span>
                      <span class="text-gray-600 text-sm">Código: {producto.codigo}</span>
