import * as http from 'node:http';

interface Producto {
  nombre: string;
  codigo: string;
  precio: number;
}

const productos: Producto[] = [];
const PORT = process.env.PORT || '3000';

const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  if (req.url === '/api/productos' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(productos));
    return;
  }

  if (req.url === '/api/productos' && req.method === 'POST') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const { nombre, codigo, precio } = JSON.parse(body);

        // Validar nombre
        if (typeof nombre !== 'string' || nombre.length < 3) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Nombre muy corto' }));
          return;
        }

        // Validar código duplicado
        if (productos.some((p) => p.codigo === codigo)) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Código repetido' }));
          return;
        }

        // Validar precio
        if (typeof precio !== 'number' || precio < 0) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Precio inválido' }));
          return;
        }

        // Crear producto
        const nuevoProducto: Producto = { nombre, codigo, precio };
        productos.push(nuevoProducto);

        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(nuevoProducto));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Error al procesar la solicitud' }));
      }
    });

    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'No encontrado' }));
});

server.listen(parseInt(PORT), () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

