import React, { useState, useEffect } from 'react';

export default function App() {
  const [file, setFile] = useState<File | null>(null);
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCurrentImage();
  }, []);

  const fetchCurrentImage = async () => {
    try {
      const response = await fetch('/api/profile-image');
      if (response.ok) {
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        setUploadedImage(url);
      }
    } catch (err) {
      console.error('Error fetching image:', err);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      if (!selectedFile.type.startsWith('image/')) {
        setError('Por favor selecciona un archivo de imagen');
        return;
      }
      if (selectedFile.size > 5 * 1024 * 1024) {
        setError('La imagen no puede superar 5MB');
        return;
      }
      setFile(selectedFile);
      setError(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setError('Por favor selecciona una imagen');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('image', file);

      const response = await fetch('/api/profile-image', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('Error al subir la imagen');
      }

      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      setUploadedImage(url);
      setFile(null);

      const fileInput = document.querySelector('input[type="file"]') as HTMLInputElement;
      if (fileInput) {
        fileInput.value = '';
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-xl p-8 w-full max-w-md">
        <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">Mi Perfil</h1>

        <div className="space-y-6">
          {/* File Input */}
          <div className="flex flex-col gap-3">
            <label className="block text-sm font-medium text-gray-700">
              Selecciona una foto de perfil
            </label>
            <input
              type="file"
              accept="image/*"
              onChange={handleFileChange}
              className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer"
            />
            {file && (
              <p className="text-sm text-green-600 font-medium">
                Archivo seleccionado: {file.name}
              </p>
            )}
          </div>

          {/* Upload Button */}
          <button
            onClick={handleUpload}
            disabled={!file || loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-bold py-2 px-4 rounded-lg transition duration-200 ease-in-out transform hover:scale-105 disabled:transform-none"
          >
            {loading ? 'Subiendo...' : 'Subir'}
          </button>

          {/* Error Message */}
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
              {error}
            </div>
          )}

          {/* Uploaded Image */}
          {uploadedImage && (
            <div className="flex flex-col gap-3">
              <h2 className="text-sm font-medium text-gray-700">Foto de perfil actual</h2>
              <div className="rounded-lg overflow-hidden bg-gray-200 flex items-center justify-center h-64 w-64 mx-auto">
                <img
                  src={uploadedImage}
                  alt="Foto de perfil"
                  className="w-full h-full object-cover"
                />
              </div>
            </div>
          )}

          {!uploadedImage && !error && (
            <div className="text-center text-gray-500 py-8">
              <p className="text-sm">No hay foto de perfil cargada</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

