import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

const PORT = process.env.PORT || 3000;

// In-memory storage for the profile image
let profileImageBuffer: Buffer | null = null;
let profileImageMimeType: string = 'image/jpeg';

function parseMultipartForm(
  req: IncomingMessage,
  contentType: string
): Promise<{ fields: Record<string, string>; files: Record<string, Buffer> }> {
  return new Promise((resolve, reject) => {
    const boundary = contentType.split('boundary=')[1];
    if (!boundary) {
      reject(new Error('No boundary found'));
      return;
    }

    const chunks: Buffer[] = [];

    req.on('data', (chunk) => {
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks).toString('binary');
        const parts = body.split(`--${boundary}`);
        const fields: Record<string, string> = {};
        const files: Record<string, Buffer> = {};

        for (const part of parts) {
          if (!part || part === '--\r\n' || part === '--') continue;

          const header_end = part.indexOf('\r\n\r\n');
          if (header_end === -1) continue;

          const headerStr = part.substring(0, header_end);
          const content = part.substring(header_end + 4);

          const nameMatch = headerStr.match(/name="([^"]+)"/);
          if (!nameMatch) continue;

          const name = nameMatch[1];
          const filenameMatch = headerStr.match(/filename="([^"]+)"/);

          if (filenameMatch) {
            const filename = filenameMatch[1];
            const contentTypeMatch = headerStr.match(/Content-Type: ([^\r\n]+)/);
            const mimeType = contentTypeMatch ? contentTypeMatch[1] : 'application/octet-stream';

            const fileContent = content.substring(0, content.length - 2);
            files[name] = Buffer.from(fileContent, 'binary');
            files[`${name}_mimetype`] = Buffer.from(mimeType);
          } else {
            const fieldContent = content.substring(0, content.length - 2);
            fields[name] = fieldContent;
          }
        }

        resolve({ fields, files });
      } catch (error) {
        reject(error);
      }
    });

    req.on('error', reject);
  });
}

function sendJson(res: ServerResponse, statusCode: number, data: any) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

function handleProfileImageGet(res: ServerResponse) {
  if (!profileImageBuffer) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'No image uploaded' }));
    return;
  }

  res.writeHead(200, {
    'Content-Type': profileImageMimeType,
    'Content-Length': profileImageBuffer.length,
    'Cache-Control': 'no-cache',
  });
  res.end(profileImageBuffer);
}

async function handleProfileImagePost(req: IncomingMessage, res: ServerResponse) {
  const contentType = req.headers['content-type'];
