import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

const PORT = process.env.PORT || 3000;

// In-memory storage for the profile image
let profileImageBuffer: Buffer | null = null;
let profileImageMimeType: string = 'image/jpeg';

function parseMultipartForm(
  req: IncomingMessage,
  contentType: string
): Promise<{ files: Record<string, { data: Buffer; mimeType: string }> }> {
  return new Promise((resolve, reject) => {
    const boundaryMatch = contentType.match(/boundary=([^\s;]+)/);
    if (!boundaryMatch) {
      reject(new Error('No boundary found'));
      return;
    }

    const boundary = boundaryMatch[1].replace(/"/g, '');
    const chunks: Buffer[] = [];

    req.on('data', (chunk) => {
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks);
        const boundaryBuffer = Buffer.from(`--${boundary}`);
        const parts: Buffer[] = [];
        let currentPos = 0;

        while (true) {
          const nextBoundary = body.indexOf(boundaryBuffer, currentPos);
          if (nextBoundary === -1) break;

          if (currentPos > 0) {
            parts.push(body.slice(currentPos + boundaryBuffer.length, nextBoundary));
          }
          currentPos = nextBoundary;
        }

        const files: Record<string, { data: Buffer; mimeType: string }> = {};

        for (const part of parts) {
          if (part.length < 4) continue;

          const headerEndIndex = part.indexOf('\r\n\r\n');
          if (headerEndIndex === -1) continue;

          const headerBuffer = part.slice(0, headerEndIndex);
          const headerStr = headerBuffer.toString('utf-8');
          const contentBuffer = part.slice(headerEndIndex + 4);

          const nameMatch = headerStr.match(/name="([^"]+)"/);
          if (!nameMatch) continue;

          const name = nameMatch[1];
          const filenameMatch = headerStr.match(/filename="([^"]+)"/);

          if (filenameMatch) {
            const contentTypeMatch = headerStr.match(/Content-Type:\s*([^\r\n]+)/);
            const mimeType = contentTypeMatch ? contentTypeMatch[1].trim() : 'application/octet-stream';

            // Remove trailing CRLF
            let fileData = contentBuffer;
            if (fileData.length >= 2 && fileData[fileData.length - 2] === 13 && fileData[fileData.length - 1] === 10) {
              fileData = fileData.slice(0, fileData.length - 2);
            }

            files[name] = {
              data: fileData,
              mimeType: mimeType,
            };
          }
        }

        resolve({ files });
      } catch (error) {
        reject(error);
      }
    });

    req.on('error', reject);
  });
}

function sendJson(res: ServerResponse, statusCode: number, data: any) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

function handleProfileImageGet(res: ServerResponse) {
  if (!profileImageBuffer) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'No image uploaded' }));
    return;
  }

  res.writeHead(200, {
    'Content-Type': profileImageMimeType,
    'Content-Length': profileImageBuffer.length,
  });
  res.end(profileImageBuffer);
}

async function handleProfileImagePost(req: IncomingMessage, res: ServerResponse) {
  const contentType = req.headers['content-type'];
  if (!contentType || !contentType.includes('multipart/form-data')) {
    sendJson(res, 400, { error: 'Content-Type must be multipart/form-data' });
    return;
  }

  try {
    const { files } = await parseMultipartForm(req, contentType);

    if (!files['image']) {
      sendJson(res, 400, { error: 'No image file provided' });
      return;
    }

    profileImageBuffer = files['image'].data;
    profileImageMimeType = files['image'].mimeType;

    res.writeHead(200, {
      'Content-Type': profileImageMimeType,
      'Content-Length': profileImageBuffer.length,
    });
    res.end(profileImageBuffer);
  } catch (error) {
    console.error('Error processing upload:', error);
    sendJson(res, 500, { error: 'Error processing upload' });
  }
}

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  const url = new URL(req.url || '', `http://${req.headers.host || 'localhost'}`);

  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (url.pathname === '/api/profile-image') {
    if (req.method === 'GET') {
      handleProfileImageGet(res);
    } else if (req.method === 'POST') {
      await handleProfileImagePost(req, res);
    } else {
      sendJson(res, 405, { error: 'Method not allowed' });
    }
  } else {
    sendJson(res, 404, { error: 'Not found' });
  }
});

server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

