          <button
            onClick={handleUpload}
            disabled={loading || !file}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-400 text-white font-bold py-2 px-4 rounded-md transition duration-200"
          >
            {loading ? 'Subiendo...' : 'Subir'}
          </button>

          {/* Error Message */}
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
              {error}
            </div>
          )}

          {/* Uploaded Image */}
          {uploadedImage && (
            <div className="space-y-2">
              <h2 className="text-lg font-semibold text-gray-800">Foto actual</h2>
              <div className="rounded-lg overflow-hidden border-2 border-indigo-200">
                <img
                  src={uploadedImage}
                  alt="Perfil"
                  className="w-full h-64 object-cover"
                />
              </div>
            </div>
          )}

          {!uploadedImage && !loading && (
            <div className="bg-gray-50 rounded-lg p-8 text-center">
              <p className="text-gray-500">No hay foto subida aún</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

