import * as http from 'http';
import * as url from 'url';

interface StoredImage {
  image: string;
  filename: string;
}

let storedImage: StoredImage | null = null;

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url || '', true);
  const pathname = parsedUrl.pathname || '';

  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  // GET /api/image - retrieve current image
  if (req.method === 'GET' && pathname === '/api/image') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(storedImage || { image: null }));
    return;
  }

  // POST /api/image - upload new image
  if (req.method === 'POST' && pathname === '/api/image') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
      if (body.length > 50 * 1024 * 1024) {
        req.connection.destroy();
      }
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        if (!data.image || !data.filename) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing image or filename' }));
          return;
        }

        storedImage = {
          image: data.image,
          filename: data.filename,
        };

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(storedImage));
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
    return;
  }

  // 404 for other routes
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

