import { createServer } from 'node:http'
import { URL } from 'node:url'

interface ImageData {
  imageBase64: string
  mimeType: string
}

let storedImage: ImageData | null = null

const PORT = process.env.PORT || 3000

async function parseFormData(req: any): Promise<{ fields: Record<string, string>; files: Record<string, Buffer> }> {
  return new Promise((resolve, reject) => {
    let body = Buffer.alloc(0)

    req.on('data', (chunk: Buffer) => {
      body = Buffer.concat([body, chunk])
    })

    req.on('end', () => {
      try {
        const contentType = req.headers['content-type'] || ''
        const boundary = contentType.split('boundary=')[1]

        if (!boundary) {
          resolve({ fields: {}, files: {} })
          return
        }

        const parts = body.toString('binary').split('--' + boundary)
        const fields: Record<string, string> = {}
        const files: Record<string, Buffer> = {}

        for (const part of parts) {
          if (part.includes('Content-Disposition')) {
            const isFile = part.includes('filename=')

            if (isFile) {
              const nameMatch = part.match(/name="([^"]+)"/)
              const filenameMatch = part.match(/filename="([^"]+)"/)
              const mimeMatch = part.match(/Content-Type: ([^\r\n]+)/)

              if (nameMatch && filenameMatch && mimeMatch) {
                const name = nameMatch[1]
                const filename = filenameMatch[1]
                const mimeType = mimeMatch[1]

                const headerEndIndex = part.indexOf('\r\n\r\n')
                const footerStartIndex = part.lastIndexOf('\r\n')

                if (headerEndIndex !== -1) {
                  const fileContent = Buffer.from(
                    part.substring(headerEndIndex + 4, footerStartIndex),
                    'binary'
                  )
                  files[name] = fileContent

                  if (name === 'file') {
                    const base64 = fileContent.toString('base64')
                    storedImage = {
                      imageBase64: base64,
                      mimeType: mimeType,
                    }
                  }
                }
              }
            } else {
              const nameMatch = part.match(/name="([^"]+)"/)
              if (nameMatch) {
                const name = nameMatch[1]
                const headerEndIndex = part.indexOf('\r\n\r\n')
                const footerStartIndex = part.lastIndexOf('\r\n')
                if (headerEndIndex !== -1) {
                  const value = part.substring(headerEndIndex + 4, footerStartIndex)
                  fields[name] = value
                }
              }
            }
          }
        }

        resolve({ fields, files })
      } catch (error) {
        reject(error)
      }
    })

    req.on('error', reject)
  })
}

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*')
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type')
  res.setHeader('Content-Type', 'application/json')

  if (req.method === 'OPTIONS') {
    res.writeHead(200)
    res.end()
    return
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`)
  const pathname = url.pathname

  if (pathname === '/api/upload' && req.method === 'POST') {
    try {
      await parseFormData(req)

      res.writeHead(200)
      res.end(JSON.stringify({ imageUrl: '/api/image-data' }))
    } catch (error) {
      res.writeHead(500)
      res.end(JSON.stringify({ error: 'Error al subir la foto' }))
    }
  } else if (pathname === '/api/image' && req.method === 'GET') {
    if (storedImage) {
      res.writeHead(200)
      res.end(JSON.stringify({ imageUrl: '/api/image-data' }))
    } else {
      res.writeHead(200)
      res.end(JSON.stringify({ imageUrl: null }))
    }
  } else if (pathname === '/api/image-data' && req.method === 'GET') {
