    res.writeHead(200)
    res.end()
    return
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`)
  const pathname = url.pathname

  if (pathname === '/api/upload' && req.method === 'POST') {
    res.setHeader('Content-Type', 'application/json')
    try {
      await parseFormData(req)

      res.writeHead(200)
      res.end(JSON.stringify({ success: true }))
    } catch (error) {
      console.error('Error al subir:', error)
      res.writeHead(500)
      res.end(JSON.stringify({ error: 'Error al subir la foto' }))
    }
  } else if (pathname === '/api/image' && req.method === 'GET') {
    res.setHeader('Content-Type', 'application/json')
    if (storedImage) {
      const dataUrl = `data:${storedImage.mimeType};base64,${storedImage.imageBase64}`
      res.writeHead(200)
      res.end(JSON.stringify({ imageUrl: dataUrl }))
    } else {
      res.writeHead(200)
      res.end(JSON.stringify({ imageUrl: null }))
    }
  } else {
    res.setHeader('Content-Type', 'application/json')
    res.writeHead(404)
    res.end(JSON.stringify({ error: 'Not Found' }))
