import { createServer, IncomingMessage, ServerResponse } from 'node:http'
import { URL } from 'node:url'

const PORT = process.env.PORT || 3000

interface StoredImage {
  data: string
  mimeType: string
}

const storage: { image: StoredImage | null } = {
  image: null,
}

const parseMultipartFormData = async (
  req: IncomingMessage
): Promise<{ fields: Record<string, string>; files: Record<string, Buffer> }> => {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = []

    req.on('data', (chunk) => {
      chunks.push(chunk)
    })

    req.on('end', () => {
      try {
        const buffer = Buffer.concat(chunks)
        const contentType = req.headers['content-type'] || ''
        const boundary = contentType.split('boundary=')[1]

        if (!boundary) {
          reject(new Error('Invalid multipart form data'))
          return
        }

        const parts = buffer.toString().split(`--${boundary}`)
        const fields: Record<string, string> = {}
        const files: Record<string, Buffer> = {}

        parts.forEach((part) => {
          if (!part || part === '--\r\n' || part === '--') return

          const headerEnd = part.indexOf('\r\n\r\n')
          if (headerEnd === -1) return

          const headers = part.substring(0, headerEnd)
          const body = part.substring(headerEnd + 4).replace(/\r\n$/, '')

          const nameMatch = headers.match(/name="([^"]+)"/)
          const filenameMatch = headers.match(/filename="([^"]+)"/)

          if (nameMatch) {
            const name = nameMatch[1]
            if (filenameMatch) {
              files[name] = Buffer.from(body, 'binary')
            } else {
              fields[name] = body
            }
          }
        })

        resolve({ fields, files })
      } catch (error) {
        reject(error)
      }
    })

    req.on('error', reject)
  })
}

const sendJson = (res: ServerResponse, status: number, data: any) => {
  res.writeHead(status, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(data))
}

const handleUpload = async (req: IncomingMessage, res: ServerResponse) => {
  try {
    const { files } = await parseMultipartFormData(req)

    if (!files.image) {
      sendJson(res, 400, { error: 'No image provided' })
      return
    }

    const imageBuffer = files.image
    const mimeType = 'image/jpeg'
    const base64Data = imageBuffer.toString('base64')

    storage.image = {
      data: base64Data,
      mimeType,
    }

    sendJson(res, 200, {
      imageUrl: `/api/image-data`,
      message: 'Image uploaded successfully',
    })
  } catch (error) {
    sendJson(res, 500, { error: 'Upload failed' })
  }
}

const handleGetImage = (res: ServerResponse) => {
  if (storage.image) {
    sendJson(res, 200, {
      imageUrl: `/api/image-data`,
    })
  } else {
    sendJson(res, 200, {
      imageUrl: null,
    })
  }
}

const handleGetImageData = (res: ServerResponse) => {
  if (storage.image) {
    res.writeHead(200, { 'Content-Type': storage.image.mimeType })
    res.end(Buffer.from(storage.image.data, 'base64'))
  } else {
    res.writeHead(404, { 'Content-Type': 'text/plain' })
    res.end('Image not found')
  }
}

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*')
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type')

  if (req.method === 'OPTIONS') {
    res.writeHead(200)
    res.end()
    return
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`)

  if (url.pathname === '/api/upload' && req.method === 'POST') {
    await handleUpload(req, res)
  } else if (url.pathname === '/api/image' && req.method === 'GET') {
    handleGetImage(res)
  } else if (url.pathname === '/api/image-data' && req.method === 'GET') {
    handleGetImageData(res)
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: 'Not found' }))
  }
})

server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`)
})

