              alt="Foto de perfil"
              class="w-full h-auto rounded-lg shadow-md border border-gray-200"
            />
          </div>
        )}

        {!uploadedImage() && !error() && (
          <div class="text-center text-gray-500 text-sm">
            Sube una foto para comenzar
          </div>
        )}
