import { createSignal, Show, onMount } from 'solid-js';

export default function App() {
  const [selectedFile, setSelectedFile] = createSignal<File | null>(null);
  const [uploadedImage, setUploadedImage] = createSignal<string | null>(null);
  const [isLoading, setIsLoading] = createSignal(false);
  const [error, setError] = createSignal<string | null>(null);

  const handleFileChange = (e: Event) => {
    const input = e.target as HTMLInputElement;
    const file = input.files?.[0];
    if (file) {
      setSelectedFile(file);
      setError(null);
    }
  };

  const handleUpload = async () => {
    const file = selectedFile();
    if (!file) {
      setError('Por favor selecciona una foto');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('Error al subir la foto');
      }

      const data = await response.json();
      setUploadedImage(data.imageUrl);
      setSelectedFile(null);
      const input = document.querySelector('input[type="file"]') as HTMLInputElement;
      if (input) input.value = '';
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  };

  const loadImage = async () => {
    try {
      const response = await fetch('/api/image');
      if (response.ok) {
        const data = await response.json();
        if (data.imageUrl) {
          setUploadedImage(data.imageUrl);
        }
      }
    } catch (err) {
      console.error('Error al cargar la imagen:', err);
    }
  };

  onMount(() => {
    loadImage();
  });

  return (
    <div class="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div class="bg-white rounded-lg shadow-xl p-8 max-w-md w-full">
        <h1 class="text-3xl font-bold text-gray-800 mb-8 text-center">Mi Perfil</h1>

        <div class="space-y-6">
          {/* Sección de carga */}
          <div class="border-2 border-dashed border-indigo-300 rounded-lg p-6 bg-indigo-50">
            <label class="block text-sm font-medium text-gray-700 mb-3">
              Selecciona tu foto
            </label>
            <input
              type="file"
              accept="image/*"
              onChange={handleFileChange}
              class="block w-full text-sm text-gray-500
                file:mr-4 file:py-2 file:px-4
                file:rounded file:border-0
                file:text-sm file:font-semibold
                file:bg-indigo-50 file:text-indigo-700
                hover:file:bg-indigo-100 file:cursor-pointer"
            />
            <Show when={selectedFile()}>
              <p class="text-xs text-gray-600 mt-2">
                Archivo seleccionado: {selectedFile()?.name}
              </p>
            </Show>
          </div>

          {/* Botón de subida */}
          <button
            onClick={handleUpload}
            disabled={!selectedFile() || isLoading()}
            class="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-lg transition duration-200"
          >
            <Show when={isLoading()} fallback="Subir">
              Subiendo...
            </Show>
          </button>

          {/* Mensaje de error */}
          <Show when={error()}>
            <div class="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
              {error()}
            </div>
          </Show>

          {/* Foto subida */}
          <Show when={uploadedImage()}>
            <div class="mt-8 border-t pt-6">
              <h2 class="text-lg font-semibold text-gray-800 mb-4">Foto actual</h2>
              <div class="rounded-lg overflow-hidden shadow-md bg-gray-100">
                <img
                  src={uploadedImage()!}
                  alt="Foto de perfil"
                  class="w-full h-auto object-cover"
                />
              </div>
            </div>
          </Show>
        </div>
      </div>
    </div>
  );
}

