import * as http from 'node:http';
import * as url from 'node:url';

// Almacenamiento en memoria
let uploadedImageData: string | null = null;
let uploadedImageMimeType: string = 'image/jpeg';

const PORT = process.env.PORT || 3000;

const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const parsedUrl = url.parse(req.url || '', true);
  const pathname = parsedUrl.pathname || '';

  // GET /api/image - Devuelve la imagen subida
  if (pathname === '/api/image' && req.method === 'GET') {
    res.setHeader('Content-Type', 'application/json');
    if (uploadedImageData) {
      res.writeHead(200);
      res.end(JSON.stringify({
        imageUrl: `data:${uploadedImageMimeType};base64,${uploadedImageData}`,
      }));
    } else {
      res.writeHead(200);
      res.end(JSON.stringify({ imageUrl: null }));
    }
    return;
  }

  // POST /api/upload - Sube una nueva imagen
  if (pathname === '/api/upload' && req.method === 'POST') {
    const chunks: Buffer[] = [];

    req.on('data', (chunk) => {
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks);
        const contentType = req.headers['content-type'] || '';

        // Parsear multipart/form-data
        const boundaryMatch = contentType.match(/boundary=([^;]+)/);
        if (!boundaryMatch) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'No boundary found' }));
          return;
        }

        const boundary = boundaryMatch[1];
        const boundaryBuffer = Buffer.from(`--${boundary}`);

        let fileData: Buffer | null = null;
        let mimeType = 'image/jpeg';

        // Dividir por boundary
        let currentPos = 0;
        let boundaryPos = body.indexOf(boundaryBuffer);

        while (boundaryPos !== -1) {
          const nextBoundaryPos = body.indexOf(boundaryBuffer, boundaryPos + boundaryBuffer.length);
          const partStart = boundaryPos + boundaryBuffer.length;
          const partEnd = nextBoundaryPos === -1 ? body.length : nextBoundaryPos;

          const part = body.slice(partStart, partEnd).toString('binary');

          // Detectar Content-Type
          const mimeMatch = part.match(/Content-Type: (image\/[^\r\n]+)/);
          if (mimeMatch) {
            mimeType = mimeMatch[1];

            // Extraer contenido del archivo
            const contentStart = part.indexOf('\r\n\r\n');
            if (contentStart !== -1) {
              const contentStartPos = partStart + contentStart + 4;
              const contentEndPos = nextBoundaryPos === -1 ? body.length - 2 : nextBoundaryPos - 2;
              fileData = body.slice(contentStartPos, contentEndPos);
            }
          }

          boundaryPos = nextBoundaryPos;
        }

        if (!fileData || fileData.length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'No file data found' }));
          return;
        }

        // Guardar en memoria como base64
        uploadedImageData = fileData.toString('base64');
        uploadedImageMimeType = mimeType;

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          imageUrl: `data:${mimeType};base64,${uploadedImageData}`,
          message: 'Image uploaded successfully',
        }));
      } catch (error) {
        console.error('Upload error:', error);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Upload failed' }));
      }
    });
    return;
  }

  // 404
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

