import { createSignal, createMemo, Show } from 'solid-js';
import ProductList from './ProductList';
import ProductDetail from './ProductDetail';
import NotFound from './NotFound';

export default function App() {
  const [currentPath, setCurrentPath] = createSignal(window.location.pathname);

  window.addEventListener('popstate', () => {
    setCurrentPath(window.location.pathname);
  });

  const handleNavigation = (path: string) => {
    setCurrentPath(path);
    window.history.pushState({}, '', path);
  };

  const route = createMemo(() => {
    const path = currentPath();

    if (path === '/') {
      return { type: 'list' as const };
    }

    const match = path.match(/^\/productos\/(\d+)$/);
    if (match) {
      return { type: 'detail' as const, id: parseInt(match[1]) };
    }

    return { type: 'notfound' as const };
  });

  return (
    <div class="min-h-screen bg-gray-100 py-8 px-4">
      <Show when={route().type === 'list'}>
        <ProductList onNavigate={handleNavigation} />
      </Show>

      <Show when={route().type === 'detail'}>
        {() => (
          <ProductDetail 
            id={(route() as any).id} 
            onNavigate={handleNavigation} 
          />
        )}
      </Show>

      <Show when={route().type === 'notfound'}>
        <NotFound />
      </Show>
    </div>
  );
}

