import React, { useState } from 'react';

interface Contact {
  id: number;
  name: string;
  type: 'Amigo' | 'Trabajo';
}

export default function App() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [name, setName] = useState('');
  const [type, setType] = useState<'Amigo' | 'Trabajo'>('Amigo');

  const handleSave = () => {
    if (name.trim()) {
      const newContact: Contact = {
        id: Date.now(),
        name: name.trim(),
        type,
      };
      setContacts([...contacts, newContact]);
      setName('');
      setType('Amigo');
      setIsDialogOpen(false);
    }
  };

  const handleCancel = () => {
    setName('');
    setType('Amigo');
    setIsDialogOpen(false);
  };

  const handleOpenDialog = () => {
    setName('');
    setType('Amigo');
    setIsDialogOpen(true);
  };

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-6">Mis Contactos</h1>

        <button
          onClick={handleOpenDialog}
          className="w-full bg-blue-500 hover:bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg transition-colors mb-6"
        >
          Nuevo contacto
        </button>

        {contacts.length === 0 ? (
          <p className="text-gray-500 text-center py-4">No hay contactos aún</p>
        ) : (
          <ul className="space-y-2">
            {contacts.map((contact) => (
              <li
                key={contact.id}
                className="bg-gray-50 border border-gray-200 rounded-lg p-3 text-gray-800"
              >
                {contact.name} ({contact.type})
              </li>
            ))}
          </ul>
        )}
      </div>

      {isDialogOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-sm">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Nuevo Contacto</h2>

            <input
              type="text"
              placeholder="Nombre"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleSave();
                }
              }}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 mb-4 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />

            <select
              value={type}
              onChange={(e) => setType(e.target.value as 'Amigo' | 'Trabajo')}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 mb-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="Amigo">Amigo</option>
              <option value="Trabajo">Trabajo</option>
            </select>

            <div className="flex gap-3">
              <button
                onClick={handleCancel}
                className="flex-1 bg-gray-300 hover:bg-gray-400 text-gray-800 font-semibold py-2 px-4 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={handleSave}
                className="flex-1 bg-blue-500 hover:bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg transition-colors"
              >
                Guardar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

