component Paginator {
  state currentPage = 1
  computed itemsPerPage = 10
  computed totalItems = 23
  computed totalPages = Math.ceil(totalItems / itemsPerPage)
  computed startIndex = (currentPage - 1) * itemsPerPage
  computed endIndex = Math.min(startIndex + itemsPerPage, totalItems)
  computed items = Array.from({ length: endIndex - startIndex }, (_, i) => ({
    id: startIndex + i + 1,
    name: `Ítem ${startIndex + i + 1}`
  }))

  fn previousPage() {
    if currentPage > 1 {
      currentPage--
    }
  }

  fn nextPage() {
    if currentPage < totalPages {
      currentPage++
    }
  }

  column gap=4 {
    for item in items {
      text item.name
    }

    row gap=2 align=center {
      text `Página ${currentPage} de ${totalPages}`
      button "Anterior" disabled=currentPage == 1 -> previousPage()
      button "Siguiente" disabled=currentPage == totalPages -> nextPage()
    }
  }
}

page Home "/" {
  column gap=6 pad=4 {
    title "Paginación"
    Paginator
  }
}

