import React, { useState } from 'react';

const ITEMS_PER_PAGE = 10;
const TOTAL_ITEMS = 23;
const TOTAL_PAGES = Math.ceil(TOTAL_ITEMS / ITEMS_PER_PAGE);

export default function App() {
  const [currentPage, setCurrentPage] = useState(1);

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const endIndex = Math.min(startIndex + ITEMS_PER_PAGE, TOTAL_ITEMS);
  const items = Array.from({ length: TOTAL_ITEMS }, (_, i) => `Ítem ${i + 1}`);
  const currentItems = items.slice(startIndex, endIndex);

  const handlePrevious = () => {
    setCurrentPage((prev) => Math.max(prev - 1, 1));
  };

  const handleNext = () => {
    setCurrentPage((prev) => Math.min(prev + 1, TOTAL_PAGES));
  };

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-2xl mx-auto bg-white rounded-lg shadow-lg p-6">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Lista de Ítems</h1>

        <ul className="space-y-2 mb-8">
          {currentItems.map((item, index) => (
            <li
              key={startIndex + index}
              className="p-3 bg-gray-50 border border-gray-200 rounded hover:bg-gray-100 transition"
            >
              {item}
            </li>
          ))}
        </ul>

        <div className="flex flex-col items-center gap-4">
          <p className="text-gray-700 font-medium">
            Página {currentPage} de {TOTAL_PAGES}
          </p>

          <div className="flex gap-3">
            <button
              onClick={handlePrevious}
              disabled={currentPage === 1}
              className="px-4 py-2 bg-blue-500 text-white rounded font-medium hover:bg-blue-600 disabled:bg-gray-300 disabled:cursor-not-allowed transition"
            >
              Anterior
            </button>

            <button
              onClick={handleNext}
              disabled={currentPage === TOTAL_PAGES}
              className="px-4 py-2 bg-blue-500 text-white rounded font-medium hover:bg-blue-600 disabled:bg-gray-300 disabled:cursor-not-allowed transition"
            >
              Siguiente
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

