component Stopwatch {
  state elapsed = 0
  state running = false
  ref intervalId = null

  fn start() {
    if running { return }
    running = true
    intervalId = setInterval(() => {
      elapsed++
    }, 100)
  }

  fn pause() {
    running = false
    if intervalId != null {
      clearInterval(intervalId)
      intervalId = null
    }
  }

  fn restart() {
    pause()
    elapsed = 0
  }

  mount {
    cleanup {
      if intervalId != null {
        clearInterval(intervalId)
      }
    }
  }

  column gap=4 align=center pad=6 {
    title "Cronómetro"
    text `Tiempo: ${elapsed}`
    row gap=3 {
      button "Iniciar" primary -> start()
      button "Pausar" -> pause()
      button "Reiniciar" danger -> restart()
    }
  }
}

