import React, { useState, useRef, useEffect } from 'react';

export default function App() {
  const [time, setTime] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const intervalRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const handleStart = () => {
    if (isRunning) return;

    setIsRunning(true);
    intervalRef.current = window.setInterval(() => {
      setTime((prevTime) => prevTime + 1);
    }, 100);
  };

  const handlePause = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
    setIsRunning(false);
  };

  const handleRestart = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
    setTime(0);
    setIsRunning(false);
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-blue-500 to-purple-600">
      <div className="bg-white rounded-lg shadow-2xl p-8 w-80">
        <h1 className="text-3xl font-bold text-center text-gray-800 mb-8">
          Cronómetro
        </h1>

        <div className="bg-gray-100 rounded-lg p-6 mb-8 text-center">
          <p className="text-5xl font-bold text-blue-600">
            Tiempo: {time}
          </p>
        </div>

        <div className="flex flex-col gap-4">
          <button
            onClick={handleStart}
            disabled={isRunning}
            className="bg-green-500 hover:bg-green-600 disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200"
          >
            Iniciar
          </button>

          <button
            onClick={handlePause}
            disabled={!isRunning}
            className="bg-yellow-500 hover:bg-yellow-600 disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200"
          >
            Pausar
          </button>

          <button
            onClick={handleRestart}
            className="bg-red-500 hover:bg-red-600 text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200"
          >
            Reiniciar
          </button>
        </div>
      </div>
    </div>
  );
}

import { createSignal } from 'solid-js';

export default function App() {
  const [tiempo, setTiempo] = createSignal(0);
  const [esActivo, setEsActivo] = createSignal(false);

  let intervalo: number | undefined;

  const iniciar = () => {
    if (esActivo()) return;

    setEsActivo(true);
    intervalo = setInterval(() => {
      setTiempo(t => t + 1);
    }, 100);
  };

  const pausar = () => {
    setEsActivo(false);
    if (intervalo !== undefined) {
      clearInterval(intervalo);
      intervalo = undefined;
    }
  };

  const reiniciar = () => {
    setEsActivo(false);
    if (intervalo !== undefined) {
      clearInterval(intervalo);
      intervalo = undefined;
    }
    setTiempo(0);
  };

  return (
    <div class="flex items-center justify-center min-h-screen bg-gray-100">
      <div class="bg-white rounded-lg shadow-lg p-8 w-80">
        <h1 class="text-3xl font-bold text-center mb-8 text-gray-800">
          Tiempo: {tiempo()}
        </h1>

        <div class="flex gap-4">
          <button
            onClick={iniciar}
            class="flex-1 bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-4 rounded transition"
          >
            Iniciar
          </button>

          <button
            onClick={pausar}
            class="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-2 px-4 rounded transition"
          >
            Pausar
          </button>

          <button
            onClick={reiniciar}
            class="flex-1 bg-red-500 hover:bg-red-600 text-white font-bold py-2 px-4 rounded transition"
          >
            Reiniciar
          </button>
        </div>
      </div>
    </div>
  );
}

