import React, { useState } from 'react';

export default function App() {
  const [likes, setLikes] = useState(0);
  const [currentPath, setCurrentPath] = useState('/');

  const navigate = (path: string) => {
    setCurrentPath(path);
    window.history.pushState(null, '', path);
  };

  const renderContent = () => {
    if (currentPath === '/') {
      return (
        <div className="p-8">
          <h1 className="text-4xl font-bold text-gray-800">Bienvenido</h1>
        </div>
      );
    }

    if (currentPath === '/equipo') {
      return (
        <div className="p-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-6">Nuestro equipo</h1>
          <div className="flex gap-4">
            <button
              onClick={() => navigate('/equipo/ana')}
              className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition"
            >
              Ana
            </button>
            <button
              onClick={() => navigate('/equipo/beto')}
              className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition"
            >
              Beto
            </button>
          </div>
        </div>
      );
    }

    const equipoMatch = currentPath.match(/^\/equipo\/(.+)$/);
    if (equipoMatch) {
      const nombre = equipoMatch[1];
      return (
        <div className="p-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-6">
            Perfil de {nombre}
          </h1>
          <button
            onClick={() => navigate('/equipo')}
            className="px-6 py-2 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition"
          >
            Volver al equipo
          </button>
        </div>
      );
    }

    return (
      <div className="p-8">
        <h1 className="text-4xl font-bold text-gray-800">Página no encontrada</h1>
      </div>
    );
  };

  React.useEffect(() => {
    const handlePopState = () => {
      setCurrentPath(window.location.pathname);
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  return (
    <div className="min-h-screen bg-gray-50">
      <nav className="bg-white shadow-md sticky top-0">
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex gap-6">
            <button
