import React, { useState, useEffect } from 'react';

const PRODUCTS = ['Mesa', 'Silla', 'Sillón', 'Lámpara'];

export default function App() {
  const [searchInput, setSearchInput] = useState('');
  const [query, setQuery] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const q = params.get('q') || '';
    setQuery(q);
    setSearchInput(q);
  }, []);

  const handleSearch = () => {
    const newQuery = searchInput.trim().toLowerCase();
    setQuery(newQuery);
    const url = newQuery ? `/?q=${encodeURIComponent(newQuery)}` : '/';
    window.history.pushState(null, '', url);
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const filteredProducts = query
    ? PRODUCTS.filter(product =>
        product.toLowerCase().includes(query.toLowerCase())
      )
    : PRODUCTS;

  return (
    <div className="min-h-screen bg-gray-100 py-12 px-4">
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-3xl font-bold text-gray-800 mb-6">Búsqueda</h1>

          <div className="flex gap-2 mb-8">
            <input
              type="text"
              placeholder="Buscar"
              value={searchInput}
              onChange={e => setSearchInput(e.target.value)}
              onKeyPress={handleKeyPress}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleSearch}
              className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors font-medium"
            >
              Buscar
            </button>
          </div>

          <div className="bg-gray-50 rounded-lg p-6">
            <p className="text-gray-700 font-semibold mb-4">
              Resultados: {filteredProducts.length}
            </p>

            <ul className="space-y-3">
              {filteredProducts.map(product => (
                <li
                  key={product}
                  className="px-4 py-3 bg-white border border-gray-200 rounded-lg text-gray-800 hover:bg-blue-50 transition-colors"
                >
                  {product}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';

const products = ['Mesa', 'Silla', 'Sillón', 'Lámpara'];

export default function App() {
  const [searchInput, setSearchInput] = useState('');
  const [query, setQuery] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const q = params.get('q') || '';
    setQuery(q);
    setSearchInput(q);
  }, []);

  const handleSearch = () => {
    const params = new URLSearchParams();
    if (searchInput) {
      params.set('q', searchInput);
    }
    window.history.replaceState(null, '', `/?${params.toString()}`);
    setQuery(searchInput);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchInput(e.target.value);
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const filteredProducts = products.filter((product) =>
    product.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-md mx-auto bg-white rounded-lg shadow-md p-6">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Búsqueda de Productos</h1>

        <div className="flex gap-2 mb-6">
          <input
            type="text"
            placeholder="Buscar"
            value={searchInput}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            onClick={handleSearch}
            className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors font-semibold"
          >
            Buscar
          </button>
        </div>

        <div className="mb-4">
          <p className="text-lg font-semibold text-gray-700">
            Resultados: {filteredProducts.length}
          </p>
        </div>

        <ul className="space-y-2">
          {filteredProducts.map((product) => (
            <li
              key={product}
              className="p-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-800 hover:bg-gray-100 transition-colors"
            >
              {product}
            </li>
          ))}
        </ul>

        {filteredProducts.length === 0 && query && (
          <p className="text-center text-gray-500 mt-4">No hay productos que coincidan con tu búsqueda.</p>
        )}
      </div>
    </div>
  );
}

