import { createSignal, createMemo } from 'solid-js';
import { useSearchParams } from '@solidjs/router';
import { useNavigate } from '@solidjs/router';
import ProductList from '../components/ProductList';
import SearchBar from '../components/SearchBar';

const PRODUCTS = ['Mesa', 'Silla', 'Sillón', 'Lámpara'];

export default function SearchPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [inputValue, setInputValue] = createSignal('');

  const query = createMemo(() => searchParams.q || '');

  const filteredProducts = createMemo(() => {
    const q = query().toLowerCase();
    if (!q) return PRODUCTS;
    return PRODUCTS.filter(product => product.toLowerCase().includes(q));
  });

  const handleSearch = (text: string) => {
    setInputValue(text);
    navigate(`/?q=${encodeURIComponent(text)}`);
  };

  return (
    <div class="min-h-screen bg-gray-50 p-8">
      <div class="max-w-2xl mx-auto">
        <h1 class="text-3xl font-bold mb-8 text-gray-900">Búsqueda de Productos</h1>
        <SearchBar onSearch={handleSearch} />
        <ProductList products={filteredProducts()} count={filteredProducts().length} />
      </div>
    </div>
  );
}

