  state name = ""
  state plan = "Gratis"
  state newsletter = false
  state completed = false
  state nameError = ""

  fn nextStep {
    if step == 1 {
      if name == "" {
        nameError = "Nombre requerido"
        return
      }
      nameError = ""
      step = 2
    } else if step == 2 {
      step = 3
    }
  }

  fn prevStep {
    if step > 1 {
      step = step - 1
      nameError = ""
    }
  }

  fn confirm {
    completed = true
  }

  if completed {
    column gap=4 align=center pad=6 {
      title `¡Listo, ${name}!` large
