import React, { useState } from 'react';

export default function App() {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  const [plan, setPlan] = useState('Gratis');
  const [newsletter, setNewsletter] = useState(false);
  const [error, setError] = useState('');
  const [completed, setCompleted] = useState(false);

  const handleNextStep1 = () => {
    if (name.trim() === '') {
      setError('Nombre requerido');
      return;
    }
    setError('');
    setStep(2);
  };

  const handleNextStep2 = () => {
    setError('');
    setStep(3);
  };

  const handleBackStep2 = () => {
    setError('');
    setStep(1);
  };

  const handleBackStep3 = () => {
    setError('');
    setStep(2);
  };

  const handleConfirm = () => {
    setCompleted(true);
  };

  if (completed) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
        <div className="bg-white rounded-lg shadow-lg p-8 text-center">
          <h1 className="text-4xl font-bold text-green-600">¡Listo, {name}!</h1>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      <div className="bg-white rounded-lg shadow-lg p-8 w-full max-w-md">
        <div className="mb-6">
          <p className="text-center text-gray-600 font-semibold">
            Paso {step} de 3
          </p>
        </div>

        {step === 1 && (
          <div className="space-y-4">
            <div>
              <input
                type="text"
                placeholder="Nombre"
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  setError('');
                }}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              {error && (
                <p className="text-red-500 text-sm mt-2">{error}</p>
              )}
            </div>
            <button
              onClick={handleNextStep1}
              className="w-full bg-blue-600 text-white py-2 rounded-lg font-semibold hover:bg-blue-700 transition-colors"
            >
              Siguiente
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4">
            <div>
              <label className="block text-gray-700 font-semibold mb-2">
                Plan
              </label>
              <select
                value={plan}
                onChange={(e) => setPlan(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="Gratis">Gratis</option>
                <option value="Pro">Pro</option>
              </select>
            </div>
            <div className="flex items-center">
              <input
                type="checkbox"
                id="newsletter"
                checked={newsletter}
                onChange={(e) => setNewsletter(e.target.checked)}
                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
              />
              <label htmlFor="newsletter" className="ml-2 text-gray-700">
                Recibir novedades
              </label>
            </div>
            <div className="flex gap-3">
              <button
                onClick={handleBackStep2}
                className="flex-1 bg-gray-400 text-white py-2 rounded-lg font-semibold hover:bg-gray-500 transition-colors"
              >
                Atrás
              </button>
              <button
                onClick={handleNextStep2}
                className="flex-1 bg-blue-600 text-white py-2 rounded-lg font-semibold hover:bg-blue-700 transition-colors"
              >
                Siguiente
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4">
            <div className="bg-gray-100 p-4 rounded-lg">
              <p className="text-gray-800">
                <span className="font-semibold">{name}</span> eligió{' '}
                <span className="font-semibold">{plan}</span>
              </p>
              {newsletter && (
                <p className="text-gray-800 mt-2">Con novedades</p>
              )}
            </div>
            <div className="flex gap-3">
              <button
                onClick={handleBackStep3}
                className="flex-1 bg-gray-400 text-white py-2 rounded-lg font-semibold hover:bg-gray-500 transition-colors"
              >
                Atrás
              </button>
              <button
                onClick={handleConfirm}
                className="flex-1 bg-green-600 text-white py-2 rounded-lg font-semibold hover:bg-green-700 transition-colors"
              >
                Confirmar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

