            </div>
          </div>
        )}

        {/* Paso 3: Resumen */}
        {step === 3 && (
          <div className="space-y-4">
            <div className="bg-gray-50 p-4 rounded-lg border border-gray-200">
              <p className="text-gray-800">
                <span className="font-semibold">{nombre}</span> eligió <span className="font-semibold">{plan}</span>
