              >
                Confirmar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { createSignal, createMemo, Show } from "solid-js";
import Step1 from "./components/Step1";
import Step2 from "./components/Step2";
import Step3 from "./components/Step3";
import Success from "./components/Success";

export default function App() {
  const [currentStep, setCurrentStep] = createSignal(1);
  const [name, setName] = createSignal("");
  const [plan, setPlan] = createSignal("Gratis");
  const [newsletter, setNewsletter] = createSignal(false);
  const [isConfirmed, setIsConfirmed] = createSignal(false);

  const handleNext = (stepData?: { name?: string; plan?: string; newsletter?: boolean }) => {
    if (stepData?.name !== undefined) setName(stepData.name);
    if (stepData?.plan !== undefined) setPlan(stepData.plan);
    if (stepData?.newsletter !== undefined) setNewsletter(stepData.newsletter);
    setCurrentStep(currentStep() + 1);
  };

  const handleBack = () => {
    setCurrentStep(currentStep() - 1);
  };

  const handleConfirm = () => {
    setIsConfirmed(true);
  };

  return (
    <div class="flex items-center justify-center min-h-screen bg-gray-100">
      <Show
        when={!isConfirmed()}
        fallback={<Success name={name()} />}
      >
        <div class="w-full max-w-md bg-white rounded-lg shadow-lg p-8">
          <h1 class="text-3xl font-bold text-center mb-8 text-gray-800">
