          </div>

          <Show when={currentStep() === 1}>
            <Step1
              name={name()}
              onNext={handleNext}
            />
          </Show>

          <Show when={currentStep() === 2}>
            <Step2
              plan={plan()}
              newsletter={newsletter()}
              onBack={handleBack}
              onNext={handleNext}
            />
          </Show>

          <Show when={currentStep() === 3}>
            <Step3
              name={name()}
              plan={plan()}
              newsletter={newsletter()}
              onBack={handleBack}
              onConfirm={handleConfirm}
            />
          </Show>
        </div>
      </Show>
    </div>
  );
}

