          <Show when={currentStep() === 2}>
            <Step2
              onNext={handleNextStep2}
              onBack={handleBackStep2}
              initialPlan={plan()}
              initialNewsletter={newsletter()}
            />
          </Show>

          <Show when={currentStep() === 3}>
            <Step3
              name={name()}
              plan={plan()}
              newsletter={newsletter()}
              onBack={handleBackStep3}
              onConfirm={handleConfirm}
            />
          </Show>
        </Show>
      </div>
    </div>
  );
}

