function NoteItem({ note, onUpdate }: { note: Note; onUpdate: (text: string) => void }) {
  const [isEditing, setIsEditing] = useState(false);
  const [tempText, setTempText] = useState(note.text);

  const handleEdit = () => {
    setTempText(note.text);
    setIsEditing(true);
  };

  const handleSave = () => {
    onUpdate(tempText);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setIsEditing(false);
  };

  return (
    <div className="flex items-center justify-between p-4 bg-white border border-gray-300 rounded shadow mb-2">
      {!isEditing ? (
        <>
          <span className="text-gray-800">{note.text}</span>
          <button
            onClick={handleEdit}
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
          >
            Editar
          </button>
        </>
      ) : (
        <>
          <input
            type="text"
            value={tempText}
            onChange={(e) => setTempText(e.target.value)}
            className="flex-1 px-3 py-2 border border-gray-300 rounded mr-2"
          />
          <div className="flex gap-2">
            <button
              onClick={handleSave}
              className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600 transition"
            >
