import { createSignal } from 'solid-js';
import { Show } from 'solid-js';

interface NoteProps {
  id: number;
  initialText: string;
  onSave: (id: number, newText: string) => void;
}

export default function Note(props: NoteProps) {
  const [isEditing, setIsEditing] = createSignal(false);
  const [text, setText] = createSignal(props.initialText);
  const [inputValue, setInputValue] = createSignal(props.initialText);

  const handleEdit = () => {
    setInputValue(text());
    setIsEditing(true);
  };

  const handleSave = () => {
    setText(inputValue());
    props.onSave(props.id, inputValue());
    setIsEditing(false);
  };

  const handleCancel = () => {
    setInputValue(text());
    setIsEditing(false);
  };

  return (
    <div class="bg-white p-4 rounded-lg shadow-md">
      <Show
        when={!isEditing()}
        fallback={
          <div class="space-y-2">
            <input
              type="text"
              value={inputValue()}
              onInput={(e) => setInputValue(e.currentTarget.value)}
              class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              autofocus
            />
            <div class="flex gap-2">
              <button
                onClick={handleSave}
                class="flex-1 bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-md transition"
              >
                Guardar
              </button>
              <button
                onClick={handleCancel}
                class="flex-1 bg-gray-400 hover:bg-gray-500 text-white font-semibold py-2 px-4 rounded-md transition"
              >
                Cancelar
              </button>
            </div>
          </div>
        }
      >
        <div class="flex justify-between items-center">
          <p class="text-gray-800">{text()}</p>
          <button
            onClick={handleEdit}
            class="bg-blue-500 hover:bg-blue-600 text-white font-semibold py-1 px-3 rounded-md transition"
          >
            Editar
          </button>
        </div>
      </Show>
    </div>
  );
}

