api tasks: Task

component TaskItem(task: Task, onUpdate: Fn) {
  state editing = false
  state newTitle = task.title

  fn saveTitle() {
    if newTitle.trim() == "" { return }
    try {
      await api.tasks.update(task.id, { title: newTitle })
      editing = false
      onUpdate()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn markDone() {
    try {
      await api.tasks.update(task.id, { completed: true })
      onUpdate()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn deleteTask() {
    try {
      await api.tasks.remove(task.id)
      onUpdate()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  row gap=2 align=center {
    if editing {
      input newTitle placeholder="Nuevo título"
