import React, { useState, useEffect } from 'react';

interface Task {
  id: string;
  title: string;
  completed: boolean;
}

type FilterType = 'all' | 'pending' | 'completed';

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [filter, setFilter] = useState<FilterType>('all');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingTitle, setEditingTitle] = useState('');
  const [loading, setLoading] = useState(true);

  // Fetch initial tasks
  useEffect(() => {
    const fetchTasks = async () => {
      try {
        const response = await fetch('/api/tasks');
        const data = await response.json();
        setTasks(data);
      } catch (error) {
        console.error('Error fetching tasks:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchTasks();
  }, []);

  const addTask = async () => {
    if (!inputValue.trim()) return;

    try {
      const response = await fetch('/api/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: inputValue }),
      });

      const newTask = await response.json();
      setTasks([...tasks, newTask]);
      setInputValue('');
    } catch (error) {
      console.error('Error adding task:', error);
    }
  };

  const markAsDone = async (id: string) => {
    try {
      const response = await fetch(`/api/tasks/${id}/complete`, {
        method: 'PATCH',
      });

      const updatedTask = await response.json();
      setTasks(tasks.map((t) => (t.id === id ? updatedTask : t)));
    } catch (error) {
      console.error('Error marking task as done:', error);
    }
  };

  const saveRename = async (id: string) => {
    if (!editingTitle.trim()) return;

    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: editingTitle }),
      });

      const updatedTask = await response.json();
      setTasks(tasks.map((t) => (t.id === id ? updatedTask : t)));
      setEditingId(null);
      setEditingTitle('');
    } catch (error) {
      console.error('Error renaming task:', error);
    }
  };

  const startEditingRename = (task: Task) => {
    setEditingId(task.id);
    setEditingTitle(task.title);
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditingTitle('');
  };

  const filteredTasks = tasks.filter((task) => {
    if (filter === 'completed') return task.completed;
    if (filter === 'pending') return !task.completed;
    return true;
  });

  if (loading) {
    return <div className="flex items-center justify-center min-h-screen text-gray-600">Cargando...</div>;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8 text-center">Gestor de Tareas</h1>

        {/* Add Task Section */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Tarea"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') addTask();
              }}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={addTask}
              className="bg-blue-500 hover:bg-blue-600 text-white font-semibold px-6 py-2 rounded-lg transition-colors"
            >
              Agregar
            </button>
          </div>
        </div>

        {/* Filter Section */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <label className="block text-sm font-medium text-gray-700 mb-2">Filtrar por:</label>
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value as FilterType)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="all">Todas</option>
            <option value="pending">Pendientes</option>
            <option value="completed">Hechas</option>
          </select>
        </div>

        {/* Tasks List */}
        <div className="space-y-3">
          {filteredTasks.length === 0 ? (
            <div className="text-center text-gray-500 py-8">
              {tasks.length === 0 ? 'No hay tareas aún' : 'No hay tareas en este filtro'}
            </div>
          ) : (
            filteredTasks.map((task) => (
              <div
                key={task.id}
                className="bg-white rounded-lg shadow-md p-4 flex items-center justify-between hover:shadow-lg transition-shadow"
              >
                <div className="flex-1">
                  {editingId === task.id ? (
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={editingTitle}
                        onChange={(e) => setEditingTitle(e.target.value)}
                        placeholder="Nuevo título"
                        className="flex-1 px-3 py-1 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                      <button
                        onClick={() => saveRename(task.id)}
                        className="bg-green-500 hover:bg-green-600 text-white font-semibold px-4 py-1 rounded transition-colors text-sm"
                      >
                        Guardar
                      </button>
                      <button
                        onClick={cancelEditing}
                        className="bg-gray-400 hover:bg-gray-500 text-white font-semibold px-4 py-1 rounded transition-colors text-sm"
                      >
                        Cancelar
                      </button>
                    </div>
                  ) : (
                    <p className={`text-lg ${task.completed ? 'line-through text-gray-500' : 'text-gray-800'}`}>
                      {task.title}
                      {task.completed && <span className="ml-2 text-sm text-gray-500">(hecha)</span>}
                    </p>
                  )}
                </div>

                {editingId !== task.id && (
                  <div className="flex gap-2 ml-4">
                    {!task.completed && (
                      <button
                        onClick={() => markAsDone(task.id)}
                        className="bg-green-500 hover:bg-green-600 text-white font-semibold px-4 py-1 rounded transition-colors text-sm"
                      >
                        Hecha
                      </button>
                    )}
                    <button
                      onClick={() => startEditingRename(task)}
                      className="bg-indigo-500 hover:bg-indigo-600 text-white font-semibold px-4 py-1 rounded transition-colors text-sm"
                    >
                      Renombrar
                    </button>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

