import * as http from 'node:http';

interface Task {
	id: string;
	title: string;
	completed: boolean;
}

const tasks: Map<string, Task> = new Map();
let nextId = 1;

const PORT = process.env.PORT || 5173;

const server = http.createServer((req, res) => {
	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

	if (req.method === 'OPTIONS') {
		res.writeHead(200);
		res.end();
		return;
	}

	const url = new URL(req.url || '', `http://${req.headers.host}`);
	const pathname = url.pathname;

	if (pathname === '/api/tasks' && req.method === 'GET') {
		handleGetTasks(res);
	} else if (pathname === '/api/tasks' && req.method === 'POST') {
		handleCreateTask(req, res);
	} else if (pathname.match(/^\/api\/tasks\/[^/]+$/) && req.method === 'PATCH') {
		const id = pathname.split('/')[3];
		const match = pathname.match(/\/(complete)$/);
		if (match) {
			handleToggleComplete(id, res);
		} else {
			handleUpdateTask(id, req, res);
		}
	} else if (pathname.match(/^\/api\/tasks\/[^/]+\/complete$/) && req.method === 'PATCH') {
		const id = pathname.split('/')[3];
		handleToggleComplete(id, res);
	} else {
		res.writeHead(404, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify({ error: 'Not found' }));
	}
});

function handleGetTasks(res: http.ServerResponse) {
	const taskList = Array.from(tasks.values());
	res.writeHead(200, { 'Content-Type': 'application/json' });
	res.end(JSON.stringify(taskList));
}

function handleCreateTask(req: http.IncomingMessage, res: http.ServerResponse) {
	let body = '';

	req.on('data', (chunk) => {
		body += chunk.toString();
	});

	req.on('end', () => {
		try {
			const { title } = JSON.parse(body);
			const id = String(nextId++);
			const task: Task = { id, title, completed: false };
			tasks.set(id, task);

			res.writeHead(201, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify(task));
		} catch (error) {
			res.writeHead(400, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify({ error: 'Invalid request' }));
		}
	});
}

function handleToggleComplete(id: string, res: http.ServerResponse) {
	const task = tasks.get(id);
	if (!task) {
		res.writeHead(404, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify({ error: 'Task not found' }));
		return;
	}

	task.completed = true;
	res.writeHead(200, { 'Content-Type': 'application/json' });
	res.end(JSON.stringify(task));
}

function handleUpdateTask(id: string, req: http.IncomingMessage, res: http.ServerResponse) {
	let body = '';

	req.on('data', (chunk) => {
