                    <Show
                      when={editingId() === task.id}
                      fallback={
                        <div class="flex-1 flex items-center justify-between">
                          <div class="flex items-center gap-3">
                            <span
                              class={`text-lg ${
                                task.completed
                                  ? 'line-through text-gray-500'
                                  : 'text-gray-800'
                              }`}
                            >
                              {task.title}
                            </span>
                            <Show when={task.completed}>
                              <span class="text-sm text-green-600 font-medium">
                                (hecha)
                              </span>
                            </Show>
                          </div>
                          <div class="flex gap-2">
                            <Show when={!task.completed}>
                              <button
                                onClick={() => markComplete(task.id)}
                                class="px-3 py-1 bg-green-500 text-white rounded hover:bg-green-600 transition text-sm font-medium"
                              >
                                Hecha
                              </button>
                            </Show>
                            <button
                              onClick={() => startRename(task)}
                              class="px-3 py-1 bg-indigo-500 text-white rounded hover:bg-indigo-600 transition text-sm font-medium"
                            >
                              Renombrar
                            </button>
                          </div>
                        </div>
                      }
                    >
                      <div class="flex-1 flex gap-2">
                        <input
                          type="text"
                          placeholder="Nuevo título"
                          value={editValue()}
                          onInput={(e) => setEditValue(e.currentTarget.value)}
                          onKeyDown={(e) => handleKeyDown(e, task.id)}
                          autoFocus
