import * as http from 'node:http';

interface Task {
  id: string;
  title: string;
  completed: boolean;
}

let tasks: Task[] = [];
let nextId = 1;

const parseBody = (req: http.IncomingMessage): Promise<any> => {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
};

const sendJson = (
  res: http.ServerResponse,
  statusCode: number,
  data: any
) => {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
};

const server = http.createServer(async (req, res) => {
  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // GET /api/tasks
  if (pathname === '/api/tasks' && req.method === 'GET') {
    sendJson(res, 200, tasks);
    return;
  }

  // POST /api/tasks
  if (pathname === '/api/tasks' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const newTask: Task = {
        id: `task-${nextId++}`,
        title: body.title,
        completed: false,
      };
      tasks.push(newTask);
      sendJson(res, 201, newTask);
    } catch {
      sendJson(res, 400, { error: 'Invalid request' });
    }
    return;
  }

  // PATCH /api/tasks/:id
  const taskIdMatch = pathname.match(/^\/api\/tasks\/(task-\d+)$/);
  if (taskIdMatch && req.method === 'PATCH') {
    const taskId = taskIdMatch[1];
    try {
      const body = await parseBody(req);
      const task = tasks.find((t) => t.id === taskId);
      if (!task) {
        sendJson(res, 404, { error: 'Task not found' });
        return;
      }
      if (body.title) {
        task.title = body.title;
      }
      sendJson(res, 200, task);
    } catch {
      sendJson(res, 400, { error: 'Invalid request' });
    }
    return;
  }

  // PATCH /api/tasks/:id/complete
  const completeMatch = pathname.match(/^\/api\/tasks\/(task-\d+)\/complete$/);
  if (completeMatch && req.method === 'PATCH') {
    const taskId = completeMatch[1];
    const task = tasks.find((t) => t.id === taskId);
    if (!task) {
      sendJson(res, 404, { error: 'Task not found' });
      return;
    }
    task.completed = true;
    sendJson(res, 200, task);
    return;
  }

  sendJson(res, 404, { error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

