      setTasks(tasks().map((t) => (t.id === id ? updated : t)));
    } catch (error) {
      console.error('Error completing task:', error);
    }
  };

  const startRename = (id: string, currentTitle: string) => {
    setEditingId(id);
    setEditValue(currentTitle);
  };

  const saveRename = async (id: string) => {
    if (!editValue().trim()) return;
    try {
      const res = await fetch(`/api/tasks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: editValue() }),
      });
      const updated = await res.json();
      setTasks(tasks().map((t) => (t.id === id ? updated : t)));
      setEditingId(null);
      setEditValue('');
    } catch (error) {
      console.error('Error renaming task:', error);
    }
  };

  // Load tasks on mount
  loadTasks();

  return (
    <div class="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div class="max-w-2xl mx-auto">
        <h1 class="text-4xl font-bold text-gray-800 mb-8 text-center">
          Gestor de Tareas
        </h1>

        <div class="bg-white rounded-lg shadow-lg p-6 mb-6">
          <div class="flex gap-2 mb-6">
            <input
              type="text"
              placeholder="Tarea"
              value={inputValue()}
              onInput={(e) => setInputValue(e.currentTarget.value)}
              onKeyDown={(e) => e.key === 'Enter' && addTask()}
              class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={addTask}
              class="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition font-semibold"
            >
              Agregar
            </button>
          </div>

          <select
            value={filter()}
            onChange={(e) => setFilter(e.currentTarget.value as FilterType)}
            class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-6"
          >
            <option value="all">Todas</option>
            <option value="pending">Pendientes</option>
            <option value="completed">Hechas</option>
          </select>

          <div class="space-y-3">
            <Show
              when={filteredTasks().length > 0}
              fallback={
                <p class="text-center text-gray-500 py-8">No hay tareas</p>
              }
            >
              <For each={filteredTasks()}>
                {(task) => (
                  <div class="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200 hover:border-gray-300 transition">
                    <Show
                      when={editingId() === task.id}
                      fallback={
                        <div class="flex items-center gap-3 flex-1">
                          <span
                            class={`text-lg ${
                              task.completed
                                ? 'text-gray-500 line-through'
                                : 'text-gray-800'
                            }`}
                          >
                            {task.title}
                          </span>
                          <Show when={task.completed}>
                            <span class="text-sm text-green-600 font-semibold">
                              (hecha)
                            </span>
                          </Show>
                        </div>
                      }
                    >
                      <input
                        type="text"
                        value={editValue()}
                        onInput={(e) => setEditValue(e.currentTarget.value)}
                        placeholder="Nuevo título"
                        class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    </Show>

                    <div class="flex gap-2 ml-4">
                      <Show when={editingId() === task.id}>
                        <button
                          onClick={() => saveRename(task.id)}
                          class="px-3 py-1 bg-green-600 text-white text-sm rounded hover:bg-green-700 transition font-semibold"
                        >
                          Guardar
                        </button>
                        <button
                          onClick={() => setEditingId(null)}
                          class="px-3 py-1 bg-gray-400 text-white text-sm rounded hover:bg-gray-500 transition font-semibold"
                        >
                          Cancelar
                        </button>
                      </Show>
                      <Show when={editingId() !== task.id}>
                        <Show when={!task.completed}>
                          <button
                            onClick={() => completeTask(task.id)}
                            class="px-3 py-1 bg-green-600 text-white text-sm rounded hover:bg-green-700 transition font-semibold"
                          >
                            Hecha
                          </button>
                        </Show>
                        <button
                          onClick={() => startRename(task.id, task.title)}
                          class="px-3 py-1 bg-blue-500 text-white text-sm rounded hover:bg-blue-600 transition font-semibold"
                        >
                          Renombrar
                        </button>
                      </Show>
                    </div>
                  </div>
                )}
              </For>
            </Show>
          </div>
        </div>
      </div>
    </div>
  );
}

