import React, { useState, useEffect } from 'react';

interface VoteData {
  dogs: number;
  cats: number;
}

interface VoteStats {
  dogs: {
    count: number;
    percentage: number;
  };
  cats: {
    count: number;
    percentage: number;
  };
}

export default function App() {
  const [stats, setStats] = useState<VoteStats | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchStats = async () => {
    try {
      const response = await fetch('/api/stats');
      const data: VoteStats = await response.json();
      setStats(data);
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  useEffect(() => {
    fetchStats();
    setLoading(false);
  }, []);

  const handleVote = async (animal: 'dogs' | 'cats') => {
    try {
      const response = await fetch(`/api/vote/${animal}`, { method: 'POST' });
      const data: VoteStats = await response.json();
      setStats(data);
    } catch (error) {
      console.error('Error voting:', error);
    }
  };

  const handleReset = async () => {
    try {
      const response = await fetch('/api/reset', { method: 'POST' });
      const data: VoteStats = await response.json();
      setStats(data);
    } catch (error) {
      console.error('Error resetting:', error);
    }
  };

  if (loading || !stats) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 flex items-center justify-center">
        <div className="text-gray-600 text-xl">Cargando encuesta...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-2xl p-8 max-w-md w-full">
        <h1 className="text-3xl font-bold text-center text-gray-800 mb-8">
          ¿Perros o Gatos?
        </h1>

        <div className="space-y-6 mb-8">
          {/* Dogs Section */}
          <div className="space-y-3">
            <div className="flex justify-between items-end">
              <h2 className="text-xl font-semibold text-gray-700">🐕 Perros</h2>
              <p className="text-2xl font-bold text-blue-600">
                {stats.dogs.percentage}%
              </p>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div
                className="bg-blue-500 h-3 rounded-full transition-all duration-300"
                style={{ width: `${stats.dogs.percentage}%` }}
              ></div>
            </div>
            <p className="text-sm text-gray-600">
              {stats.dogs.count} {stats.dogs.count === 1 ? 'voto' : 'votos'}
            </p>
            <button
              onClick={() => handleVote('dogs')}
              className="w-full bg-blue-500 hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200"
            >
              Votar Perros
            </button>
          </div>

          {/* Cats Section */}
          <div className="space-y-3">
            <div className="flex justify-between items-end">
              <h2 className="text-xl font-semibold text-gray-700">🐱 Gatos</h2>
              <p className="text-2xl font-bold text-purple-600">
                {stats.cats.percentage}%
              </p>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div
                className="bg-purple-500 h-3 rounded-full transition-all duration-300"
                style={{ width: `${stats.cats.percentage}%` }}
              ></div>
            </div>
            <p className="text-sm text-gray-600">
              {stats.cats.count} {stats.cats.count === 1 ? 'voto' : 'votos'}
            </p>
            <button
              onClick={() => handleVote('cats')}
              className="w-full bg-purple-500 hover:bg-purple-600 text-white font-bold py-3 px-4 rounded-lg transition-colors duration-200"
            >
              Votar Gatos
            </button>
          </div>
        </div>

        <button
          onClick={handleReset}
          className="w-full bg-gray-300 hover:bg-gray-400 text-gray-800 font-semibold py-2 px-4 rounded-lg transition-colors duration-200"
        >
          Reiniciar Encuesta
        </button>

        <p className="text-center text-gray-500 text-xs mt-4">
          Total de votos: {stats.dogs.count + stats.cats.count}
        </p>
      </div>
    </div>
  );
}

