import { createServer, IncomingMessage, ServerResponse } from 'node:http';

interface Votes {
  dogs: number;
  cats: number;
}

interface VoteStats {
  dogs: {
    count: number;
    percentage: number;
  };
  cats: {
    count: number;
    percentage: number;
  };
}

let votes: Votes = {
  dogs: 0,
  cats: 0,
};

function calculateStats(): VoteStats {
  const total = votes.dogs + votes.cats;

  return {
    dogs: {
      count: votes.dogs,
      percentage: total === 0 ? 0 : Math.round((votes.dogs / total) * 100),
    },
    cats: {
      count: votes.cats,
      percentage: total === 0 ? 0 : Math.round((votes.cats / total) * 100),
    },
  };
}

function sendJson(res: ServerResponse, statusCode: number, data: unknown) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

function handleRequest(req: IncomingMessage, res: ServerResponse) {
  const url = new URL(req.url || '/', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  // GET /api/stats
  if (pathname === '/api/stats' && req.method === 'GET') {
    const stats = calculateStats();
    sendJson(res, 200, stats);
    return;
  }

  // POST /api/vote/dogs
  if (pathname === '/api/vote/dogs' && req.method === 'POST') {
    votes.dogs++;
    const stats = calculateStats();
    sendJson(res, 200, stats);
