  const total = state.dogs + state.cats
  const dogsPercentage = total === 0 ? 0 : Math.round((state.dogs / total) * 100)
  const catsPercentage = total === 0 ? 0 : Math.round((state.cats / total) * 100)

  return {
    dogs: state.dogs,
    cats: state.cats,
    dogsPercentage,
    catsPercentage
  }
}

