import { createSignal, createMemo, Show, onMount } from 'solid-js';

export default function App() {
  const [dogs, setDogs] = createSignal(0);
  const [cats, setCats] = createSignal(0);
  const [loading, setLoading] = createSignal(false);

  const total = createMemo(() => dogs() + cats());

  const dogsPercentage = createMemo(() => {
    const t = total();
    return t === 0 ? 0 : Math.round((dogs() / t) * 100);
  });

  const catsPercentage = createMemo(() => {
    const t = total();
    return t === 0 ? 0 : Math.round((cats() / t) * 100);
  });

  const fetchResults = async () => {
    try {
      const res = await fetch('/api/results');
      const data = await res.json();
      setDogs(data.dogs);
      setCats(data.cats);
    } catch (err) {
      console.error('Error fetching results:', err);
    }
  };

  const vote = async (option: 'dogs' | 'cats') => {
    setLoading(true);
    try {
      const res = await fetch(`/api/vote/${option}`, { method: 'POST' });
      const data = await res.json();
      setDogs(data.dogs);
      setCats(data.cats);
    } catch (err) {
      console.error('Error voting:', err);
    } finally {
      setLoading(false);
    }
  };

  const reset = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/reset', { method: 'POST' });
      const data = await res.json();
      setDogs(data.dogs);
      setCats(data.cats);
    } catch (err) {
      console.error('Error resetting:', err);
    } finally {
      setLoading(false);
    }
  };

  onMount(() => {
    fetchResults();
  });

  return (
    <div class="flex items-center justify-center min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      <div class="bg-white rounded-lg shadow-2xl p-8 w-full max-w-md">
        <h1 class="text-4xl font-bold text-center text-gray-800 mb-8">
          Perros vs Gatos
        </h1>

        <div class="space-y-6 mb-8">
          {/* Perros */}
          <div class="bg-blue-50 rounded-lg p-6 border-2 border-blue-200">
            <div class="flex justify-between items-center mb-3">
              <h2 class="text-2xl font-bold text-blue-700">Perros:</h2>
              <span class="text-lg font-bold text-blue-600">{dogsPercentage()}% ({dogs()} {dogs() === 1 ? 'voto' : 'votos'})</span>
            </div>
            <button
              onClick={() => vote('dogs')}
              disabled={loading()}
              class="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold py-3 rounded-lg transition-colors"
            >
              Votar Perros
            </button>
          </div>

          {/* Gatos */}
          <div class="bg-orange-50 rounded-lg p-6 border-2 border-orange-200">
            <div class="flex justify-between items-center mb-3">
              <h2 class="text-2xl font-bold text-orange-700">Gatos:</h2>
              <span class="text-lg font-bold text-orange-600">{catsPercentage()}% ({cats()} {cats() === 1 ? 'voto' : 'votos'})</span>
            </div>
            <button
              onClick={() => vote('cats')}
              disabled={loading()}
              class="w-full bg-orange-600 hover:bg-orange-700 disabled:bg-orange-400 text-white font-bold py-3 rounded-lg transition-colors"
            >
              Votar Gatos
            </button>
          </div>
        </div>

        {/* Reset Button */}
        <button
          onClick={reset}
          disabled={loading()}
          class="w-full bg-red-600 hover:bg-red-700 disabled:bg-red-400 text-white font-bold py-3 rounded-lg transition-colors"
        >
          Reiniciar
        </button>

        {/* Total votes */}
        <p class="text-center text-gray-500 text-sm mt-6">
          Total: {total()} {total() === 1 ? 'voto' : 'votos'}
        </p>
      </div>
    </div>
  );
}

