import React, { useState, useEffect } from 'react';

type Product = {
  id: number;
  name: string;
};

type PaginatedResponse = {
  products: Product[];
  total: number;
  page: number;
};

export default function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchProducts = async (currentPage: number, searchQuery: string) => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        search: searchQuery,
      });
      const response = await fetch(`/api/products?${params}`);
      const data: PaginatedResponse = await response.json();
      setProducts(data.products);
      setTotal(data.total);
      setPage(currentPage);
    } catch (error) {
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts(1, search);
  }, [search]);

  const handleLoadExamples = async () => {
    try {
      const response = await fetch('/api/init', { method: 'POST' });
      const data = await response.json();
      if (data.success) {
        fetchProducts(1, search);
      }
    } catch (error) {
      console.error('Error loading examples:', error);
    }
  };

  const handlePrevious = () => {
    if (page > 1) {
      fetchProducts(page - 1, search);
    }
  };

  const handleNext = () => {
    if (page * 5 < total) {
      fetchProducts(page + 1, search);
    }
  };

  const handleSearch = (value: string) => {
    setSearch(value);
  };

  const hasPrevious = page > 1;
  const hasNext = page * 5 < total;

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8">Catálogo de Productos</h1>

        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <button
            onClick={handleLoadExamples}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded mb-6 transition-colors"
          >
            Cargar ejemplos
          </button>

          <input
            type="text"
            placeholder="Buscar"
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 mb-6"
          />

          <div className="mb-4">
            <p className="text-gray-700 font-semibold">Total: {total}</p>
          </div>

          {loading ? (
            <p className="text-center text-gray-600">Cargando...</p>
          ) : products.length > 0 ? (
            <div className="space-y-3 mb-6">
              {products.map((product) => (
                <div
                  key={product.id}
                  className="p-4 bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-colors"
                >
                  <p className="text-gray-800 font-medium">{product.name}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-center text-gray-600 mb-6">No se encontraron productos</p>
          )}

          <div className="flex gap-4 justify-center">
            <button
              onClick={handlePrevious}
              disabled={!hasPrevious}
              className={`py-2 px-6 rounded font-semibold transition-colors ${
                hasPrevious
                  ? 'bg-gray-500 hover:bg-gray-600 text-white cursor-pointer'
                  : 'bg-gray-300 text-gray-500 cursor-not-allowed'
              }`}
            >
              Anterior
            </button>
            <span className="py-2 px-4 text-gray-700 font-semibold">
              Página {page}
            </span>
            <button
              onClick={handleNext}
              disabled={!hasNext}
              className={`py-2 px-6 rounded font-semibold transition-colors ${
                hasNext
                  ? 'bg-gray-500 hover:bg-gray-600 text-white cursor-pointer'
                  : 'bg-gray-300 text-gray-500 cursor-not-allowed'
              }`}
            >
              Siguiente
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

