import http from 'node:http';
import { URL } from 'node:url';

type Product = {
  id: number;
  name: string;
};

let products: Product[] = [];
let nextId = 1;

const port = process.env.PORT || 3000;

const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  // POST /api/init - Initialize with 12 products
  if (req.method === 'POST' && pathname === '/api/init') {
    if (products.length === 0) {
      for (let i = 1; i <= 12; i++) {
        products.push({ id: nextId++, name: `Producto ${i}` });
      }
    }
    res.writeHead(200);
    res.end(JSON.stringify({ success: true }));
    return;
  }

  // GET /api/products - Get paginated products with optional search
  if (req.method === 'GET' && pathname === '/api/products') {
    const pageStr = url.searchParams.get('page') || '1';
    const search = url.searchParams.get('search') || '';

    const page = Math.max(1, parseInt(pageStr, 10));
    const pageSize = 5;

    let filtered = products;
    if (search.trim()) {
      const lowerSearch = search.toLowerCase();
      filtered = products.filter((p) =>
        p.name.toLowerCase().includes(lowerSearch)
      );
    }

    // Sort by product number (extracted from name)
    filtered.sort((a, b) => {
      const numA = parseInt(a.name.split(' ')[1], 10) || 0;
      const numB = parseInt(b.name.split(' ')[1], 10) || 0;
      return numA - numB;
    });

    const total = filtered.length;
    const start = (page - 1) * pageSize;
    const end = start + pageSize;
    const paginated = filtered.slice(start, end);

    res.writeHead(200);
    res.end(
      JSON.stringify({
        products: paginated,
        total,
        page,
      })
    );
    return;
  }

  // 404
  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

