import React, { useState, useEffect } from 'react';

export default function App() {
  const [products, setProducts] = useState<Array<{ id: number; name: string }>>([]);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);

  const fetchProducts = async (searchQuery: string, pageNum: number) => {
    setLoading(true);
    try {
      const response = await fetch(
        `/api/products?search=${encodeURIComponent(searchQuery)}&page=${pageNum}`
      );
      const data = await response.json();
      setProducts(data.products);
      setTotal(data.total);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts(search, page);
  }, [search, page]);

  const handleLoadExamples = async () => {
    setLoading(true);
    try {
      await fetch('/api/products/init', { method: 'POST' });
      setSearch('');
      setPage(1);
      await fetchProducts('', 1);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (value: string) => {
    setSearch(value);
    setPage(1);
  };

  const handlePrevious = () => {
    if (page > 1) {
      setPage(page - 1);
    }
  };

  const handleNext = () => {
    const maxPage = Math.ceil(total / 5);
    if (page < maxPage) {
      setPage(page + 1);
    }
  };

  const maxPage = Math.ceil(total / 5) || 1;

  return (
    <div className="min-h-screen bg-gray-100 py-8 px-4">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-8 text-center">
          Catálogo de Productos
        </h1>

        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <button
            onClick={handleLoadExamples}
            disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold py-2 px-4 rounded transition duration-200"
          >
            {loading ? 'Cargando...' : 'Cargar ejemplos'}
          </button>
        </div>

        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <input
            type="text"
            placeholder="Buscar"
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            disabled={loading}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100"
          />
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="mb-4">
            <p className="text-gray-700 font-semibold">Total: {total}</p>
          </div>

          {products.length > 0 ? (
            <div className="space-y-3 mb-6">
              {products.map((product) => (
                <div
                  key={product.id}
                  className="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition"
                >
                  <p className="text-gray-900 font-medium">{product.name}</p>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <p className="text-gray-500">
                {total === 0 ? 'No hay productos' : 'Cargando...'}
              </p>
            </div>
          )}

          <div className="flex gap-4 justify-between items-center">
            <button
              onClick={handlePrevious}
              disabled={page === 1 || loading}
              className="flex-1 bg-gray-300 hover:bg-gray-400 disabled:bg-gray-200 disabled:cursor-not-allowed text-gray-900 font-bold py-2 px-4 rounded transition duration-200"
            >
              Anterior
            </button>

            <span className="text-gray-700 font-semibold">
              Página {page} de {maxPage}
            </span>

            <button
              onClick={handleNext}
              disabled={page >= maxPage || loading}
              className="flex-1 bg-gray-300 hover:bg-gray-400 disabled:bg-gray-200 disabled:cursor-not-allowed text-gray-900 font-bold py-2 px-4 rounded transition duration-200"
            >
              Siguiente
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

