import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { URL } from 'node:url';

interface Product {
  id: number;
  name: string;
}

let products: Product[] = [];
let nextId = 1;

function initializeProducts(): void {
  if (products.length === 0) {
    for (let i = 1; i <= 12; i++) {
      products.push({ id: nextId++, name: `Producto ${i}` });
    }
  }
}

function getProducts(search: string, page: number): { products: Product[]; total: number } {
  let filtered = products;

  if (search.trim()) {
    filtered = products.filter((p) =>
      p.name.toLowerCase().includes(search.toLowerCase())
    );
  }

  const itemsPerPage = 5;
  const total = filtered.length;
  const start = (page - 1) * itemsPerPage;
  const end = start + itemsPerPage;

  return {
    products: filtered.slice(start, end),
    total,
  };
}

function parseQuery(url: string): Record<string, string> {
  const parsed = new URL(url, 'http://localhost');
  const query: Record<string, string> = {};

  parsed.searchParams.forEach((value, key) => {
    query[key] = value;
  });

  return query;
}

function sendJson(res: ServerResponse, status: number, data: unknown): void {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

const server = createServer((req: IncomingMessage, res: ServerResponse) => {
  const url = req.url || '';

  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (url.startsWith('/api/products/init') && req.method === 'POST') {
    initializeProducts();
    sendJson(res, 200, { success: true });
    return;
  }

  if (url.startsWith('/api/products') && req.method === 'GET') {
    const query = parseQuery(url);
    const search = query.search || '';
    const page = parseInt(query.page || '1', 10);

    const result = getProducts(search, page);
    sendJson(res, 200, result);
    return;
  }

  sendJson(res, 404, { error: 'Not found' });
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});

