const parseUrl = (urlString: string) => {
  try {
    return new URL(urlString, 'http://localhost')
  } catch {
    return null
  }
}

const getProducts = (
  searchQuery: string = '',
  page: number = 1,
  limit: number = 5
) => {
  let filtered = products
  if (searchQuery.trim()) {
    const query = searchQuery.toLowerCase()
    filtered = products.filter((p) => p.name.toLowerCase().includes(query))
  }

  const sorted = [...filtered].sort((a, b) => a.id - b.id)
  const total = sorted.length
  const start = (page - 1) * limit
  const end = start + limit
  const paged = sorted.slice(start, end)

  return {
    products: paged,
    total,
  }
}

const sendJson = (res: ServerResponse, statusCode: number, data: unknown) => {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(data))
}

const server = createServer(
  (req: IncomingMessage, res: ServerResponse) => {
    res.setHeader('Access-Control-Allow-Origin', '*')
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type')

    if (req.method === 'OPTIONS') {
      res.writeHead(200)
      res.end()
      return
    }

    const parsedUrl = parseUrl(req.url || '')
    if (!parsedUrl) {
      sendJson(res, 400, { error: 'Invalid URL' })
      return
    }

    const pathname = parsedUrl.pathname
    const searchParams = parsedUrl.searchParams

    // GET /api/products
    if (pathname === '/api/products' && req.method === 'GET') {
      const search = searchParams.get('search') || ''
      const page = parseInt(searchParams.get('page') || '1', 10)
      const limit = parseInt(searchParams.get('limit') || '5', 10)

      const result = getProducts(search, page, limit)
      sendJson(res, 200, result)
      return
    }

    // POST /api/products/load-examples
    if (pathname === '/api/products/load-examples' && req.method === 'POST') {
      if (products.length === 0) {
        products = Array.from({ length: 12 }, (_, i) => ({
          id: i + 1,
          name: `Producto ${i + 1}`,
        }))
      }
      sendJson(res, 200, { success: true, count: products.length })
      return
    }

    sendJson(res, 404, { error: 'Not Found' })
  }
)

const port = parseInt(process.env.PORT || '3000', 10)
server.listen(port, () => {
  console.log(`Server listening on port ${port}`)
})

