    setSearch(value);
    setPage(1);
    fetchProducts(value, 1);
  };

  const handleLoadExamples = async () => {
    try {
      await fetch("/api/load-examples", { method: "POST" });
      fetchProducts(search(), 1);
    } catch (error) {
      console.error("Error loading examples:", error);
    }
  };

  const handlePrevious = () => {
    if (page() > 1) {
      const newPage = page() - 1;
      setPage(newPage);
      fetchProducts(search(), newPage);
    }
  };

  const handleNext = () => {
    if (page() < totalPages()) {
      const newPage = page() + 1;
      setPage(newPage);
      fetchProducts(search(), newPage);
    }
  };

  createEffect(() => {
    fetchProducts(search(), 1);
  });

  return (
    <div class="min-h-screen bg-gray-50 py-8 px-4">
      <div class="max-w-2xl mx-auto">
        <div class="bg-white rounded-lg shadow-lg p-6">
          <h1 class="text-3xl font-bold text-gray-800 mb-6">Catálogo de Productos</h1>

          <div class="flex gap-4 mb-6">
            <input
              type="text"
              placeholder="Buscar"
              value={search()}
              onInput={(e) => handleSearch(e.currentTarget.value)}
              class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleLoadExamples}
              class="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 font-medium transition-colors"
            >
              Cargar ejemplos
            </button>
          </div>

          <Show when={!loading()} fallback={<div class="text-center text-gray-500">Cargando...</div>}>
            <div class="mb-4">
              <p class="text-gray-600 font-medium">Total: {total()}</p>
            </div>

            <div class="space-y-2 mb-6">
              <Show
                when={products().length > 0}
                fallback={<p class="text-gray-400 text-center py-8">No hay productos</p>}
              >
                <For each={products()}>
                  {(product) => (
                    <div class="p-4 bg-gray-50 rounded-lg border border-gray-200 hover:bg-gray-100 transition-colors">
                      <p class="text-gray-800 font-medium">{product.name}</p>
                    </div>
                  )}
                </For>
              </Show>
            </div>

            <div class="flex gap-4 justify-center">
              <button
                onClick={handlePrevious}
                disabled={page() === 1}
                class="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 disabled:opacity-50 disabled:cursor-not-allowed font-medium transition-colors"
              >
                Anterior
              </button>
              <button
                onClick={handleNext}
                disabled={page() === totalPages() || totalPages() === 0}
                class="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 disabled:opacity-50 disabled:cursor-not-allowed font-medium transition-colors"
              >
                Siguiente
              </button>
            </div>
          </Show>
        </div>
      </div>
    </div>
  );
}

