import * as http from "node:http";

interface Product {
  id: number;
  name: string;
}

let products: Product[] = [];
let nextId = 1;

function loadExamples() {
  if (products.length === 0) {
    for (let i = 1; i <= 12; i++) {
      products.push({ id: nextId++, name: `Producto ${i}` });
    }
  }
}

function getProductsPage(
  search: string,
  page: number
): { products: Product[]; total: number; totalPages: number } {
  const pageSize = 5;
  let filtered = products;

  if (search) {
    filtered = products.filter((p) =>
      p.name.toLowerCase().includes(search.toLowerCase())
    );
  }

  filtered.sort((a, b) => {
    const numA = parseInt(a.name.match(/\d+/)?.[0] || "0");
    const numB = parseInt(b.name.match(/\d+/)?.[0] || "0");
    return numA - numB;
  });

  const total = filtered.length;
  const totalPages = Math.ceil(total / pageSize);
  const startIdx = (page - 1) * pageSize;
  const endIdx = startIdx + pageSize;
  const paginatedProducts = filtered.slice(startIdx, endIdx);

  return { products: paginatedProducts, total, totalPages };
}

const server = http.createServer((req, res) => {
  res.setHeader("Content-Type", "application/json");
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");

  if (req.method === "OPTIONS") {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || "", `http://${req.headers.host}`);

  if (url.pathname === "/api/load-examples" && req.method === "POST") {
    loadExamples();
    res.writeHead(200);
    res.end(JSON.stringify({ success: true }));
    return;
  }

  if (url.pathname === "/api/products" && req.method === "GET") {
    const search = url.searchParams.get("search") || "";
    const page = parseInt(url.searchParams.get("page") || "1");

    const result = getProductsPage(search, page);
    res.writeHead(200);
    res.end(
      JSON.stringify({
        products: result.products,
        total: result.total,
        page,
        totalPages: result.totalPages,
      })
    );
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: "Not found" }));
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

