import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { createHash, randomBytes } from 'node:crypto';

interface User {
  id: string;
  email: string;
  passwordHash: string;
  salt: string;
}

interface Note {
  id: string;
  userId: string;
  content: string;
}

interface Token {
  userId: string;
  email: string;
}

const users: Map<string, User> = new Map();
const notes: Map<string, Note> = new Map();
const tokens: Map<string, Token> = new Map();

function hashPassword(password: string, salt: string): string {
  return createHash('sha256').update(password + salt).digest('hex');
}

function verifyPassword(password: string, salt: string, hash: string): boolean {
  return hashPassword(password, salt) === hash;
}

function generateToken(): string {
  return randomBytes(32).toString('hex');
}

function authenticateToken(req: IncomingMessage): Token | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }
  const token = authHeader.slice(7);
  return tokens.get(token) || null;
}

function parseJson(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
    });
    req.on('end', () => {
      try {
        resolve(JSON.parse(body || '{}'));
      } catch {
        reject(new Error('Invalid JSON'));
      }
    });
  });
}

function sendJson(res: ServerResponse, statusCode: number, data: any): void {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

async function handleRegister(req: IncomingMessage, res: ServerResponse): Promise<void> {
  try {
    const { email, password } = await parseJson(req);

    if (!email || !password) {
      sendJson(res, 400, { message: 'Email and password required' });
      return;
    }

    const existingUser = Array.from(users.values()).find((u) => u.email === email);
    if (existingUser) {
      sendJson(res, 400, { message: 'User already exists' });
      return;
    }

    const userId = randomUUID();
    const salt = randomBytes(16).toString('hex');
    const passwordHash = hashPassword(password, salt);

    users.set(userId, {
      id: userId,
      email,
      passwordHash,
      salt,
    });

    const token = generateToken();
    tokens.set(token, { userId, email });

    sendJson(res, 201, { token, email });
  } catch (err) {
    sendJson(res, 400, { message: 'Invalid request' });
  }
}

async function handleLogin(req: IncomingMessage, res: ServerResponse): Promise<void> {
  try {
    const { email, password } = await parseJson(req);

    if (!email || !password) {
      sendJson(res, 400, { message: 'Email and password required' });
      return;
    }

    const user = Array.from(users.values()).find((u) => u.email === email);
    if (!user || !verifyPassword(password, user.salt, user.passwordHash)) {
      sendJson(res, 401, { message: 'Invalid credentials' });
      return;
    }

    const token = generateToken();
    tokens.set(token, { userId: user.id, email: user.email });

    sendJson(res, 200, { token, email });
  } catch (err) {
    sendJson(res, 400, { message: 'Invalid request' });
  }
}

function handleGetNotes(req: IncomingMessage, res: ServerResponse): void {
  const auth = authenticateToken(req);
  if (!auth) {
    sendJson(res, 401, { message: 'Unauthorized' });
    return;
  }

  const userNotes = Array.from(notes.values())
    .filter((n) => n.userId === auth.userId)
    .map(({ id, content }) => ({ id, content }));

  sendJson(res, 200, userNotes);
}

async function handleCreateNote(req: IncomingMessage, res: ServerResponse): Promise<void> {
  try {
    const auth = authenticateToken(req);
    if (!auth) {
      sendJson(res, 401, { message: 'Unauthorized' });
      return;
    }

    const { content } = await parseJson(req);
    if (!content || typeof content !== 'string' || !content.trim()) {
      sendJson(res, 400, { message: 'Content required' });
      return;
    }

    const noteId = randomUUID();
    const newNote: Note = {
      id: noteId,
      userId: auth.userId,
      content: content.trim(),
    };

    notes.set(noteId, newNote);

    sendJson(res, 201, { id: noteId, content: newNote.content });
  } catch (err) {
    sendJson(res, 400, { message: 'Invalid request' });
  }
}

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/api/auth/register' && req.method === 'POST') {
    await handleRegister(req, res);
  } else if (pathname === '/api/auth/login' && req.method === 'POST') {
    await handleLogin(req, res);
  } else if (pathname === '/api/notes' && req.method === 'GET') {
    handleGetNotes(req, res);
  } else if (pathname === '/api/notes' && req.method === 'POST') {
    await handleCreateNote(req, res);
  } else {
    sendJson(res, 404, { message: 'Not found' });
  }
});

const port = parseInt(process.env.PORT || '3000', 10);
server.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

