import React, { useState, useEffect } from 'react';

interface Note {
  id: string;
  content: string;
}

interface User {
  email: string;
  passwordHash: string;
}

interface ApiResponse {
  success: boolean;
  message?: string;
  data?: any;
  error?: string;
}

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteInput, setNoteInput] = useState('');
  const [loading, setLoading] = useState(false);

  // Verificar si hay sesión activa al cargar
  useEffect(() => {
    const checkSession = async () => {
      try {
        const response = await fetch('/api/auth/session');
        const data: ApiResponse = await response.json();
        if (data.success && data.data?.email) {
          setEmail(data.data.email);
          setIsLoggedIn(true);
          await loadNotes();
        }
      } catch (error) {
        console.error('Error checking session:', error);
      }
    };
    checkSession();
  }, []);

  const loadNotes = async () => {
    try {
      const response = await fetch('/api/notes');
      const data: ApiResponse = await response.json();
      if (data.success && Array.isArray(data.data)) {
        setNotes(data.data);
      }
    } catch (error) {
      console.error('Error loading notes:', error);
    }
  };

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setLoginError('');
    try {
      const response = await fetch('/api/auth/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data: ApiResponse = await response.json();
      if (data.success) {
        setIsLoggedIn(true);
        setPassword('');
        await loadNotes();
      } else {
        setLoginError(data.message || 'Error creating account');
      }
    } catch (error) {
      setLoginError('Error creating account');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setLoginError('');
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data: ApiResponse = await response.json();
      if (data.success) {
        setIsLoggedIn(true);
        setPassword('');
        await loadNotes();
      } else {
        setLoginError('Datos incorrectos');
      }
    } catch (error) {
      setLoginError('Error logging in');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    try {
      await fetch('/api/auth/logout', { method: 'POST' });
    } catch (error) {
      console.error('Error logging out:', error);
    }
    setIsLoggedIn(false);
    setEmail('');
    setPassword('');
    setNotes([]);
    setNoteInput('');
  };

  const handleAddNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!noteInput.trim()) return;

    setLoading(true);
    try {
      const response = await fetch('/api/notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: noteInput }),
      });
      const data: ApiResponse = await response.json();
      if (data.success) {
        setNoteInput('');
        await loadNotes();
      }
    } catch (error) {
      console.error('Error adding note:', error);
    } finally {
      setLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center p-4">
        <div className="bg-white rounded-lg shadow-xl p-8 w-full max-w-md">
          <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">
            Notas Privadas
          </h1>

          <form onSubmit={handleLogin} className="space-y-4 mb-6">
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                setLoginError('');
              }}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
            <input
              type="password"
              placeholder="Contraseña"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setLoginError('');
              }}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
            {loginError && (
              <p className="text-red-500 text-sm font-medium">{loginError}</p>
            )}
            <div className="flex gap-3">
              <button
                type="submit"
                disabled={loading}
                className="flex-1 bg-blue-500 text-white py-2 rounded-lg font-semibold hover:bg-blue-600 disabled:opacity-50 transition"
              >
                Entrar
              </button>
              <button
                type="button"
                onClick={handleSignUp}
                disabled={loading}
                className="flex-1 bg-purple-500 text-white py-2 rounded-lg font-semibold hover:bg-purple-600 disabled:opacity-50 transition"
              >
                Crear cuenta
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-500 to-purple-600 p-4">
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-lg shadow-xl p-8 mb-6">
          <div className="flex justify-between items-center mb-6">
            <h1 className="text-3xl font-bold text-gray-800">
              Hola, {email}
            </h1>
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-6 py-2 rounded-lg font-semibold hover:bg-red-600 transition"
            >
              Salir
            </button>
          </div>

          <form onSubmit={handleAddNote} className="flex gap-2">
            <input
              type="text"
              placeholder="Nota"
              value={noteInput}
              onChange={(e) => setNoteInput(e.target.value)}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              type="submit"
              disabled={loading}
              className="bg-blue-500 text-white px-6 py-2 rounded-lg font-semibold hover:bg-blue-600 disabled:opacity-50 transition"
            >
              Agregar
            </button>
          </form>
        </div>

        <div className="space-y-3">
          {notes.length === 0 ? (
            <div className="bg-white rounded-lg shadow-xl p-8 text-center text-gray-500">
              No tienes notas aún. ¡Crea una!
            </div>
          ) : (
            notes.map((note) => (
              <div
                key={note.id}
                className="bg-white rounded-lg shadow-xl p-6 hover:shadow-2xl transition"
              >
                <p className="text-gray-700">{note.content}</p>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

