import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { randomBytes, scryptSync } from 'node:crypto';

interface User {
  email: string;
  passwordHash: string;
  salt: string;
}

interface Note {
  id: string;
  email: string;
  content: string;
}

interface Session {
  email: string;
  sessionId: string;
}

const users: Map<string, User> = new Map();
const notes: Note[] = [];
const sessions: Map<string, Session> = new Map();

const hashPassword = (password: string, salt: string): string => {
  return scryptSync(password, salt, 64).toString('hex');
};

const verifyPassword = (password: string, hash: string, salt: string): boolean => {
  return hashPassword(password, salt) === hash;
};

const generateSessionId = (): string => {
  return randomBytes(32).toString('hex');
};

const getSessionEmail = (cookies: string | undefined, sessionId: string | undefined): string | null => {
  if (!sessionId) return null;
  const session = sessions.get(sessionId);
  return session?.email || null;
};

const parseUrl = (pathname: string): { endpoint: string; method: string } => {
  return {
    endpoint: pathname.replace(/^\/api/, ''),
    method: 'GET',
  };
};

const parseJson = (body: string): any => {
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
};

const sendJson = (res: ServerResponse, statusCode: number, data: any): void => {
  res.writeHead(statusCode, {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  });
  res.end(JSON.stringify(data));
};

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  const pathname = req.url?.split('?')[0] || '';

  if (req.method === 'OPTIONS') {
    res.writeHead(200, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    });
    res.end();
    return;
  }

  if (!pathname.startsWith('/api/')) {
    sendJson(res, 404, { success: false, error: 'Not found' });
    return;
  }

  const endpoint = pathname.replace(/^\/api/, '');
  const method = req.method || 'GET';

  let body = '';
  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', async () => {
    try {
      if (endpoint === '/auth/signup' && method === 'POST') {
        const data = parseJson(body);
        if (!data?.email || !data?.password) {
          sendJson(res, 400, { success: false, message: 'Email and password required' });
          return;
        }

        if (users.has(data.email)) {
          sendJson(res, 400, { success: false, message: 'Email already exists' });
          return;
        }

        const salt = randomBytes(16).toString('hex');
        const passwordHash = hashPassword(data.password, salt);

        users.set(data.email, { email: data.email, passwordHash, salt });

        const sessionId = generateSessionId();
        sessions.set(sessionId, { email: data.email, sessionId });

        res.writeHead(200, {
          'Content-Type': 'application/json',
          'Set-Cookie': `sessionId=${sessionId}; Path=/; HttpOnly; Max-Age=604800`,
          'Access-Control-Allow-Origin': '*',
        });
        res.end(JSON.stringify({ success: true, data: { email: data.email } }));
        return;
      }

      if (endpoint === '/auth/login' && method === 'POST') {
        const data = parseJson(body);
        if (!data?.email || !data?.password) {
          sendJson(res, 400, { success: false, message: 'Email and password required' });
          return;
        }

        const user = users.get(data.email);
        if (!user || !verifyPassword(data.password, user.passwordHash, user.salt)) {
          sendJson(res, 401, { success: false, message: 'Invalid credentials' });
          return;
        }

        const sessionId = generateSessionId();
        sessions.set(sessionId, { email: data.email, sessionId });

        res.writeHead(200, {
          'Content-Type': 'application/json',
          'Set-Cookie': `sessionId=${sessionId}; Path=/; HttpOnly; Max-Age=604800`,
          'Access-Control-Allow-Origin': '*',
        });
        res.end(JSON.stringify({ success: true, data: { email: data.email } }));
        return;
      }

      if (endpoint === '/auth/logout' && method === 'POST') {
        const cookieHeader = req.headers.cookie || '';
        const sessionIdMatch = cookieHeader.match(/sessionId=([^;]+)/);
        if (sessionIdMatch) {
          sessions.delete(sessionIdMatch[1]);
        }

        res.writeHead(200, {
          'Content-Type': 'application/json',
          'Set-Cookie': 'sessionId=; Path=/; HttpOnly; Max-Age=0',
          'Access-Control-Allow-Origin': '*',
        });
        res.end(JSON.stringify({ success: true }));
        return;
      }

      if (endpoint === '/auth/session' && method === 'GET') {
        const cookieHeader = req.headers.cookie || '';
        const sessionIdMatch = cookieHeader.match(/sessionId=([^;]+)/);
        const sessionId = sessionIdMatch?.[1];

        if (!sessionId) {
          sendJson(res, 401, { success: false, error: 'No session' });
          return;
        }

        const session = sessions.get(sessionId);
        if (!session) {
          sendJson(res, 401, { success: false, error: 'Invalid session' });
          return;
        }

        sendJson(res, 200, { success: true, data: { email: session.email } });
        return;
      }

      if (endpoint === '/notes' && method === 'GET') {
        const cookieHeader = req.headers.cookie || '';
        const sessionIdMatch = cookieHeader.match(/sessionId=([^;]+)/);
        const sessionId = sessionIdMatch?.[1];

        const session = sessions.get(sessionId || '');
        if (!session) {
          sendJson(res, 401, { success: false, error: 'Unauthorized' });
          return;
        }

        const userNotes = notes.filter((n) => n.email === session.email);
        sendJson(res, 200, { success: true, data: userNotes });
        return;
      }

      if (endpoint === '/notes' && method === 'POST') {
        const cookieHeader = req.headers.cookie || '';
        const sessionIdMatch = cookieHeader.match(/sessionId=([^;]+)/);
        const sessionId = sessionIdMatch?.[1];

        const session = sessions.get(sessionId || '');
        if (!session) {
          sendJson(res, 401, { success: false, error: 'Unauthorized' });
          return;
        }

        const data = parseJson(body);
        if (!data?.content) {
          sendJson(res, 400, { success: false, message: 'Content required' });
          return;
        }

        const note: Note = {
          id: randomBytes(8).toString('hex'),
          email: session.email,
          content: data.content,
        };

        notes.push(note);
        sendJson(res, 201, { success: true, data: note });
        return;
      }

      sendJson(res, 404, { success: false, error: 'Endpoint not found' });
    } catch (error) {
      console.error('Error:', error);
