import { createServer, IncomingMessage, ServerResponse } from 'node:http';
import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';

interface User {
  email: string;
  passwordHash: string;
  salt: string;
}

interface Note {
  id: string;
  email: string;
  content: string;
  createdAt: string;
}

interface Session {
  email: string;
  expiresAt: number;
}

const users: Map<string, User> = new Map();
const notes: Note[] = [];
const sessions: Map<string, Session> = new Map();

const hashPassword = (password: string, salt?: string): { hash: string; salt: string } => {
  const s = salt || randomBytes(16).toString('hex');
  const hash = scryptSync(password, s, 64).toString('hex');
  return { hash, salt: s };
};

const verifyPassword = (password: string, hash: string, salt: string): boolean => {
  const { hash: computedHash } = hashPassword(password, salt);
  try {
    return timingSafeEqual(Buffer.from(hash), Buffer.from(computedHash));
  } catch {
    return false;
  }
};

const generateSessionId = (): string => randomBytes(32).toString('hex');

const parseUrl = (url: string): { path: string; search: string } => {
  const [path, search] = url.split('?');
  return { path, search: search || '' };
};

const getSessionEmail = (req: IncomingMessage): string | null => {
  const cookies = req.headers.cookie?.split(';') || [];
  for (const cookie of cookies) {
    const [name, value] = cookie.trim().split('=');
    if (name === 'sessionId') {
      const session = sessions.get(value);
      if (session && session.expiresAt > Date.now()) {
        return session.email;
      }
      sessions.delete(value);
      return null;
    }
  }
  return null;
};

const setSessionCookie = (res: ServerResponse, sessionId: string): void => {
  res.setHeader('Set-Cookie', `sessionId=${sessionId}; Path=/; HttpOnly; Max-Age=86400`);
};

const clearSessionCookie = (res: ServerResponse): void => {
  res.setHeader('Set-Cookie', 'sessionId=; Path=/; HttpOnly; Max-Age=0');
};

const handleAuth = async (req: IncomingMessage, res: ServerResponse, action: string): Promise<void> => {
  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const { email, password } = JSON.parse(body);

      if (!email || !password) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ message: 'Email y contraseña requeridos' }));
        return;
      }

      if (action === 'signup') {
        if (users.has(email)) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ message: 'El email ya está registrado' }));
          return;
        }

        const { hash, salt } = hashPassword(password);
        users.set(email, { email, passwordHash: hash, salt });

        const sessionId = generateSessionId();
        sessions.set(sessionId, { email, expiresAt: Date.now() + 86400000 });
        setSessionCookie(res, sessionId);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ email }));
      } else if (action === 'signin') {
        const user = users.get(email);

        if (!user || !verifyPassword(password, user.passwordHash, user.salt)) {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ message: 'Datos incorrectos' }));
          return;
        }

        const sessionId = generateSessionId();
        sessions.set(sessionId, { email, expiresAt: Date.now() + 86400000 });
        setSessionCookie(res, sessionId);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ email }));
      }
    } catch (error) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ message: 'Error al procesar la solicitud' }));
    }
  });
};

const handleMe = (req: IncomingMessage, res: ServerResponse): void => {
  const email = getSessionEmail(req);

  if (!email) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'No autenticado' }));
    return;
  }

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ email }));
};

const handleLogout = (req: IncomingMessage, res: ServerResponse): void => {
  clearSessionCookie(res);
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ message: 'Sesión cerrada' }));
};

const handleGetNotes = (req: IncomingMessage, res: ServerResponse): void => {
  const email = getSessionEmail(req);

  if (!email) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'No autenticado' }));
    return;
  }

  const userNotes = notes
    .filter((note) => note.email === email)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(userNotes));
};

const handleAddNote = async (req: IncomingMessage, res: ServerResponse): Promise<void> => {
  const email = getSessionEmail(req);

  if (!email) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'No autenticado' }));
    return;
  }

  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const { content } = JSON.parse(body);

      if (!content || typeof content !== 'string' || !content.trim()) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ message: 'Contenido de nota requerido' }));
        return;
      }

      const note: Note = {
        id: randomBytes(16).toString('hex'),
        email,
        content: content.trim(),
        createdAt: new Date().toISOString()
      };

      notes.push(note);

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(note));
    } catch (error) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ message: 'Error al procesar la solicitud' }));
    }
  });
};

const server = createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  const { path } = parseUrl(req.url || '');

  if (path === '/api/auth/signup' && req.method === 'POST') {
    await handleAuth(req, res, 'signup');
  } else if (path === '/api/auth/signin' && req.method === 'POST') {
    await handleAuth(req, res, 'signin');
  } else if (path === '/api/auth/me' && req.method === 'GET') {
    handleMe(req, res);
  } else if (path === '/api/auth/logout' && req.method === 'POST') {
    handleLogout(req, res);
  } else if (path === '/api/notes' && req.method === 'GET') {
    handleGetNotes(req, res);
  } else if (path === '/api/notes' && req.method === 'POST') {
    await handleAddNote(req, res);
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'No encontrado' }));
  }
});

