					.filter((n) => n.userId === session.userId)
					.map((n) => ({ id: n.id, text: n.text }));

				res.writeHead(200);
				res.end(
					JSON.stringify({
						user: { email: session.email },
						notes: userNotes
					})
				);
				return;
			}

			if (req.url === '/api/register' && req.method === 'POST') {
				const body = await parseJsonBody(req);
				const { email, password } = body as Record<string, unknown>;

				if (!email || !password) {
					res.writeHead(400);
					res.end(JSON.stringify({ message: 'Email and password required' }));
					return;
				}

				if (users.has(email as string)) {
					res.writeHead(400);
					res.end(JSON.stringify({ message: 'Email already exists' }));
					return;
				}

				const passwordHash = hashPassword(password as string);
				users.set(email as string, { email: email as string, passwordHash });

				const sessionId = generateSessionId();
				sessions.set(sessionId, { userId: email as string, email: email as string });

				res.setHeader('Set-Cookie', `sessionId=${sessionId}; Path=/; HttpOnly`);
				res.writeHead(200);
				res.end(JSON.stringify({ user: { email }, notes: [] }));
				return;
			}

			if (req.url === '/api/login' && req.method === 'POST') {
				const body = await parseJsonBody(req);
				const { email, password } = body as Record<string, unknown>;

				if (!email || !password) {
					res.writeHead(400);
					res.end(JSON.stringify({ message: 'Email and password required' }));
					return;
				}

				const user = users.get(email as string);
				if (!user || user.passwordHash !== hashPassword(password as string)) {
					res.writeHead(401);
					res.end(JSON.stringify({ message: 'Datos incorrectos' }));
					return;
				}

				const sessionId = generateSessionId();
				sessions.set(sessionId, { userId: email as string, email: email as string });

				const userNotes = Array.from(notes.values())
					.filter((n) => n.userId === email as string)
					.map((n) => ({ id: n.id, text: n.text }));

				res.setHeader('Set-Cookie', `sessionId=${sessionId}; Path=/; HttpOnly`);
				res.writeHead(200);
				res.end(JSON.stringify({ user: { email }, notes: userNotes }));
				return;
			}

			if (req.url === '/api/logout' && req.method === 'POST') {
				const sessionId = req.headers.cookie
					?.split(';')
					.map((c) => c.trim())
					.find((c) => c.startsWith('sessionId='))
					?.split('=')[1];

				if (sessionId) {
					sessions.delete(sessionId);
				}

				res.setHeader('Set-Cookie', `sessionId=; Path=/; HttpOnly; Max-Age=0`);
				res.writeHead(200);
				res.end(JSON.stringify({ message: 'Logged out' }));
				return;
			}

			if (req.url === '/api/notes' && req.method === 'POST') {
				const session = getSessionFromCookie(req.headers.cookie);
				if (!session) {
					res.writeHead(401);
					res.end(JSON.stringify({ message: 'Unauthorized' }));
					return;
				}

				const body = await parseJsonBody(req);
				const { text } = body as Record<string, unknown>;

				if (!text) {
					res.writeHead(400);
					res.end(JSON.stringify({ message: 'Text required' }));
					return;
				}

				const noteId = generateNoteId();
				notes.set(noteId, { id: noteId, text: text as string, userId: session.userId });

				const userNotes = Array.from(notes.values())
					.filter((n) => n.userId === session.userId)
					.map((n) => ({ id: n.id, text: n.text }));

				res.writeHead(200);
				res.end(JSON.stringify({ notes: userNotes }));
				return;
			}

			if (req.url?.startsWith('/api/notes/') && req.method === 'DELETE') {
				const session = getSessionFromCookie(req.headers.cookie);
				if (!session) {
					res.writeHead(401);
					res.end(JSON.stringify({ message: 'Unauthorized' }));
					return;
				}

				const noteId = req.url.split('/')[3];
				const note = notes.get(noteId);

				if (!note || note.userId !== session.userId) {
					res.writeHead(404);
					res.end(JSON.stringify({ message: 'Note not found' }));
					return;
				}

				notes.delete(noteId);

				const userNotes = Array.from(notes.values())
					.filter((n) => n.userId === session.userId)
					.map((n) => ({ id: n.id, text: n.text }));

				res.writeHead(200);
				res.end(JSON.stringify({ notes: userNotes }));
				return;
			}

			res.writeHead(404);
			res.end(JSON.stringify({ message: 'Not found' }));
		} catch (error) {
			res.writeHead(500);
			res.end(JSON.stringify({ message: 'Internal server error' }));
		}
	} else {
		res.writeHead(404);
		res.end(JSON.stringify({ message: 'Not found' }));
	}
});

