import { createServer } from 'node:http'
import { randomUUID } from 'node:crypto'
import { createHash } from 'node:crypto'

interface User {
  id: string
  email: string
  passwordHash: string
}

interface Note {
  id: string
  userId: string
  content: string
}

interface Session {
  userId: string
  token: string
}

const users: Map<string, User> = new Map()
const notes: Map<string, Note> = new Map()
const sessions: Map<string, Session> = new Map()

function hashPassword(password: string): string {
  return createHash('sha256').update(password).digest('hex')
}

function generateToken(): string {
  return randomUUID()
}

function parseJson(body: string): any {
  try {
    return JSON.parse(body)
  } catch {
    return null
  }
}

function getUserByToken(token: string): User | null {
  const session = sessions.get(token)
  if (!session) return null
  return users.get(session.userId) || null
}

const server = createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json')
  res.setHeader('Access-Control-Allow-Origin', '*')
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS')
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization')

  if (req.method === 'OPTIONS') {
    res.writeHead(200)
    res.end()
    return
  }

  if (req.url === '/api/signup' && req.method === 'POST') {
    let body = ''
    req.on('data', chunk => body += chunk)
    req.on('end', () => {
      const data = parseJson(body)
      if (!data || !data.email || !data.password) {
        res.writeHead(400)
        res.end(JSON.stringify({ message: 'Email y contraseña requeridos' }))
        return
      }

      const existingUser = Array.from(users.values()).find(u => u.email === data.email)
      if (existingUser) {
        res.writeHead(400)
        res.end(JSON.stringify({ message: 'El email ya está registrado' }))
        return
      }

      const userId = randomUUID()
      const passwordHash = hashPassword(data.password)
      const token = generateToken()

      users.set(userId, {
        id: userId,
        email: data.email,
        passwordHash
      })
      sessions.set(token, { userId, token })

      res.writeHead(201)
      res.end(JSON.stringify({ email: data.email, token }))
    })
    return
  }

  if (req.url === '/api/login' && req.method === 'POST') {
    let body = ''
    req.on('data', chunk => body += chunk)
    req.on('end', () => {
      const data = parseJson(body)
      if (!data || !data.email || !data.password) {
        res.writeHead(400)
        res.end(JSON.stringify({ message: 'Email y contraseña requeridos' }))
        return
      }

      const user = Array.from(users.values()).find(u => u.email === data.email)
      if (!user || user.passwordHash !== hashPassword(data.password)) {
        res.writeHead(401)
        res.end(JSON.stringify({ message: 'Datos incorrectos' }))
        return
      }

      const token = generateToken()
      sessions.set(token, { userId: user.id, token })

      res.writeHead(200)
      res.end(JSON.stringify({ email: user.email, token }))
    })
    return
  }

  if (req.url === '/api/notes' && req.method === 'GET') {
    const token = req.headers.authorization?.replace('Bearer ', '')
    const user = token ? getUserByToken(token) : null

    if (!user) {
      res.writeHead(401)
      res.end(JSON.stringify({ message: 'No autorizado' }))
      return
    }

    const userNotes = Array.from(notes.values())
      .filter(n => n.userId === user.id)
      .sort((a, b) => b.id.localeCompare(a.id))

    res.writeHead(200)
    res.end(JSON.stringify({ notes: userNotes }))
    return
  }

  if (req.url === '/api/notes' && req.method === 'POST') {
    const token = req.headers.authorization?.replace('Bearer ', '')
    const user = token ? getUserByToken(token) : null

    if (!user) {
      res.writeHead(401)
      res.end(JSON.stringify({ message: 'No autorizado' }))
      return
    }

    let body = ''
    req.on('data', chunk => body += chunk)
    req.on('end', () => {
      const data = parseJson(body)
      if (!data || !data.content || !data.content.trim()) {
        res.writeHead(400)
        res.end(JSON.stringify({ message: 'Contenido requerido' }))
        return
      }

      const noteId = randomUUID()
      const note: Note = {
        id: noteId,
        userId: user.id,
        content: data.content.trim()
      }

      notes.set(noteId, note)

      res.writeHead(201)
      res.end(JSON.stringify({ note }))
    })
    return
  }

  if (req.url?.match(/^\/api\/notes\/[^/]+$/) && req.method === 'DELETE') {
    const token = req.headers.authorization?.replace('Bearer ', '')
    const user = token ? getUserByToken(token) : null

    if (!user) {
      res.writeHead(401)
      res.end(JSON.stringify({ message: 'No autorizado' }))
      return
    }

    const noteId = req.url.split('/').pop()!
    const note = notes.get(noteId)

    if (!note || note.userId !== user.id) {
      res.writeHead(404)
      res.end(JSON.stringify({ message: 'Nota no encontrada' }))
      return
    }

    notes.delete(noteId)

    res.writeHead(200)
    res.end(JSON.stringify({ success: true }))
    return
  }

  res.writeHead(404)
  res.end(JSON.stringify({ message: 'No encontrado' }))
})

const PORT = process.env.PORT || 3000
server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`)
})

