        if (passwordHash !== user.passwordHash) {
          res.writeHead(401)
          res.end(JSON.stringify({ message: 'Datos incorrectos' }))
          return
        }

        const token = generateToken()
        sessions.set(token, { userId: email, email })

        res.writeHead(200)
        res.end(JSON.stringify({ email, token }))
      } catch (err) {
        res.writeHead(500)
        res.end(JSON.stringify({ message: 'Error interno' }))
      }
      return
    }
  }

  // Notes routes
  if (segments[0] === 'api' && segments[1] === 'notes') {
    const authHeader = req.headers.authorization
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401)
      res.end(JSON.stringify({ message: 'No autorizado' }))
      return
    }

    const token = authHeader.substring(7)
    const session = sessions.get(token)
    if (!session) {
      res.writeHead(401)
      res.end(JSON.stringify({ message: 'Token inválido' }))
      return
    }

    if (req.method === 'GET') {
      const userNotes = notes.get(session.userId) || []
      res.writeHead(200)
      res.end(JSON.stringify({ notes: userNotes }))
      return
    }

    if (req.method === 'POST') {
      try {
        const body = await parseBody(req)
        const { text } = body

        if (!text) {
          res.writeHead(400)
          res.end(JSON.stringify({ message: 'Texto requerido' }))
          return
        }

        const note: Note = {
          id: generateId(),
          userId: session.userId,
          text,
          createdAt: new Date().toISOString()
        }

        if (!notes.has(session.userId)) {
          notes.set(session.userId, [])
        }
        notes.get(session.userId)!.push(note)

        res.writeHead(201)
        res.end(JSON.stringify({ note }))
      } catch (err) {
        res.writeHead(500)
        res.end(JSON.stringify({ message: 'Error interno' }))
      }
      return
    }
  }

  res.writeHead(404)
  res.end(JSON.stringify({ message: 'Ruta no encontrada' }))
})

