import { createSignal, createMemo, Show, For } from 'solid-js';

type AuthState = { type: 'none' } | { type: 'authenticated'; email: string };

export default function App() {
  const [authState, setAuthState] = createSignal<AuthState>({ type: 'none' });
  const [email, setEmail] = createSignal('');
  const [password, setPassword] = createSignal('');
  const [error, setError] = createSignal('');
  const [notes, setNotes] = createSignal<string[]>([]);
  const [noteInput, setNoteInput] = createSignal('');

  const isAuthenticated = createMemo(() => authState().type === 'authenticated');
  const currentEmail = createMemo(() =>
    authState().type === 'authenticated' ? authState().email : ''
  );

  const handleSignup = async () => {
    setError('');
    if (!email() || !password()) {
      setError('Completa email y contraseña');
      return;
    }

    try {
      const res = await fetch('/api/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email(), password: password() }),
      });

      if (res.ok) {
        setAuthState({ type: 'authenticated', email: email() });
        setEmail('');
        setPassword('');
        await loadNotes();
      } else {
        const data = await res.json();
        setError(data.error || 'Error al crear cuenta');
      }
    } catch (err) {
      setError('Error de conexión');
    }
  };

  const handleLogin = async () => {
    setError('');
    if (!email() || !password()) {
      setError('Completa email y contraseña');
      return;
    }

    try {
      const res = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email(), password: password() }),
      });

      if (res.ok) {
        setAuthState({ type: 'authenticated', email: email() });
        setEmail('');
        setPassword('');
        await loadNotes();
      } else {
        setError('Datos incorrectos');
      }
    } catch (err) {
      setError('Error de conexión');
    }
  };

  const handleLogout = () => {
