import * as http from 'node:http';
import * as crypto from 'node:crypto';

interface User {
  email: string;
  passwordHash: string;
}

interface UserData {
  user: User;
  notes: string[];
}

const users: Map<string, UserData> = new Map();

function hashPassword(password: string): string {
  return crypto.createHash('sha256').update(password).digest('hex');
}

function parseJson(data: string): any {
  try {
    return JSON.parse(data);
  } catch {
    return null;
  }
}

async function handleRequest(
  req: http.IncomingMessage,
  res: http.ServerResponse
): Promise<void> {
  res.setHeader('Content-Type', 'application/json');

  if (req.url?.startsWith('/api/')) {
    const path = req.url.slice(5);

    if (path === 'signup' && req.method === 'POST') {
      let body = '';
      for await (const chunk of req) {
        body += chunk.toString();
      }

      const data = parseJson(body);
      if (!data || !data.email || !data.password) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email y contraseña requeridos' }));
        return;
      }

      if (users.has(data.email)) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email ya existe' }));
        return;
      }

      const user: User = {
        email: data.email,
        passwordHash: hashPassword(data.password),
      };

      users.set(data.email, { user, notes: [] });
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
      return;
    }

    if (path === 'login' && req.method === 'POST') {
      let body = '';
      for await (const chunk of req) {
        body += chunk.toString();
      }

      const data = parseJson(body);
      if (!data || !data.email || !data.password) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email y contraseña requeridos' }));
        return;
      }

      const userData = users.get(data.email);
      if (
        !userData ||
        userData.user.passwordHash !== hashPassword(data.password)
      ) {
        res.writeHead(401);
        res.end(JSON.stringify({ error: 'Datos incorrectos' }));
        return;
      }

      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
      return;
    }

    if (path === 'notes' && req.method === 'GET') {
      const email = req.headers['x-email'] as string;
      if (!email) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email requerido' }));
        return;
      }

      const userData = users.get(email);
      if (!userData) {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Usuario no encontrado' }));
        return;
      }

      res.writeHead(200);
      res.end(JSON.stringify({ notes: userData.notes }));
      return;
    }

    if (path === 'notes' && req.method === 'POST') {
      const email = req.headers['x-email'] as string;
      if (!email) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Email requerido' }));
        return;
      }

      let body = '';
      for await (const chunk of req) {
        body += chunk.toString();
      }

      const data = parseJson(body);
      if (!data || !data.note) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Nota requerida' }));
        return;
      }

      const userData = users.get(email);
      if (!userData) {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Usuario no encontrado' }));
        return;
      }

      userData.notes.push(data.note);
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
      return;
    }

    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Ruta no encontrada' }));
    return;
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'No encontrado' }));
}

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

const server = http.createServer(handleRequest);

server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

