import { createSignal, createMemo, Show, For } from "solid-js";

export default function App() {
  const [email, setEmail] = createSignal("");
  const [password, setPassword] = createSignal("");
  const [sessionEmail, setSessionEmail] = createSignal<string | null>(null);
  const [noteInput, setNoteInput] = createSignal("");
  const [notes, setNotes] = createSignal<string[]>([]);
  const [error, setError] = createSignal("");
  const [loading, setLoading] = createSignal(false);

  const isLoggedIn = createMemo(() => sessionEmail() !== null);

  const handleSignUp = async () => {
    setError("");
    if (!email() || !password()) {
      setError("Email y contraseña son requeridos");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email(), password: password() }),
      });
      const data = await res.json();
      if (res.ok) {
        setSessionEmail(email());
        setNotes([]);
        setEmail("");
        setPassword("");
      } else {
        setError(data.error || "Error al crear cuenta");
      }
    } catch (err) {
      setError("Error de conexión");
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async () => {
    setError("");
    if (!email() || !password()) {
      setError("Email y contraseña son requeridos");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email(), password: password() }),
      });
      const data = await res.json();
      if (res.ok) {
        setSessionEmail(email());
        setNotes(data.notes || []);
        setEmail("");
        setPassword("");
      } else {
        setError("Datos incorrectos");
      }
    } catch (err) {
      setError("Error de conexión");
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    setSessionEmail(null);
    setNotes([]);
    setEmail("");
    setPassword("");
    setError("");
    setNoteInput("");
  };

  const handleAddNote = async () => {
    if (!noteInput().trim()) return;
    setLoading(true);
    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: sessionEmail(),
          note: noteInput().trim(),
        }),
      });
      const data = await res.json();
      if (res.ok) {
        setNotes(data.notes || []);
        setNoteInput("");
      }
    } catch (err) {
      setError("Error al guardar nota");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div class="bg-white rounded-lg shadow-md p-8 w-full max-w-md">
        <Show
          when={!isLoggedIn()}
          fallback={
            <div>
              <h1 class="text-2xl font-bold text-gray-900 mb-6">
                Hola, {sessionEmail()}
              </h1>

              <button
                onClick={handleLogout}
                class="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-2 px-4 rounded mb-6"
              >
                Salir
              </button>

              <Show when={error()}>
                <div class="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded">
                  {error()}
                </div>
              </Show>

              <div class="mb-4">
                <input
                  type="text"
                  placeholder="Nota"
                  value={noteInput()}
                  onInput={(e) => setNoteInput(e.currentTarget.value)}
                  onKeyPress={(e) => {
                    if (e.key === "Enter") handleAddNote();
                  }}
                  class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <button
                onClick={handleAddNote}
                disabled={loading()}
                class="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-bold py-2 px-4 rounded mb-6"
              >
                Agregar
              </button>

              <div class="space-y-2">
                <h2 class="text-lg font-semibold text-gray-900">Tus notas:</h2>
                <Show when={notes().length === 0} fallback={<For each={notes()}>
                  {(note) => (
                    <div class="p-3 bg-gray-50 border border-gray-200 rounded">
                      <p class="text-gray-800">{note}</p>
                    </div>
                  )}
                </For>}>
                  <p class="text-gray-500">No hay notas aún</p>
                </Show>
              </div>
            </div>
          }
        >
          <h1 class="text-2xl font-bold text-gray-900 mb-6">Notas Privadas</h1>

          <Show when={error()}>
            <div class="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded">
              {error()}
            </div>
          </Show>

          <div class="mb-4">
            <input
              type="email"
              placeholder="Email"
              value={email()}
              onInput={(e) => setEmail(e.currentTarget.value)}
              class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div class="mb-6">
            <input
              type="password"
              placeholder="Contraseña"
              value={password()}
              onInput={(e) => setPassword(e.currentTarget.value)}
              onKeyPress={(e) => {
