import { createServer } from "node:http";
import { createHash } from "node:crypto";
import { URL } from "node:url";

interface User {
  email: string;
  passwordHash: string;
  notes: string[];
}

const users: Map<string, User> = new Map();

function hashPassword(password: string): string {
  return createHash("sha256").update(password).digest("hex");
}

function parseBody(req: any): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk: string) => {
      body += chunk;
    });
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  res.setHeader("Content-Type", "application/json");
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");

  if (req.method === "OPTIONS") {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || "", `http://${req.headers.host}`);
  const pathname = url.pathname;

  try {
    if (pathname === "/api/signup" && req.method === "POST") {
      const { email, password } = await parseBody(req);

      if (!email || !password) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: "Email y contraseña requeridos" }));
        return;
      }

      if (users.has(email)) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: "El email ya está registrado" }));
        return;
      }

      const passwordHash = hashPassword(password);
      users.set(email, {
        email,
        passwordHash,
        notes: [],
      });

      res.writeHead(200);
      res.end(JSON.stringify({ success: true, email }));
      return;
    }

    if (pathname === "/api/login" && req.method === "POST") {
      const { email, password } = await parseBody(req);

      if (!email || !password) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: "Email y contraseña requeridos" }));
        return;
      }

      const user = users.get(email);
      if (!user || user.passwordHash !== hashPassword(password)) {
        res.writeHead(401);
        res.end(JSON.stringify({ error: "Credenciales inválidas" }));
        return;
      }

      res.writeHead(200);
      res.end(JSON.stringify({ success: true, email, notes: user.notes }));
      return;
    }

    if (pathname === "/api/notes" && req.method === "POST") {
      const { email, note } = await parseBody(req);

      if (!email || !note) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: "Email y nota requeridos" }));
        return;
      }

      const user = users.get(email);
      if (!user) {
        res.writeHead(401);
        res.end(JSON.stringify({ error: "Usuario no autorizado" }));
        return;
      }

      user.notes.push(note);

      res.writeHead(200);
      res.end(JSON.stringify({ success: true, notes: user.notes }));
      return;
    }

    res.writeHead(404);
    res.end(JSON.stringify({ error: "Ruta no encontrada" }));
  } catch (error) {
    res.writeHead(500);
    res.end(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Error interno",
      })
    );
  }
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

