  return (
    <div className="flex flex-col gap-2">
      {cart.map((item) => (
        <CartItemRow key={item.product.id} item={item} onChangeQty={(d) => onChangeQty(item.product.id, d)} />
      ))}
      <Summary cart={cart} onClear={onClear} />
    </div>
  );
}

