import { Show } from "solid-js";
import type { CartItem } from "./data";

export default function Summary(props: { cart: CartItem[]; onClear: () => void }) {
  const total = () => props.cart.reduce((sum, i) => sum + i.product.price * i.qty, 0);
  const hasDiscount = () => total() > 50;
  const finalTotal = () => total() * 0.9;

  return (
    <div class="flex flex-col gap-2 border-t pt-2">
      <div class="flex items-center justify-between">
        <span class="font-bold">Total: ${total().toFixed(2)}</span>
        <button class="danger" onClick={props.onClear}>Vaciar carrito</button>
      </div>
      <Show when={hasDiscount()}>
        <div class="flex flex-col gap-1">
          <span class="text-green-600 font-semibold">Descuento 10%</span>
          <span class="font-bold">Total final: ${finalTotal().toFixed(2)}</span>
        </div>
      </Show>
    </div>
  );
}

