      </div>
      {hasDiscount() && (
        <div class="flex flex-col gap-1 text-sm">
          <span class="text-green-600 font-semibold">Descuento 10%</span>
          <span class="font-bold">Total final: ${discountedTotal().toFixed(2)}</span>
        </div>
      )}
    </div>
  );
}

