import { useState } from "react";
import type { Product } from "./data";
import SearchBox from "./SearchBox";
import ProductCard from "./ProductCard";

export default function Catalog({ products, onAdd }: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = useState("");
  const [sortByPrice, setSortByPrice] = useState(false);
  const shown = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
  const displayed = sortByPrice ? [...shown].sort((a, b) => a.price - b.price) : shown;

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-2 items-center">
        <SearchBox value={query} onChange={setQuery} />
        <button
          onClick={() => setSortByPrice(!sortByPrice)}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors whitespace-nowrap"
        >
          {sortByPrice ? "✓ Ordenar por precio" : "Ordenar por precio"}
        </button>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {displayed.map((p) => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
      {displayed.length === 0 && <span className="text-gray-500">Sin resultados</span>}
    </div>
  );
}

