files.app.art:
model Item {
  id: Number
  name: String
  amount: Number
  active: Bool
}

page Admin "/" {
  state page = "products"

  column gap=4 pad=4 {
    title "Panel" large
    Nav page=page onChange=(p => page = p)
    if page == "products" {
      ProductsPage
    } else if page == "customers" {
      CustomersPage
    } else if page == "orders" {
      OrdersPage
    } else if page == "suppliers" {
      SuppliersPage
    } else if page == "employees" {
      EmployeesPage
    } else if page == "categories" {
      CategoriesPage
    } else if page == "warehouses" {
      WarehousesPage
    } else if page == "invoices" {
      InvoicesPage
    } else if page == "coupons" {
      CouponsPage
    } else if page == "reviews" {
      ReviewsPage
    } else if page == "shipments" {
      ShipmentsPage
    } else if page == "payments" {
      PaymentsPage
    } else if page == "refunds" {
      RefundsPage
