import { createSignal } from "solid-js";
import { SEED, type Item } from "./data";
import EmployeesForm from "./EmployeesForm";
import EmployeesList from "./EmployeesList";

export default function EmployeesPage() {
  const [items, setItems] = createSignal<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items(), { id: Date.now(), name, amount, active: true }]);
  }

  function toggleEmployee(id: number) {
    setItems(items().map((item) => 
      item.id === id ? { ...item, active: !item.active } : item
    ));
  }

  return (
    <div class="flex flex-col gap-2">
      <h2 class="text-xl font-bold">Empleados</h2>
      <EmployeesForm onAdd={add} />
      <EmployeesList items={items()} onToggle={toggleEmployee} />
    </div>
  );
}

files.EmployeesRow.tsx:
import { createSignal } from "solid-js";
import type { Item } from "./data";

export default function EmployeesRow(props: { item: Item; onToggle: (id: number) => void }) {
  const [active, setActive] = createSignal(props.item.active);

  function handleToggle() {
    setActive(!active());
    props.onToggle(props.item.id);
  }

  return (
    <div class="flex gap-2 items-center">
      <span class="font-semibold">
        {props.item.name}
        {!active() && <span class="text-gray-500"> (inactivo)</span>}
      </span>
      <span>Sueldo: {props.item.amount}</span>
      <button onClick={handleToggle} class="text-sm px-2 py-1 bg-gray-200 rounded">
        Alternar
      </button>
    </div>
  );
}

